prompt --application/shared_components/logic/application_processes/carregar_nome_usuario
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(711934416694827963)
,p_process_sequence=>1
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Carregar_nome_usuario'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT UPPER(',
'               SUBSTR(',
'                 TRANSLATE(S.nom_pessoa,',
unistr('                   ''\00C1\00C0\00C2\00C3\00C4\00C9\00C8\00CA\00CB\00CD\00CC\00CE\00CF\00D3\00D2\00D4\00D5\00D6\00DA\00D9\00DB\00DC\00C7\00E1\00E0\00E2\00E3\00E4\00E9\00E8\00EA\00EB\00ED\00EC\00EE\00EF\00F3\00F2\00F4\00F5\00F6\00FA\00F9\00FB\00FC\00E7'','),
'                   ''AAAAAEEEEIIIIOOOOOUUUUCaaaaaeeeeiiiiooooouuuuc''),',
'                 1,',
'                 INSTR(S.nom_pessoa, '' '') - 1',
'               )',
'           ) || '' ('' || S.num_cpf || '')''',
'INTO :NOME_USUARIO',
'FROM dda.vinculo_sf s',
'JOIN dda.usuario_rede ur ON s.num_cpf = ur.num_cpf_pessoa',
'WHERE s.ind_vinculo_ativo = ''S''',
'    AND ur.nom_situacao_login_ad = ''ATIVO''',
'    AND LOWER(ur.txt_login_ad) = LOWER(:APP_USER);'))
,p_process_clob_language=>'PLSQL'
,p_version_scn=>558947598626
);
end;
/
prompt --application/shared_components/logic/application_processes/carregar_setor
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(734824856531792924)
,p_process_sequence=>1
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Carregar_setor'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT vs.sgl_orgao_exercicio INTO :SETOR_USUARIO',
'FROM dda.vinculo_sf vs ',
'JOIN dda.usuario_rede ur ON vs.num_cpf = ur.num_cpf_pessoa',
'WHERE vs.ind_vinculo_ativo = ''S''',
'    AND ur.nom_situacao_login_ad = ''ATIVO''',
'    AND LOWER(ur.txt_login_ad) = LOWER(:APP_USER);'))
,p_process_clob_language=>'PLSQL'
,p_version_scn=>558947607260
);
end;
