,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    DELETE FROM buf_hor_item',
'    WHERE fk_id_item IN (',
'        SELECT i.id_item',
'        FROM buf_item_solicitacao i',
'        JOIN buf_solicitacao s ',
'            ON s.id_solicitacao = i.fk_id_solicitacao',
'        WHERE s.ind_pendente = ''S''',
'          AND s.dat_criacao < TRUNC(SYSDATE)',
'    );',
'',
'    DELETE FROM buf_item_solicitacao',
'    WHERE fk_id_solicitacao IN (',
'        SELECT id_solicitacao',
'        FROM buf_solicitacao',
'        WHERE ind_pendente = ''S''',
'          AND dat_criacao < TRUNC(SYSDATE)',
'    );',
'',
'    DELETE FROM buf_solicitacao',
'    WHERE ind_pendente = ''S''',
'      AND dat_criacao < TRUNC(SYSDATE);',
'',
'    DELETE FROM buf_item_solicitacao_ext ie',
'    WHERE ie.fk_id_solicitacao_ext IN (',
'        SELECT se.id_solicitacao_ext',
'        FROM buf_solicitacao_ext se',
'        WHERE se.ind_pendente = ''S''',
'            AND se.dat_criacao < TRUNC(SYSDATE)',
'    );',
'',
'    DELETE FROM buf_solicitacao_ext se',
'    WHERE se.ind_pendente = ''S''',
'        AND se.dat_criacao < TRUNC(SYSDATE);',
'END;'))
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
