,p_process_name=>unistr('Update Descri\00E7\00E3o')
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_esps      APEX_T_VARCHAR2;',
'BEGIN',
'    UPDATE buf_descricao',
'    SET descricao = :P170_DESCRICAO,',
'        tempo_servico = :P170_TEMPO_SERVICO,',
'        valor = TO_NUMBER(',
'            REPLACE(',
'                :P170_VALOR_UNIT, ''R$ '', ''''',
'            )',
'        )',
'    WHERE id_desc = :P170_ID;',
'',
'    IF :P170_ESP_VALOR IS NOT NULL THEN',
'        v_esps := APEX_STRING.SPLIT(:P170_ESP_VALOR, '':'');',
'    ELSE',
'        v_esps := APEX_T_VARCHAR2();',
'    END IF;',
'',
'    FOR i IN 1 .. v_esps.COUNT LOOP',
'        DECLARE',
'            v_detalhe   VARCHAR2(4000);',
'        BEGIN',
'            v_detalhe := TRIM(v_esps(i));',
'',
'            IF v_detalhe NOT LIKE ''- %'' THEN',
'                v_detalhe := ''- '' || v_detalhe;',
'            END IF;',
'',
'            INSERT INTO buf_especificacao (',
'                detalhe,',
'                fk_id_desc',
'            ) VALUES (',
'                v_detalhe,',
'                :P170_ID',
'            );',
'        END;',
'    END LOOP;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(716944088800980766)
