wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(716947327833980799)
,p_plug_name=>unistr('Solicita\00E7\00F5es (Melhor visualiza\00E7\00E3o no 90%)')
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(711817305933954668)
,p_plug_display_sequence=>40
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_total_itens NUMBER;',
'    v_primeiro BOOLEAN;',
'',
'    v_url_asqualog  VARCHAR2(4000);',
'    v_url_deletar   VARCHAR2(4000);',
'    v_url_pag       VARCHAR2(4000);',
'',
'    v_limite        CONSTANT NUMBER := 15;',
'    v_pagina        NUMBER := NVL(:P200_PAGINA,1);',
'',
'    v_total_registros   NUMBER;',
'    v_total_paginas     NUMBER;',
'',
'    v_inicio        NUMBER;',
'    v_fim           NUMBER;',
'',
'    v_output        CLOB;',
'    v_temp          VARCHAR2(32767);',
'',
'    v_status_class         VARCHAR2(100);',
'    v_status_fatura_class  VARCHAR2(100);',
'',
'BEGIN',
'',
'    DBMS_LOB.CREATETEMPORARY(v_output, TRUE);',
'',
'    v_inicio := (v_pagina - 1) * v_limite + 1;',
'    v_fim    := v_pagina * v_limite;',
'',
'    SELECT COUNT(DISTINCT id_solicitacao)',
'    INTO v_total_registros',
'    FROM buf_solicitacao;',
'',
'    v_total_paginas := CEIL(v_total_registros / v_limite);',
'',
'    v_temp := ''',
'    <div class="table-scroll">',
'    <table class="tbl-buffet">',
'    '';',
'',
'    DBMS_LOB.APPEND(v_output, v_temp);',
'',
'    v_temp := ''',
'    <thead>',
'    <tr>',
'        <th></th>',
'        <th class="col-solicitante">Solicitante</th>',
unistr('        <th class="col-orgao">\00D3rg\00E3o</th>'),
'        <th class="col-evento">Evento</th>',
unistr('        <th class="col-servico">Servi\00E7o</th>'),
'        <th class="col-data">Data</th>',
'        <th class="col-pessoas">Pessoas</th>',
'        <th class="col-local">Local</th>',
'        <th class="col-status">Status</th>',
'        <th class="col-fatura">Fatura</th>',
'        <th class="col-status-fatura">Status Fatura</th>',
'        <th class="col-valor">Valor</th>',
'        <th class="col-detalhes">Detalhes</th>',
'    </tr>',
'    </thead>',
'    <tbody>',
'    '';',
'',
'    DBMS_LOB.APPEND(v_output, v_temp);',
'',
'    FOR sol IN (',
'',
'        SELECT *',
'        FROM (',
'',
'            SELECT',
'                s.id_solicitacao,',
'                s.nom_solicitante,',
'                s.sgl_orgao,',
'                s.nom_evento,',
'                MIN(i.dat_servico) primeira_data,',
'',
'                ROW_NUMBER() OVER (',
'                    ORDER BY MIN(i.dat_servico) DESC',
'                ) rn',
'',
'            FROM buf_solicitacao s',
'',
'            JOIN buf_item_solicitacao i',
'                ON i.fk_id_solicitacao = s.id_solicitacao',
'',
'            GROUP BY',
'                s.id_solicitacao,',
'                s.nom_solicitante,',
'                s.sgl_orgao,',
'                s.nom_evento',
'',
'        )',
'',
'        WHERE rn BETWEEN v_inicio AND v_fim',
'',
'    )',
'    LOOP',
'',
'        v_url_deletar := apex_util.prepare_url(',
'            ''f?p='' || :APP_ID || '':271:'' || :APP_SESSION ||',
'            ''::NO::P271_ID_SOLICITACAO:'' || sol.id_solicitacao',
'        );',
'',
'        SELECT COUNT(*)',
'        INTO v_total_itens',
'        FROM buf_item_solicitacao',
'        WHERE fk_id_solicitacao = sol.id_solicitacao;',
'',
'        v_primeiro := TRUE;',
'',
'        FOR item IN (',
'',
'            SELECT',
'                i.id_item,',
'                i.fk_id_desc || '' - '' || d.descricao descricao,',
'                i.dat_servico,',
'                i.qtd_pessoas,',
'                i.local,',
'                i.status,',
'                i.valor_item,',
'                i.fatura,',
'                i.status_fatura',
'',
'            FROM buf_item_solicitacao i',
'',
'            JOIN buf_descricao d',
'                ON d.id_desc = i.fk_id_desc',
'',
'            WHERE i.fk_id_solicitacao = sol.id_solicitacao',
'',
'        )',
'        LOOP',
'',
'            v_status_class :=',
'                CASE item.status',
'                    WHEN ''Contratado'' THEN ''status-verde''',
'                    WHEN ''Cancelado'' THEN ''status-vermelho''',
unistr('                    WHEN ''Em negocia\00E7\00E3o'' THEN ''status-amarelo'''),
'                END;',
'',
'            v_status_fatura_class :=',
'                CASE item.status_fatura',
'                    WHEN ''Pago'' THEN ''status-verde''',
'                    WHEN ''Faturado'' THEN ''status-azul''',
'                    WHEN ''A Faturar'' THEN ''status-laranja''',
'                END;',
'',
'            v_url_asqualog := apex_util.prepare_url(',
'                ''f?p='' || :APP_ID || '':270:'' || :APP_SESSION ||',
'                ''::NO::P270_ID_ITEM:'' || item.id_item',
'            );',
'',
'            v_temp := ''<tr>'';',
'            DBMS_LOB.APPEND(v_output, v_temp);',
'',
'            IF v_primeiro THEN',
'',
'                v_temp := ''',
'                    <td rowspan="''||v_total_itens||''" class="central">',
'',
'                        <a href="''||v_url_deletar||''"',
'                           class="t-Button t-Button--small t-Button--danger">',
'',
'                           <span class="fa fa-trash-o"></span>',
'',
'                        </a>',
'',
'                    </td>',
'                '';',
'',
'                DBMS_LOB.APPEND(v_output, v_temp);',
'',
'                v_temp := ''',
'                    <td rowspan="''||v_total_itens||''" class="col-solicitante">',
'                        ''||sol.nom_solicitante||''',
'                    </td>',
'                '';',
'',
'                DBMS_LOB.APPEND(v_output, v_temp);',
'',
'                v_temp := ''',
'                    <td rowspan="''||v_total_itens||''" class="col-orgao central">',
'                        ''||sol.sgl_orgao||''',
'                    </td>',
'                '';',
'',
'                DBMS_LOB.APPEND(v_output, v_temp);',
'',
'                v_temp := ''',
'                    <td rowspan="''||v_total_itens||''" class="col-evento">',
'                        ''||sol.nom_evento||''',
'                    </td>',
'                '';',
'',
'                DBMS_LOB.APPEND(v_output, v_temp);',
'',
'                v_primeiro := FALSE;',
'',
'            END IF;',
'',
'            v_temp := ''',
'                <td class="col-servico">',
'                    ''||item.descricao||''',
'                </td>',
'            '';',
'',
'            DBMS_LOB.APPEND(v_output, v_temp);',
'',
'            v_temp := ''',
'                <td class="col-data central">',
'                    ''||TO_CHAR(item.dat_servico,''DD/MM/YYYY'')||''',
'                </td>',
'            '';',
'',
'            DBMS_LOB.APPEND(v_output, v_temp);',
'',
'            v_temp := ''',
'                <td class="col-pessoas central">',
'                    ''||item.qtd_pessoas||''',
'                </td>',
'            '';',
'',
'            DBMS_LOB.APPEND(v_output, v_temp);',
'',
'            v_temp := ''',
'                <td class="col-local central">',
'                    ''||NVL(item.local,''-'')||''',
'                </td>',
'            '';',
'',
'            DBMS_LOB.APPEND(v_output, v_temp);',
'',
'            v_temp := ''',
'                <td class="col-status central">',
'',
'                    <span class="badge-status ''||v_status_class||''">',
'                        ''||item.status||''',
'                    </span>',
'',
'                </td>',
'            '';',
'',
'            DBMS_LOB.APPEND(v_output, v_temp);',
'',
'            v_temp := ''',
'                <td class="col-fatura central">',
'                    ''||NVL(item.fatura,''-'')||''',
'                </td>',
'            '';',
'',
'            DBMS_LOB.APPEND(v_output, v_temp);',
'',
'            v_temp := ''',
'                <td class="col-status-fatura central">',
'',
'                    <span class="badge-status ''||v_status_fatura_class||''">',
'',
'                        ''||NVL(item.status_fatura,''-'')||''',
'',
'                    </span>',
'',
'                </td>',
'            '';',
'',
'            DBMS_LOB.APPEND(v_output, v_temp);',
'',
'            v_temp := ''',
'                <td class="col-valor valor">',
'',
'                    R$ ''||',
'                    TO_CHAR(',
'                        item.valor_item,',
'                        ''FM999G999G990D00''',
'                    )||''',
'',
'                </td>',
'            '';',
'',
'            DBMS_LOB.APPEND(v_output, v_temp);',
'',
'            v_temp := ''',
'                <td class="col-detalhes central">',
'',
'                    <a href="''||v_url_asqualog||''"',
'                       class="t-Button t-Button--small">',
'',
'                       <span class="fa fa-eye"></span>',
'',
'                    </a>',
'',
'                </td>',
'            '';',
'',
'            DBMS_LOB.APPEND(v_output, v_temp);',
'',
'            v_temp := ''</tr>'';',
'',
'            DBMS_LOB.APPEND(v_output, v_temp);',
'',
'        END LOOP;',
'',
'        v_temp := ''',
'            <tr>',
'                <td colspan="13" class="separador"></td>',
'            </tr>',
'        '';',
'',
'        DBMS_LOB.APPEND(v_output, v_temp);',
'',
'    END LOOP;',
'',
'    v_temp := ''',
'        </tbody>',
'        </table>',
'        </div>',
'    '';',
'',
'    DBMS_LOB.APPEND(v_output, v_temp);',
'',
'    v_temp := ''',
'        <div style="margin-top:15px;text-align:center;">',
'    '';',
'',
'    DBMS_LOB.APPEND(v_output, v_temp);',
'',
'    FOR i IN 1..v_total_paginas LOOP',
'',
'        v_url_pag := apex_page.get_url(',
'            p_page   => :APP_PAGE_ID,',
'            p_items  => ''P200_PAGINA'',',
'            p_values => i',
'        );',
'',
'        IF i = v_pagina THEN',
'',
'            v_temp := ''',
'                <span class="t-Button t-Button--hot"',
'                      style="margin:0 4px;">',
'                    ''||i||''',
'                </span>',
'            '';',
'',
'        ELSE',
'',
'            v_temp := ''',
'                <a class="t-Button"',
'                   style="margin:0 4px;"',
'                   href="''||v_url_pag||''">',
'',
'                   ''||i||''',
'',
'                </a>',
'            '';',
'',
'        END IF;',
'',
'        DBMS_LOB.APPEND(v_output, v_temp);',
'',
'    END LOOP;',
'',
'    v_temp := ''</div>'';',
'',
'    DBMS_LOB.APPEND(v_output, v_temp);',
'',
'    RETURN v_output;',
'',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P200_ORGAO,P200_STATUS,P200_DATA_INI,P200_DAT_FIM,P200_TIP_SERVICO'
);
