wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(843893928260148767)
,p_plug_name=>unistr('Solicita\00E7\00F5es')
,p_region_name=>'solicitacoes'
,p_region_css_classes=>'solicitacoes'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(711807441892954664)
,p_plug_display_sequence=>50
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    s.id_solicitacao                                          AS "ID",',
'    s.nom_solicitante                                         AS "Solicitante",',
unistr('    s.sgl_orgao                                               AS "\00D3rg\00E3o",'),
'    s.nom_evento                                              AS "Evento",',
unistr('    d.descricao                                               AS "Tipo de Servi\00E7o",'),
'    i.dat_servico                                             AS "Data do Evento",',
'    i.local                                                   AS "Local do Evento",',
'    i.qtd_pessoas                                             AS "Qtd de Pessoas",',
'    i.valor_item                                              AS "Valor",',
'    i.dat_envio_senac                                         AS "Enviado ao SENAC em",',
unistr('    i.status                                                  AS "Status do Servi\00E7o",'),
unistr('    i.dat_envio_cardapio                                      AS "Envio do card\00E1pio",'),
unistr('    i.dat_aprovacao_cardapio                                  AS "Aprova\00E7\00E3o do card\00E1pio",'),
'    i.dat_pedido_ateste                                       AS "Pedido de Ateste",',
'    i.dat_ateste                                              AS "Ateste",',
'    i.fatura                                                  AS "Fatura",',
unistr('    i.prov_pagamento                                          AS "Provid\00EAncias de Pagamento",'),
'    i.status_fatura                                           AS "Status da Fatura",',
unistr('    i.pranchao                                                AS "Pranch\00E3o?",'),
unistr('    i.dat_pranchao                                            AS "Data de Solicita\00E7\00E3o do Pranch\00E3o",'),
unistr('    i.obs                                                     AS "Observa\00E7\00F5es"'),
'FROM buf_solicitacao s',
'JOIN buf_item_solicitacao i',
'    ON i.fk_id_solicitacao = s.id_solicitacao',
'JOIN buf_descricao d',
'    ON d.id_desc = i.fk_id_desc',
'WHERE 1 = 1',
'',
unistr('-- \00D3RG\00C3O (MULTISELECT)'),
'AND (',
'        :P200_ORGAO IS NULL',
'        OR',
'        INSTR(',
'            '':'' || REPLACE(:P200_ORGAO,'';'','':'') || '':'',',
'            '':'' || s.sgl_orgao || '':''',
'        ) > 0',
'    )',
'-- STATUS (MULTISELECT)',
'AND (',
'        :P200_STATUS IS NULL',
'        OR',
'        INSTR(',
'            '':'' || REPLACE(:P200_STATUS,'';'','':'') || '':'',',
'            '':'' || i.status || '':''',
'        ) > 0',
'    )',
unistr('-- TIPO SERVI\00C7O (MULTISELECT RETORNANDO ID_DESC)'),
'AND (',
'        :P200_TIP_SERVICO IS NULL',
'        OR',
'        INSTR(',
'            '':'' || REPLACE(:P200_TIP_SERVICO,'';'','':'') || '':'',',
'            '':'' || i.fk_id_desc || '':''',
'        ) > 0',
'    )',
unistr('-- DATA IN\00CDCIO'),
'AND (',
'        :P200_DATA_INI IS NULL',
'        OR',
'        TRUNC(i.dat_servico) >= TRUNC(TO_DATE(:P200_DATA_INI), ''DD/MM/YYYY'')',
'    )',
'-- DATA FIM',
'AND (',
'        :P200_DAT_FIM IS NULL',
'        OR',
'        TRUNC(i.dat_servico) <= TRUNC(TO_DATE(:P200_DAT_FIM), ''DD/MM/YYYY'')',
'    )',
'ORDER BY',
'    s.id_solicitacao DESC,',
'    i.dat_servico,',
'    i.id_item'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P200_ORGAO,P200_STATUS,P200_TIP_SERVICO,P200_DATA_INI,P200_DAT_FIM'
