wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1227479846243833966)
,p_plug_name=>unistr('Itens da Solicita\00E7\00E3o')
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(711807441892954664)
,p_plug_display_sequence=>60
,p_plug_new_grid_row=>false
,p_plug_new_grid_column=>false
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT i.id_item AS "ID",',
'    i.fk_id_solicitacao AS "FK",',
'    d.descricao AS "Item do Buffet",',
'    i.dat_servico AS "Data do Evento",',
'    i.qtd_pessoas AS "Quantidade de Itens",',
'    i.motivo_qtd AS "Justificativa da Qtd",',
'    i.valor_item AS "Valor R$",',
'    i.local AS "Local",',
unistr('    i.obs AS "Observa\00E7\00E3o",'),
'    LISTAGG(h.hor, ''<br>'')',
unistr('        WITHIN GROUP (ORDER BY h.hor) AS "Hor\00E1rios"'),
'FROM buf_item_solicitacao i',
'JOIN buf_descricao d ON i.fk_id_desc = d.id_desc',
'LEFT JOIN buf_hor_item h ON h.fk_id_item = i.id_item',
'WHERE fk_id_solicitacao = :P202_ID_SOLICITACAO',
'    AND EXISTS(',
'        SELECT 1',
'        FROM buf_hor_item h2',
'        WHERE h2.fk_id_item = i.id_item',
'    )',
'GROUP BY ',
'    i.id_item,',
'    i.fk_id_solicitacao,',
'    d.descricao,',
'    i.dat_servico,',
'    i.qtd_pessoas,',
'    i.motivo_qtd,',
'    i.valor_item,',
'    i.local,',
'    i.obs',
'ORDER BY i.dat_servico'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P202_ID_SOLICITACAO'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'MILLIMETERS'
,p_prn_paper_size=>'A4'
