begin
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(246107397135892290)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Salvar Primeira Parte'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_valor_item      NUMBER;',
'    v_qtd_disponivel  NUMBER;',
'    v_qtd             NUMBER;',
'    v_valor           NUMBER;',
'BEGIN',
'    SELECT tempo_servico',
'    INTO :P202_DURACAO',
'    FROM buf_descricao',
'    WHERE id_desc = :P202_ITEM;',
'',
'    SELECT valor, qtd_disponivel',
'    INTO v_valor_item, v_qtd_disponivel',
'    FROM buf_descricao',
'    WHERE id_desc = :P202_ITEM;',
'',
'    v_qtd := :P202_QTD_PESSOAS;',
'    v_valor := v_valor_item * v_qtd;',
'',
unistr('    -- Apenas informa caso a quantidade seja maior que a dispon\00EDvel'),
'    IF v_qtd > v_qtd_disponivel THEN',
'        apex_error.add_error(',
unistr('            p_message          => ''A quantidade solicitada \00E9 maior que a dispon\00EDvel ('' || v_qtd_disponivel || ''). O item ser\00E1 cadastrado normalmente.'','),
'            p_display_location => apex_error.c_inline_in_notification',
'        );',
'    ELSE',
'        -- Desconta do estoque apenas se houver quantidade suficiente',
'        UPDATE buf_descricao',
'        SET qtd_disponivel = qtd_disponivel - v_qtd',
'        WHERE id_desc = :P202_ITEM;',
'    END IF;',
'',
'    INSERT INTO buf_item_solicitacao (',
'        fk_id_solicitacao,',
'        fk_id_desc,',
'        dat_servico,',
'        qtd_pessoas,',
'        valor_item,',
'        status,',
'        local,',
'        obs,',
'        motivo_qtd',
'    ) VALUES (',
'        :P202_ID_SOLICITACAO,',
'        :P202_ITEM,',
'        :P202_DAT_SERVICO,',
'        :P202_QTD_PESSOAS,',
'        v_valor,',
unistr('        ''Em negocia\00E7\00E3o'','),
'        :P202_LOCAL,',
'        :P202_OBS,',
'        :P202_MOTIVO_QTD',
'    )',
'    RETURNING id_item INTO :P202_ID_ITEM;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(246100287437892282)
,p_internal_uid=>246107397135892290
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(246108178565892290)
,p_process_sequence=>20
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Deletar Itens sem Horario'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    -- 1) Repor quantidade na BUF_DESCRICAO',
'    UPDATE buf_descricao d',
'    SET d.qtd_disponivel = d.qtd_disponivel + (',
'        SELECT NVL(SUM(bis.qtd_pessoas), 0)',
'        FROM buf_item_solicitacao bis',
'        JOIN buf_solicitacao bs ON bs.id_solicitacao = bis.fk_id_solicitacao',
'        WHERE bis.fk_id_desc = d.id_desc',
'          AND bis.fk_id_solicitacao = :P202_ID_SOLICITACAO',
'          AND bs.ind_pendente = ''S''',
'          AND NOT EXISTS (',
'                SELECT 1',
'                FROM buf_hor_item bhi',
'                WHERE bhi.fk_id_item = bis.id_item',
'          )',
'    )',
'    WHERE EXISTS (',
'        SELECT 1',
'        FROM buf_item_solicitacao bis',
'        JOIN buf_solicitacao bs ON bs.id_solicitacao = bis.fk_id_solicitacao',
'        WHERE bis.fk_id_desc = d.id_desc',
'          AND bis.fk_id_solicitacao = :P202_ID_SOLICITACAO',
'          AND bs.ind_pendente = ''S''',
'          AND NOT EXISTS (',
'                SELECT 1',
'                FROM buf_hor_item bhi',
'                WHERE bhi.fk_id_item = bis.id_item',
'          )',
'    );',
'',
'    -- 2) Deletar os itens',
'    DELETE FROM buf_item_solicitacao bis',
'    WHERE bis.fk_id_solicitacao = :P202_ID_SOLICITACAO',
'      AND EXISTS (',
'          SELECT 1',
'          FROM buf_solicitacao bs',
'          WHERE bs.id_solicitacao = bis.fk_id_solicitacao',
'            AND bs.ind_pendente = ''S''',
'      )',
'      AND NOT EXISTS (',
'            SELECT 1',
'            FROM buf_hor_item bhi',
'            WHERE bhi.fk_id_item = bis.id_item',
'      );',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(246101410033892283)
,p_internal_uid=>246108178565892290
);
