wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(246454888513598952)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Confirmar Evento e Enviar e-mail'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_cnt_solicitacao NUMBER;',
'BEGIN',
'    SELECT COUNT(*)',
'      INTO v_cnt_solicitacao',
'      FROM buf_solicitacao',
'     WHERE id_solicitacao = :P203_ID_SOLICITACAO',
'       AND ind_pendente = ''S'';',
'',
'    IF v_cnt_solicitacao = 0 THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
unistr('            ''N\00E3o h\00E1 solicita\00E7\00E3o pendente para confirma\00E7\00E3o.'''),
'        );',
'    END IF;',
'',
unistr('    -- Marca como n\00E3o analisada'),
'    UPDATE buf_solicitacao',
'       SET ind_analisado = ''S'',',
'        ind_senac = ''S'',',
'        ind_feedback = ''S''',
'     WHERE id_solicitacao = :P203_ID_SOLICITACAO;',
'',
unistr('    -- Remove anexos tempor\00E1rios (caso ainda deseje)'),
'    DELETE',
'      FROM buf_anexo',
'     WHERE fk_id_solicitacao = :P203_ID_SOLICITACAO;',
'',
unistr('    -- Finaliza a solicita\00E7\00E3o'),
'    UPDATE buf_solicitacao',
'       SET ind_pendente = ''N''',
'     WHERE id_solicitacao = :P203_ID_SOLICITACAO;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>246454888513598952
);
end;
