wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(734748408540592374)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Deletar Item'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_status        buf_item_solicitacao.status%TYPE;',
'    v_qtd_pessoas   buf_item_solicitacao.qtd_pessoas%TYPE;',
'    v_id_desc       buf_item_solicitacao.fk_id_desc%TYPE;',
'BEGIN',
'    SELECT status, qtd_pessoas, fk_id_desc',
'    INTO v_status, v_qtd_pessoas, v_id_desc',
'    FROM buf_item_solicitacao',
'    WHERE id_item = :P270_ID_ITEM;',
'',
'    IF v_status <> ''Cancelado'' THEN',
'        UPDATE buf_descricao',
'        SET qtd_disponivel = qtd_disponivel + v_qtd_pessoas',
'        WHERE id_desc = v_id_desc;',
'    END IF;',
'',
'    DELETE FROM buf_item_solicitacao',
'    WHERE id_item = :P270_ID_ITEM;',
'END;',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(734748152570592372)
,p_internal_uid=>518870687134366717
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(843893575752148763)
,p_process_sequence=>20
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Atualizar Item'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_valor NUMBER;',
'    v_status        buf_item_solicitacao.status%TYPE;',
'    v_qtd_pessoas   buf_item_solicitacao.qtd_pessoas%TYPE;',
'    v_id_desc       buf_item_solicitacao.fk_id_desc%TYPE;',
'BEGIN',
'    v_valor :=',
'        TO_NUMBER(',
'            REPLACE(',
'                REPLACE(',
'                    REPLACE(:P270_VALOR,''R$'',''''),',
'                ''.'',''''),',
'            '','',''.''),',
'            ''999999999D99'',',
'            ''NLS_NUMERIC_CHARACTERS = ''''.,''''''',
'        );',
'    ',
'    SELECT qtd_pessoas, status, fk_id_desc',
'    INTO v_qtd_pessoas, v_status, v_id_desc',
'    FROM buf_item_solicitacao',
'    WHERE id_item = :P270_ID_ITEM;',
'',
'    IF v_status <> ''Cancelado'' AND :P270_STATUS_SERVICO = ''Cancelado'' THEN',
'        UPDATE buf_descricao',
'        SET qtd_disponivel = qtd_disponivel + v_qtd_pessoas',
'        WHERE id_desc = v_id_desc;',
'    END IF;',
'',
'    UPDATE buf_item_solicitacao',
'    SET fk_id_desc = :P270_SERVICO,',
'        dat_servico = :P270_DATA_EVENTO,',
'        qtd_pessoas = :P270_QTD,',
'        valor_item = v_valor,',
'        local = :P270_LOCAL,',
'',
'        dat_envio_senac = :P270_DAT_SENAC,',
'        dat_envio_cardapio = :P270_DAT_CARDAPIO,',
'        dat_aprovacao_cardapio = :P270_APROV_CARDAPIO,',
'        dat_pedido_ateste = :P270_ATESTE_ASQ,',
'        dat_ateste = :P270_ATESTE_DEM,',
'',
'        status = :P270_STATUS_SERVICO,',
'        fatura = :P270_FATURA,',
'        status_fatura = :P270_STATUS_FATURA,',
'',
'        prov_pagamento = :P270_PROV_PAGAMENTO,',
'        pranchao = :P270_PRANCHAO,',
'        dat_pranchao = :P270_DAT_PRANCHAO,',
'',
'        obs = :P270_OBS',
'    WHERE id_item = :P270_ID_ITEM;',
'',
'    COMMIT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(843893517701148762)
,p_internal_uid=>628015854345923106
);
end;
