'BEGIN',
'    UPDATE buf_descricao d',
'    SET qtd_disponivel = qtd_disponivel + (',
'        SELECT NVL(SUM(bis.qtd_pessoas), 0)',
'        FROM buf_item_solicitacao bis',
'        WHERE bis.fk_id_desc = d.id_desc',
'            AND bis.fk_id_solicitacao = :P271_ID_SOLICITACAO',
'            AND bis.status <> ''Cancelado''',
'    )',
'    WHERE EXISTS (',
'        SELECT 1',
'        FROM buf_item_solicitacao bis',
'        WHERE bis.fk_id_desc = d.id_desc',
'            AND bis.fk_id_solicitacao = :P271_ID_SOLICITACAO',
