'    DELETE FROM buf_hor_item',
'    WHERE fk_id_item IN (',
'        SELECT id_item',
'        FROM buf_item_solicitacao',
'        WHERE fk_id_solicitacao = :P271_ID_SOLICITACAO',
'    );',
'',
'    DELETE FROM buf_item_solicitacao',
'    WHERE fk_id_solicitacao = :P271_ID_SOLICITACAO;',
'',
'    DELETE FROM buf_solicitacao',
'    WHERE id_solicitacao = :P271_ID_SOLICITACAO;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
