'BEGIN',
'    SELECT valor INTO v_valor_item',
'    FROM buf_descricao',
'    WHERE id_desc = :P275_ITEM;',
'',
'    v_qtd := :P275_QTD_PESSOAS;',
'',
'    v_valor := v_valor_item * v_qtd;',
'',
'    :P275_VALOR := ''R$ '' || v_valor;',
'END;'))
