wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(754710404569073780)
,p_plug_name=>'Todos os Meus Eventos'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(711817305933954668)
,p_plug_display_sequence=>30
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_total_itens NUMBER;',
'    v_primeiro BOOLEAN;',
'',
'    v_url_asqualog  CLOB;',
'    v_url_deletar   CLOB;',
'',
'    v_limite        CONSTANT NUMBER := 15;',
'    v_pagina        NUMBER := NVL(:P300_PAGINA,1);',
'    v_total_registros   NUMBER;',
'    v_total_paginas     NUMBER;',
'',
'    v_inicio        NUMBER;',
'    v_fim           NUMBER;',
'    v_existe        NUMBER;',
'BEGIN',
'',
'    SELECT COUNT(DISTINCT s.id_solicitacao) INTO v_existe',
'    FROM buf_solicitacao s',
'    JOIN buf_item_solicitacao i',
'        ON i.fk_id_solicitacao = s.id_solicitacao',
'    WHERE s.sgl_orgao = :SETOR_USUARIO;',
'',
'    IF v_existe = 0 THEN',
'        htp.p(''',
'            <div class="t-Alert t-Alert--warning t-Alert--horizontal t-Alert--defaultIcons">',
'                <div class="t-Alert-wrap">',
'                    <div class="t-Alert-icon">',
'                        <span class="t-Icon fa fa-info-circle"></span>',
'                    </div>',
'                    <div class="t-Alert-content">',
'                        <div class="t-Alert-header">',
'                            <h2 class="t-Alert-title">',
unistr('                                N\00E3o h\00E1 itens cadastrados para este setor.'),
'                            </h2>',
'                        </div>',
'                    </div>',
'                </div>',
'            </div>',
'        '');',
'    ELSE',
'        v_inicio := (v_pagina - 1) * v_limite + 1;',
'        v_fim    := v_pagina * v_limite;',
'',
'        SELECT COUNT(DISTINCT s.id_solicitacao) INTO v_total_registros',
'        FROM buf_solicitacao s',
'        JOIN buf_item_solicitacao i',
'            ON i.fk_id_solicitacao = s.id_solicitacao',
'        WHERE s.sgl_orgao = :SETOR_USUARIO;',
'',
'        v_total_paginas := CEIL(v_total_registros / v_limite);',
'',
'        htp.p(''<table class="tbl-buffet">'');',
'',
'        htp.p(''',
'        <thead>',
'        <tr>',
'            <th></th>',
'            <th class="col-solicitante">Solicitante</th>',
unistr('            <th class="col-orgao">\00D3rg\00E3o</th>'),
'            <th class="col-evento">Evento</th>',
unistr('            <th class="col-servico">Servi\00E7o</th>'),
'            <th class="col-data">Data</th>',
'            <th class="col-pessoas">Pessoas</th>',
'            <th class="col-local">Local</th>',
'            <th class="col-status">Status</th>',
'            <th class="col-valor">Valor</th>',
'            <th class="col-detalhes">Detalhes</th>',
'        </tr>',
'        </thead>',
'        <tbody>',
'        '');',
'',
'        FOR sol IN (',
'            SELECT *',
'            FROM (',
'                SELECT',
'                    s.id_solicitacao,',
'                    s.nom_solicitante,',
'                    s.sgl_orgao,',
'                    s.nom_evento,',
'                    MIN(i.dat_servico) AS primeira_data,',
'                    ROW_NUMBER() OVER (ORDER BY MIN(i.dat_servico) DESC) rn',
'                FROM buf_solicitacao s',
'                JOIN buf_item_solicitacao i',
'                    ON i.fk_id_solicitacao = s.id_solicitacao',
'                WHERE s.sgl_orgao = :SETOR_USUARIO',
'                GROUP BY',
'                    s.id_solicitacao,',
'                    s.nom_solicitante,',
'                    s.sgl_orgao,',
'                    s.nom_evento',
'            )',
'            WHERE rn BETWEEN v_inicio AND v_fim',
'        )',
'        LOOP',
'            v_url_deletar := apex_util.prepare_url(',
'                    ''f?p='' || :APP_ID || '':372:'' || :APP_SESSION ||',
'                    ''::NO::P372_ID_SOLICITACAO:'' || sol.id_solicitacao',
'                );',
'',
'            SELECT COUNT(*)',
'            INTO v_total_itens',
'            FROM buf_item_solicitacao',
'            WHERE fk_id_solicitacao = sol.id_solicitacao;',
'',
'            v_primeiro := TRUE;',
'',
'            FOR item IN (',
'                SELECT',
'                    i.id_item,',
'                    i.fk_id_desc || '' - '' || d.descricao AS descricao,',
'                    i.dat_servico,',
'                    i.qtd_pessoas,',
'                    i.local,',
'                    i.status,',
'                    i.valor_item',
'                FROM buf_item_solicitacao i',
'                JOIN buf_descricao d',
'                    ON d.id_desc = i.fk_id_desc',
'                WHERE i.fk_id_solicitacao = sol.id_solicitacao',
'            )',
'            LOOP',
'',
'                v_url_asqualog := apex_util.prepare_url(',
'                    ''f?p='' || :APP_ID || '':371:'' || :APP_SESSION ||',
'                    ''::NO::P371_ID_ITEM:'' || item.id_item',
'                );',
'',
'                htp.p(''<tr>'');',
'',
'                IF v_primeiro THEN',
'',
'                    htp.p(',
'                        ''<td rowspan="''||v_total_itens||''" class="central">',
'                            <a href="''||v_url_deletar||''"',
'                               class="t-Button t-Button--small t-Button--danger">',
'                               <span class="fa fa-trash-o"></span>',
'                            </a>',
'                         </td>''',
'                    );',
'',
'                    htp.p(''<td rowspan="''||v_total_itens||''" class="col-solicitante">''||sol.nom_solicitante||''</td>'');',
'                    htp.p(''<td rowspan="''||v_total_itens||''" class="col-orgao central">''||sol.sgl_orgao||''</td>'');',
'                    htp.p(''<td rowspan="''||v_total_itens||''" class="col-evento">''||sol.nom_evento||''</td>'');',
'',
'                    v_primeiro := FALSE;',
'',
'                END IF;',
'',
'                htp.p(''<td class="col-servico">''||item.descricao||''</td>'');',
'',
'                htp.p(''<td class="col-data central">''||',
'                TO_CHAR(item.dat_servico,''DD/MM/YYYY'')||',
'                ''</td>'');',
'',
'                htp.p(''<td class="col-pessoas central">''||',
'                item.qtd_pessoas||',
'                ''</td>'');',
'',
'                htp.p(''<td class="col-local central">''||',
'                item.local||',
'                ''</td>'');',
'',
'                htp.p(''<td class="col-status central">''||',
'                item.status||',
'                ''</td>'');',
'',
'                htp.p(''<td class="col-valor valor">R$ ''||',
'                TO_CHAR(item.valor_item,''FM999G999G990D00'')||',
'                ''</td>'');',
'',
'                IF item.status <> ''Cancelado'' THEN',
'                    htp.p(',
'                        ''<td class="col-detalhes central">',
'                            <a href="''||v_url_asqualog||''"',
'                               class="t-Button t-Button--small">',
'                               <span class="fa fa-eye"></span>',
'                            </a>',
'                        </td>''',
'                    );',
'                ELSE',
'                    htp.p(''<td class="col-detalhes central"></td>'');',
'                END IF;',
'',
'                htp.p(''</tr>'');',
'',
'            END LOOP;',
'',
'            htp.p(''',
'                <tr>',
'                    <td colspan="11" class="separador"></td>',
'                </tr>',
'            '');',
'',
'        END LOOP;',
'',
'        htp.p(''</tbody></table>'');',
'',
'        DECLARE',
'            v_url_pag VARCHAR2(4000);',
'        BEGIN',
'',
'            htp.p(''<div style="margin-top:15px;text-align:center;">'');',
'',
'            FOR i IN 1..v_total_paginas LOOP',
'',
'                v_url_pag := apex_page.get_url(',
'                    p_page   => :APP_PAGE_ID,',
'                    p_items  => ''P300_PAGINA'',',
'                    p_values => i',
'                );',
'',
'                IF i = v_pagina THEN',
'                    htp.p(',
'                        ''<span class="t-Button t-Button--hot" ',
'                               style="margin:0 4px;">''||i||''</span>''',
'                    );',
'                ELSE',
'                    htp.p(',
'                        ''<a class="t-Button" ',
'                            style="margin:0 4px;"',
'                            href="''||v_url_pag||''">''||i||''</a>''',
'                    );',
'                END IF;',
'            END LOOP;',
'            htp.p(''</div>'');',
'        END;',
'    END IF;',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(775767488813239161)
,p_plug_name=>unistr('Eventos pass\00EDveis a Feedback (Realizados)')
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(711817305933954668)
,p_plug_display_sequence=>50
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_total_itens NUMBER;',
'    v_primeiro BOOLEAN;',
'',
'    v_url_asqualog  CLOB;',
'    v_url_deletar   CLOB;',
'    v_url_feedback  CLOB;',
'',
'    v_limite        CONSTANT NUMBER := 15;',
'    v_pagina        NUMBER := NVL(:P300_PAGINA,1);',
'    v_total_registros   NUMBER;',
'    v_total_paginas     NUMBER;',
'',
'    v_inicio        NUMBER;',
'    v_fim           NUMBER;',
'    v_existe        NUMBER;',
'BEGIN',
'',
'    SELECT COUNT(DISTINCT s.id_solicitacao) INTO v_existe',
'    FROM buf_solicitacao s',
'    JOIN buf_item_solicitacao i',
'        ON i.fk_id_solicitacao = s.id_solicitacao',
'    WHERE s.sgl_orgao = :SETOR_USUARIO',
'      AND s.ind_analisado = ''S''',
'      AND s.aprovacao_dger IS NOT NULL',
'      AND i.status = ''Contratado''',
'      AND NOT EXISTS (',
'          SELECT 1',
'          FROM buf_item_solicitacao i2',
'          WHERE i2.fk_id_solicitacao = s.id_solicitacao',
'            AND i2.status = ''Contratado''',
'            AND TRUNC(i2.dat_servico) >= TRUNC(SYSDATE)',
'      );',
'',
'    IF v_existe = 0 THEN',
'        htp.p(''',
'            <div class="t-Alert t-Alert--warning t-Alert--horizontal t-Alert--defaultIcons">',
'                <div class="t-Alert-wrap">',
'                    <div class="t-Alert-icon">',
'                        <span class="t-Icon fa fa-info-circle"></span>',
'                    </div>',
'                    <div class="t-Alert-content">',
'                        <div class="t-Alert-header">',
'                            <h2 class="t-Alert-title">',
unistr('                                N\00E3o h\00E1 eventos conclu\00EDdos contratados para este setor.'),
'                            </h2>',
'                        </div>',
'                    </div>',
'                </div>',
'            </div>',
'        '');',
'    ELSE',
'        v_inicio := (v_pagina - 1) * v_limite + 1;',
'        v_fim    := v_pagina * v_limite;',
'',
'        SELECT COUNT(DISTINCT s.id_solicitacao) INTO v_total_registros',
'        FROM buf_solicitacao s',
'        JOIN buf_item_solicitacao i',
'            ON i.fk_id_solicitacao = s.id_solicitacao',
'        WHERE s.sgl_orgao = :SETOR_USUARIO',
'          AND s.ind_analisado = ''S''',
'          AND s.aprovacao_dger IS NOT NULL',
'          AND i.status = ''Contratado''',
'          AND NOT EXISTS (',
'              SELECT 1',
'              FROM buf_item_solicitacao i2',
'              WHERE i2.fk_id_solicitacao = s.id_solicitacao',
'                AND i2.status = ''Contratado''',
'                AND TRUNC(i2.dat_servico) >= TRUNC(SYSDATE)',
'          );',
'',
'        v_total_paginas := CEIL(v_total_registros / v_limite);',
'',
'        htp.p(''<table class="tbl-buffet">'');',
'',
'        htp.p(''',
'        <thead>',
'        <tr>',
'            <th></th>',
'            <th class="col-solicitante">Solicitante</th>',
unistr('            <th class="col-orgao">\00D3rg\00E3o</th>'),
'            <th class="col-evento">Evento</th>',
unistr('            <th class="col-servico">Servi\00E7o</th>'),
'            <th class="col-data">Data</th>',
'            <th class="col-pessoas">Pessoas</th>',
'            <th class="col-local">Local</th>',
'            <th class="col-status">Status</th>',
'            <th class="col-valor">Valor</th>',
'            <th class="col-detalhes">Detalhes</th>',
'        </tr>',
'        </thead>',
'        <tbody>',
'        '');',
'',
'        FOR sol IN (',
'            SELECT *',
'            FROM (',
'                SELECT',
'                    s.id_solicitacao,',
'                    s.nom_solicitante,',
'                    s.sgl_orgao,',
'                    s.nom_evento,',
'                    s.ind_feedback,',
'                    MIN(i.dat_servico) AS primeira_data,',
'                    ROW_NUMBER() OVER (ORDER BY MIN(i.dat_servico) DESC) rn',
'                FROM buf_solicitacao s',
'                JOIN buf_item_solicitacao i',
'                    ON i.fk_id_solicitacao = s.id_solicitacao',
'                WHERE s.sgl_orgao = :SETOR_USUARIO',
'                  AND s.ind_analisado = ''S''',
'                  AND s.aprovacao_dger IS NOT NULL',
'                  AND i.status = ''Contratado''',
'                  AND NOT EXISTS (',
'                      SELECT 1',
'                      FROM buf_item_solicitacao i2',
'                      WHERE i2.fk_id_solicitacao = s.id_solicitacao',
'                        AND i2.status = ''Contratado''',
'                        AND TRUNC(i2.dat_servico) >= TRUNC(SYSDATE)',
'                  )',
'                GROUP BY',
'                    s.id_solicitacao,',
'                    s.nom_solicitante,',
'                    s.sgl_orgao,',
'                    s.nom_evento,',
'                    s.ind_feedback',
'            )',
'            WHERE rn BETWEEN v_inicio AND v_fim',
'        )',
'        LOOP',
'            v_url_deletar := apex_util.prepare_url(',
'                    ''f?p='' || :APP_ID || '':372:'' || :APP_SESSION ||',
'                    ''::NO::P372_ID_SOLICITACAO:'' || sol.id_solicitacao',
'                );',
'',
'            v_url_feedback := apex_util.prepare_url(',
'                    ''f?p='' || :APP_ID || '':700:'' || :APP_SESSION ||',
'                    ''::NO::P700_ID_SOLICITACAO:'' || sol.id_solicitacao',
'                );',
'',
'            SELECT COUNT(*)',
'            INTO v_total_itens',
'            FROM buf_item_solicitacao',
'            WHERE fk_id_solicitacao = sol.id_solicitacao',
'              AND status = ''Contratado'';',
'',
'            v_primeiro := TRUE;',
'',
'            FOR item IN (',
'                SELECT',
'                    i.id_item,',
'                    i.fk_id_desc || '' - '' || d.descricao AS descricao,',
'                    i.dat_servico,',
'                    i.qtd_pessoas,',
'                    i.local,',
'                    i.status,',
'                    i.valor_item',
'                FROM buf_item_solicitacao i',
'                JOIN buf_descricao d',
'                    ON d.id_desc = i.fk_id_desc',
'                WHERE i.fk_id_solicitacao = sol.id_solicitacao',
'                  AND i.status = ''Contratado''',
'            )',
'            LOOP',
'',
'                v_url_asqualog := apex_util.prepare_url(',
'                    ''f?p='' || :APP_ID || '':371:'' || :APP_SESSION ||',
'                    ''::NO::P371_ID_ITEM:'' || item.id_item',
'                );',
'',
'                htp.p(''<tr>'');',
'',
'                IF v_primeiro THEN',
'',
'                    IF sol.ind_feedback = ''S'' THEN',
'                        htp.p(',
'                            ''<td rowspan="''||v_total_itens||''" class="central">',
'                                <span class="fa fa-check" style="color:#28a745;"></span>',
'                             </td>''',
'                        );',
'                    ELSE',
'                        htp.p(',
'                            ''<td rowspan="''||v_total_itens||''" class="central">',
'                                <a href="''||v_url_feedback||''" title="Responder feedback">',
'                                    <span class="fa fa-list-alt fa-2x" style="color:#007bff;"></span>',
'                                </a>',
'                             </td>''',
'                        );',
'                    END IF;',
'',
'                    htp.p(''<td rowspan="''||v_total_itens||''" class="col-solicitante">''||sol.nom_solicitante||''</td>'');',
'                    htp.p(''<td rowspan="''||v_total_itens||''" class="col-orgao central">''||sol.sgl_orgao||''</td>'');',
'                    htp.p(''<td rowspan="''||v_total_itens||''" class="col-evento">''||sol.nom_evento||''</td>'');',
'',
'                    v_primeiro := FALSE;',
'',
'                END IF;',
'',
'                htp.p(''<td class="col-servico">''||item.descricao||''</td>'');',
'',
'                htp.p(''<td class="col-data central">''||',
'                TO_CHAR(item.dat_servico,''DD/MM/YYYY'')||',
'                ''</td>'');',
'',
'                htp.p(''<td class="col-pessoas central">''||',
'                item.qtd_pessoas||',
'                ''</td>'');',
'',
'                htp.p(''<td class="col-local central">''||',
'                item.local||',
'                ''</td>'');',
'',
'                htp.p(''<td class="col-status central">''||',
'                item.status||',
'                ''</td>'');',
'',
'                htp.p(''<td class="col-valor valor">R$ ''||',
'                TO_CHAR(item.valor_item,''FM999G999G990D00'')||',
'                ''</td>'');',
'',
'                IF item.status <> ''Cancelado'' THEN',
'                    htp.p(',
'                        ''<td class="col-detalhes central">',
'                            <a href="''||v_url_asqualog||''"',
'                               class="t-Button t-Button--small">',
'                               <span class="fa fa-eye"></span>',
'                            </a>',
'                        </td>''',
'                    );',
'                ELSE',
'                    htp.p(''<td class="col-detalhes central"></td>'');',
'                END IF;',
'',
'                htp.p(''</tr>'');',
'',
'            END LOOP;',
'',
'            htp.p(''',
'                <tr>',
'                    <td colspan="11" class="separador"></td>',
'                </tr>',
'            '');',
'',
'        END LOOP;',
'',
'        htp.p(''</tbody></table>'');',
'',
'        DECLARE',
'            v_url_pag VARCHAR2(4000);',
'        BEGIN',
'',
'            htp.p(''<div style="margin-top:15px;text-align:center;">'');',
'',
'            FOR i IN 1..v_total_paginas LOOP',
'',
'                v_url_pag := apex_page.get_url(',
'                    p_page   => :APP_PAGE_ID,',
'                    p_items  => ''P300_PAGINA'',',
'                    p_values => i',
'                );',
'',
'                IF i = v_pagina THEN',
'                    htp.p(',
'                        ''<span class="t-Button t-Button--hot" ',
'                               style="margin:0 4px;">''||i||''</span>''',
'                    );',
'                ELSE',
'                    htp.p(',
'                        ''<a class="t-Button" ',
'                            style="margin:0 4px;"',
'                            href="''||v_url_pag||''">''||i||''</a>''',
'                    );',
'                END IF;',
'            END LOOP;',
'            htp.p(''</div>'');',
'        END;',
'    END IF;',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(775767567934239162)
,p_plug_name=>'Eventos a serem Realizados (Contratados)'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(711817305933954668)
,p_plug_display_sequence=>40
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_total_itens NUMBER;',
'    v_primeiro BOOLEAN;',
'',
'    v_url_asqualog  CLOB;',
'    v_url_deletar   CLOB;',
'',
'    v_limite        CONSTANT NUMBER := 15;',
'    v_pagina        NUMBER := NVL(:P300_PAGINA,1);',
'    v_total_registros   NUMBER;',
'    v_total_paginas     NUMBER;',
'',
'    v_inicio        NUMBER;',
'    v_fim           NUMBER;',
'    v_existe        NUMBER;',
'BEGIN',
'',
'    SELECT COUNT(DISTINCT s.id_solicitacao) INTO v_existe',
'    FROM buf_solicitacao s',
'    JOIN buf_item_solicitacao i',
'        ON i.fk_id_solicitacao = s.id_solicitacao',
'    WHERE s.sgl_orgao = :SETOR_USUARIO',
'      AND i.status = ''Contratado''',
'      AND EXISTS (',
'          SELECT 1',
'          FROM buf_item_solicitacao i2',
'          WHERE i2.fk_id_solicitacao = s.id_solicitacao',
'            AND i2.status = ''Contratado''',
'            AND TRUNC(i2.dat_servico) >= TRUNC(SYSDATE)',
'      );',
'',
'    IF v_existe = 0 THEN',
'        htp.p(''',
'            <div class="t-Alert t-Alert--warning t-Alert--horizontal t-Alert--defaultIcons">',
'                <div class="t-Alert-wrap">',
'                    <div class="t-Alert-icon">',
'                        <span class="t-Icon fa fa-info-circle"></span>',
'                    </div>',
'                    <div class="t-Alert-content">',
'                        <div class="t-Alert-header">',
'                            <h2 class="t-Alert-title">',
unistr('                                N\00E3o h\00E1 eventos pendentes contratados para este setor.'),
'                            </h2>',
'                        </div>',
'                    </div>',
'                </div>',
'            </div>',
'        '');',
'    ELSE',
'        v_inicio := (v_pagina - 1) * v_limite + 1;',
'        v_fim    := v_pagina * v_limite;',
'',
'        SELECT COUNT(DISTINCT s.id_solicitacao) INTO v_total_registros',
'        FROM buf_solicitacao s',
'        JOIN buf_item_solicitacao i',
'            ON i.fk_id_solicitacao = s.id_solicitacao',
'        WHERE s.sgl_orgao = :SETOR_USUARIO',
'          AND i.status = ''Contratado''',
'          AND EXISTS (',
'              SELECT 1',
'              FROM buf_item_solicitacao i2',
'              WHERE i2.fk_id_solicitacao = s.id_solicitacao',
'                AND i2.status = ''Contratado''',
'                AND TRUNC(i2.dat_servico) >= TRUNC(SYSDATE)',
'          );',
'',
'        v_total_paginas := CEIL(v_total_registros / v_limite);',
'',
'        htp.p(''<table class="tbl-buffet">'');',
'',
'        htp.p(''',
'        <thead>',
'        <tr>',
'            <th></th>',
'            <th class="col-solicitante">Solicitante</th>',
unistr('            <th class="col-orgao">\00D3rg\00E3o</th>'),
'            <th class="col-evento">Evento</th>',
unistr('            <th class="col-servico">Servi\00E7o</th>'),
'            <th class="col-data">Data</th>',
'            <th class="col-pessoas">Pessoas</th>',
'            <th class="col-local">Local</th>',
'            <th class="col-status">Status</th>',
'            <th class="col-valor">Valor</th>',
'            <th class="col-detalhes">Detalhes</th>',
'        </tr>',
'        </thead>',
'        <tbody>',
'        '');',
'',
'        FOR sol IN (',
'            SELECT *',
'            FROM (',
'                SELECT',
'                    s.id_solicitacao,',
'                    s.nom_solicitante,',
'                    s.sgl_orgao,',
'                    s.nom_evento,',
'                    MIN(i.dat_servico) AS primeira_data,',
'                    ROW_NUMBER() OVER (ORDER BY MIN(i.dat_servico) DESC) rn',
'                FROM buf_solicitacao s',
'                JOIN buf_item_solicitacao i',
'                    ON i.fk_id_solicitacao = s.id_solicitacao',
'                WHERE s.sgl_orgao = :SETOR_USUARIO',
'                  AND i.status = ''Contratado''',
'                  AND EXISTS (',
'                      SELECT 1',
'                      FROM buf_item_solicitacao i2',
'                      WHERE i2.fk_id_solicitacao = s.id_solicitacao',
'                        AND i2.status = ''Contratado''',
'                        AND TRUNC(i2.dat_servico) >= TRUNC(SYSDATE)',
'                  )',
'                GROUP BY',
'                    s.id_solicitacao,',
'                    s.nom_solicitante,',
'                    s.sgl_orgao,',
'                    s.nom_evento',
'            )',
'            WHERE rn BETWEEN v_inicio AND v_fim',
'        )',
'        LOOP',
'            v_url_deletar := apex_util.prepare_url(',
'                    ''f?p='' || :APP_ID || '':372:'' || :APP_SESSION ||',
'                    ''::NO::P372_ID_SOLICITACAO:'' || sol.id_solicitacao',
'                );',
'',
'            SELECT COUNT(*)',
'            INTO v_total_itens',
'            FROM buf_item_solicitacao',
'            WHERE fk_id_solicitacao = sol.id_solicitacao',
'              AND status = ''Contratado'';',
'',
'            v_primeiro := TRUE;',
'',
'            FOR item IN (',
'                SELECT',
'                    i.id_item,',
'                    i.fk_id_desc || '' - '' || d.descricao AS descricao,',
'                    i.dat_servico,',
'                    i.qtd_pessoas,',
'                    i.local,',
'                    i.status,',
'                    i.valor_item',
'                FROM buf_item_solicitacao i',
'                JOIN buf_descricao d',
'                    ON d.id_desc = i.fk_id_desc',
'                WHERE i.fk_id_solicitacao = sol.id_solicitacao',
'                  AND i.status = ''Contratado''',
'            )',
'            LOOP',
'',
'                v_url_asqualog := apex_util.prepare_url(',
'                    ''f?p='' || :APP_ID || '':371:'' || :APP_SESSION ||',
'                    ''::NO::P371_ID_ITEM:'' || item.id_item',
'                );',
'',
'                htp.p(''<tr>'');',
'',
'                IF v_primeiro THEN',
'',
'                    htp.p(',
'                        ''<td rowspan="''||v_total_itens||''" class="central">',
'                            <a href="''||v_url_deletar||''"',
'                               class="t-Button t-Button--small t-Button--danger">',
'                               <span class="fa fa-trash-o"></span>',
'                            </a>',
'                         </td>''',
'                    );',
'',
'                    htp.p(''<td rowspan="''||v_total_itens||''" class="col-solicitante">''||sol.nom_solicitante||''</td>'');',
'                    htp.p(''<td rowspan="''||v_total_itens||''" class="col-orgao central">''||sol.sgl_orgao||''</td>'');',
'                    htp.p(''<td rowspan="''||v_total_itens||''" class="col-evento">''||sol.nom_evento||''</td>'');',
'',
'                    v_primeiro := FALSE;',
'',
'                END IF;',
'',
'                htp.p(''<td class="col-servico">''||item.descricao||''</td>'');',
'',
'                htp.p(''<td class="col-data central">''||',
'                TO_CHAR(item.dat_servico,''DD/MM/YYYY'')||',
'                ''</td>'');',
'',
'                htp.p(''<td class="col-pessoas central">''||',
'                item.qtd_pessoas||',
'                ''</td>'');',
'',
'                htp.p(''<td class="col-local central">''||',
'                item.local||',
'                ''</td>'');',
'',
'                htp.p(''<td class="col-status central">''||',
'                item.status||',
'                ''</td>'');',
'',
'                htp.p(''<td class="col-valor valor">R$ ''||',
'                TO_CHAR(item.valor_item,''FM999G999G990D00'')||',
'                ''</td>'');',
'',
'                IF item.status <> ''Cancelado'' THEN',
'                    htp.p(',
'                        ''<td class="col-detalhes central">',
'                            <a href="''||v_url_asqualog||''"',
'                               class="t-Button t-Button--small">',
'                               <span class="fa fa-eye"></span>',
'                            </a>',
'                        </td>''',
'                    );',
'                ELSE',
'                    htp.p(''<td class="col-detalhes central"></td>'');',
'                END IF;',
'',
'                htp.p(''</tr>'');',
'',
'            END LOOP;',
'',
'            htp.p(''',
'                <tr>',
'                    <td colspan="11" class="separador"></td>',
'                </tr>',
'            '');',
'',
'        END LOOP;',
'',
'        htp.p(''</tbody></table>'');',
'',
'        DECLARE',
'            v_url_pag VARCHAR2(4000);',
'        BEGIN',
'',
'            htp.p(''<div style="margin-top:15px;text-align:center;">'');',
'',
'            FOR i IN 1..v_total_paginas LOOP',
'',
'                v_url_pag := apex_page.get_url(',
'                    p_page   => :APP_PAGE_ID,',
'                    p_items  => ''P300_PAGINA'',',
'                    p_values => i',
'                );',
'',
'                IF i = v_pagina THEN',
'                    htp.p(',
'                        ''<span class="t-Button t-Button--hot" ',
'                               style="margin:0 4px;">''||i||''</span>''',
'                    );',
'                ELSE',
'                    htp.p(',
'                        ''<a class="t-Button" ',
'                            style="margin:0 4px;"',
'                            href="''||v_url_pag||''">''||i||''</a>''',
'                    );',
'                END IF;',
'            END LOOP;',
'            htp.p(''</div>'');',
'        END;',
'    END IF;',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
end;
/
