,p_plug_template=>wwv_flow_imp.id(711817305933954668)
,p_plug_display_sequence=>80
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    i.id_item AS id,',
'    LISTAGG(h.hor, '', '') WITHIN GROUP (ORDER BY h.hor) ',
'        || '' - '' || s.nom_evento AS title,',
'    i.dat_servico AS start_date,',
'    i.dat_servico AS end_date,',
'    ''interno'' AS tipo',
'FROM buf_item_solicitacao i',
'JOIN buf_solicitacao s ',
'    ON s.id_solicitacao = i.fk_id_solicitacao',
'LEFT JOIN buf_hor_item h ',
'    ON h.fk_id_item = i.id_item',
'WHERE i.status <> ''Cancelado''',
'GROUP BY ',
'    i.id_item, ',
'    s.nom_evento, ',
'    i.dat_servico',
'',
'UNION ALL',
'',
'SELECT ',
'    ie.id_item_solicitacao_ext AS id,',
'    ie.hor_inicio || '' - '' || se.nom_evento AS title,',
'    ie.dat_evento AS start_date,',
'    ie.dat_evento AS end_date,',
'    ''externo'' AS tipo',
'FROM buf_item_solicitacao_ext ie',
'JOIN buf_solicitacao_ext se ',
'    ON se.id_solicitacao_ext = ie.fk_id_solicitacao_ext',
'ORDER BY start_date DESC;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CSS_CALENDAR'
,p_attribute_01=>'START_DATE'
,p_attribute_02=>'END_DATE'
,p_attribute_03=>'TITLE'
