,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT i.id_item AS "ID",',
'    i.fk_id_solicitacao AS "FK",',
'    d.descricao AS "Item do Buffet",',
'    i.dat_servico AS "Data do Evento",',
'    i.qtd_pessoas AS "Quantidade de Itens",',
'    i.motivo_qtd AS "Justificativa da Qtd",',
'    i.valor_item AS "Valor R$",',
'    i.local AS "Local",',
unistr('    i.obs AS "Observa\00E7\00E3o",'),
'    LISTAGG(h.hor, ''<br>'')',
unistr('        WITHIN GROUP (ORDER BY h.hor) AS "Hor\00E1rios"'),
'FROM buf_item_solicitacao i',
'JOIN buf_descricao d ON i.fk_id_desc = d.id_desc',
'LEFT JOIN buf_hor_item h ON h.fk_id_item = i.id_item',
'WHERE fk_id_solicitacao = :P302_ID_SOLICITACAO',
'    AND EXISTS(',
'        SELECT 1',
'        FROM buf_hor_item h2',
'        WHERE h2.fk_id_item = i.id_item',
'    )',
'GROUP BY ',
'    i.id_item,',
'    i.fk_id_solicitacao,',
'    d.descricao,',
'    i.dat_servico,',
'    i.qtd_pessoas,',
'    i.motivo_qtd,',
'    i.valor_item,',
'    i.local,',
'    i.obs',
'ORDER BY i.dat_servico'))
