wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(735327500286195893)
,p_name=>'P302_LOCAL'
,p_item_sequence=>60
,p_item_plug_id=>wwv_flow_imp.id(735132571406701670)
,p_prompt=>'Local do Item'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH locais AS (',
'  SELECT ',
'    TO_CHAR(:P302_ITEM) AS item_value,',
'    TO_CHAR(:P302_QTD_PESSOAS) AS qtd',
'  FROM dual',
'  WHERE :P302_ITEM IS NOT NULL',
'),',
'resultado AS (',
'',
'  -- ITENS 1,2,3,7,10,13',
'  SELECT ''1'' AS item_id, ''Restaurante dos Senadores'' AS local ',
'  FROM locais ',
'  WHERE item_value IN (''1'',''2'',''3'',''7'',''10'',''13'')',
'',
'  UNION ALL',
'',
'  -- ITEM 4',
'  SELECT ''4'', ''Restaurante dos Senadores'' FROM locais WHERE item_value = ''4''',
'  UNION ALL',
'  SELECT ''4'', ''Cafezinho dos Senadores'' FROM locais WHERE item_value = ''4''',
'  UNION ALL',
unistr('  SELECT ''4'', ''Sal\00E3o Negro'' FROM locais WHERE item_value = ''4'''),
'',
'  UNION ALL',
'',
unistr('  -- ITEM 5 e 6 (Coffee break / refei\00E7\00E3o simplificada)'),
'  SELECT ''5'', ''Interlegis'' ',
'  FROM locais ',
'  WHERE item_value IN (''5'',''6'')',
'',
'  UNION ALL',
'  SELECT ''5'', ''ILB'' ',
'  FROM locais ',
'  WHERE item_value IN (''5'',''6'')',
'',
'  UNION ALL',
'  SELECT ''5'', ''Restaurante dos Senadores'' ',
'  FROM locais ',
'  WHERE item_value IN (''5'',''6'')',
'',
'  UNION ALL',
unistr('  -- \00BF REGRA AQUI'),
'  SELECT ''5'', ''Cafezinho dos Senadores'' ',
'  FROM locais ',
'  WHERE item_value IN (''5'',''6'')',
'    AND qtd <= 80',
'',
'  UNION ALL',
'',
'  -- ITEM 8 (limite 100 pessoas)',
'  SELECT ''8'', ''Restaurante dos Senadores'' ',
'  FROM locais ',
'  WHERE item_value = ''8''',
'    AND qtd <= 100',
'',
'  UNION ALL',
'',
'  -- ITEM 9',
unistr('  SELECT ''9'', ''Salas de Comiss\00F5es'' '),
'  FROM locais ',
'  WHERE item_value IN (''9'',''11'',''12'')',
')',
'',
'SELECT local AS display_value, local AS return_value',
'FROM resultado',
'ORDER BY local;'))
,p_lov_cascade_parent_items=>'P302_ITEM'
,p_ajax_optimize_refresh=>'Y'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(712094673063954719)
,p_item_template_options=>'#DEFAULT#'
,p_warn_on_unsaved_changes=>'I'
,p_lov_display_extra=>'YES'
,p_inline_help_text=>'teste'
,p_attribute_01=>'NONE'
,p_attribute_02=>'N'
);
