wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(744982179396796183)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_TEXTO_AJUDA'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_html CLOB := '''';',
'BEGIN',
unistr('    -- Busca descri\00E7\00E3o (sem quebrar se n\00E3o existir)'),
'    BEGIN',
'        SELECT ',
unistr('            ''Tempo de servi\00E7o: '' || NVL(d.tempo_servico, ''-'') || ''<br>'' ||'),
unistr('            ''Valor unit\00E1rio: '' || NVL(TO_CHAR(d.valor), ''-'') || ''<br>'' ||'),
unistr('            ''Anteced\00EAncia: '' || NVL(TO_CHAR(d.antecedencia), ''-'') || '' dias \00FAteis<br>'' || '),
unistr('            ''Quantidade dispon\00EDvel: '' || NVL(TO_CHAR(d.qtd_disponivel), ''-'') || ''<br><br>'''),
'        INTO v_html',
'        FROM buf_descricao d',
'        WHERE d.id_desc = TO_NUMBER(:P302_ITEM);',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
unistr('            v_html := ''Nenhuma descri\00E7\00E3o encontrada.'';'),
'    END;',
'',
unistr('    -- Especifica\00E7\00F5es'),
'    FOR esp IN (',
'        SELECT detalhe',
'        FROM buf_especificacao',
'        WHERE fk_id_desc = TO_NUMBER(:P302_ITEM)',
'    ) LOOP',
'        v_html := v_html || esp.detalhe || ''<br>'';',
'    END LOOP;',
'',
'    -- Retornar como JSON',
'    apex_json.open_object;',
'    apex_json.write(''responseText'', v_html);',
'    apex_json.close_object;',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        apex_json.open_object;',
'        apex_json.write(''responseText'', ''Erro: '' || SQLERRM);',
'        apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>529104457990570526
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(738919505528992481)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Salvar Primeira Parte'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_valor_item    NUMBER;',
'    v_qtd_disponivel    NUMBER;',
'    v_qtd           NUMBER;',
'    v_valor         NUMBER;',
'',
'    v_data_servico  DATE;',
'    v_hoje          DATE := TRUNC(SYSDATE);',
'',
'    v_dias_uteis    NUMBER;',
'    v_dias_corridos NUMBER;',
'',
'    v_setor_usuario VARCHAR2(20) := :SETOR_USUARIO;',
'    v_validar_datas BOOLEAN;',
'',
'    v_antecedencia_insuficiente     BOOLEAN := FALSE;',
'    v_conflito_data                 BOOLEAN := FALSE;',
'    v_qtd_conflito                  NUMBER;',
'',
'    FUNCTION fn_dias_uteis (',
'        p_data_inicio   DATE,',
'        p_data_fim      DATE',
'    ) RETURN NUMBER',
'    IS  ',
'        v_dias NUMBER := 0;',
'        v_data DATE := TRUNC(p_data_inicio);',
'    BEGIN',
'        WHILE v_data < TRUNC(p_data_fim) LOOP',
'            v_data := v_data + 1;',
'',
'            IF TO_CHAR(v_data, ''D'') NOT IN (''1'', ''7'') THEN',
'                v_dias := v_dias + 1;',
'            END IF;',
'        END LOOP;',
'',
'        RETURN v_dias;',
'    END;',
'BEGIN',
'    SELECT tempo_servico INTO :P302_DURACAO',
'    FROM buf_descricao',
'    WHERE id_desc = :P302_ITEM;',
'',
'    v_validar_datas := v_setor_usuario NOT IN (''ASCOM'', ''GBDGER'', ''GBPRES'', ''ASQUALOG'');',
'',
'    SELECT valor, qtd_disponivel INTO v_valor_item, v_qtd_disponivel',
'    FROM buf_descricao',
'    WHERE id_desc = :P302_ITEM;',
'',
'    v_qtd := :P302_QTD_PESSOAS;',
'    v_valor := v_valor_item * v_qtd;',
'    v_data_servico := TRUNC(TO_DATE(:P302_DAT_SERVICO, ''DD/MM/YYYY''));',
'',
'    v_dias_uteis := fn_dias_uteis(v_hoje, v_data_servico);',
'    v_dias_corridos := v_data_servico - v_hoje;',
'',
'    IF v_qtd > v_qtd_disponivel THEN',
unistr('        RAISE_APPLICATION_ERROR(-20020, ''Quantidade solicitada indispon\00EDvel. Dispon\00EDvel para este item: '' || v_qtd_disponivel || ''.'');'),
'    END IF;',
'',
'    SELECT COUNT(*) INTO v_qtd_conflito',
'    FROM buf_item_solicitacao',
'    WHERE dat_servico = v_data_servico',
'        AND status <> ''Cancelado'';',
'    ',
'    IF v_qtd_conflito > 0 THEN',
'        v_conflito_data := TRUE;',
'    ELSE',
'        SELECT COUNT(*) INTO v_qtd_conflito',
'        FROM buf_item_solicitacao_ext',
'        WHERE dat_evento = v_data_servico;',
'',
'        IF v_qtd_conflito > 0 THEN',
'            v_conflito_data := TRUE;',
'        END IF;',
'    END IF;',
'',
'    CASE :P302_ITEM',
'',
'        WHEN 1 THEN',
'            IF v_dias_uteis < 4 THEN',
'                IF v_validar_datas THEN',
unistr('                    RAISE_APPLICATION_ERROR(-20001, ''Empratado especial exige 4 dias \00FAteis.'');'),
'                ELSE',
'                    v_antecedencia_insuficiente := TRUE;',
'                END IF;',
'            END IF;',
'',
'        WHEN 2 THEN',
'            IF v_dias_corridos < 2 THEN',
'                IF v_validar_datas THEN',
unistr('                    RAISE_APPLICATION_ERROR(-20002, ''Empratado para almo\00E7o exige 48 horas.'');'),
'                ELSE',
'                    v_antecedencia_insuficiente := TRUE;',
'                END IF;',
'            END IF;',
'',
'        WHEN 3 THEN',
'            IF v_dias_uteis < 3 THEN',
'                IF v_validar_datas THEN',
unistr('                    RAISE_APPLICATION_ERROR(-20003, ''Buffet exige 3 dias \00FAteis.'');'),
'                ELSE',
'                    v_antecedencia_insuficiente := TRUE;',
'                END IF;',
'            END IF;',
'',
'        WHEN 4 THEN',
'            IF v_dias_corridos < 15 THEN',
'                IF v_validar_datas THEN',
'                    RAISE_APPLICATION_ERROR(-20004, ''Coquetel exige 15 dias.'');',
'                ELSE',
'                    v_antecedencia_insuficiente := TRUE;',
'                END IF;',
'            END IF;',
'',
'            IF v_qtd > 150 THEN',
unistr('                RAISE_APPLICATION_ERROR(-20005, ''M\00E1ximo de 150 pessoas para coquetel.'');'),
'            END IF;',
'',
'        WHEN 5 THEN',
'            IF v_dias_uteis < 5 THEN',
'                IF v_validar_datas THEN',
unistr('                    RAISE_APPLICATION_ERROR(-20006, ''Coffee break exige 5 dias \00FAteis.'');'),
'                ELSE',
'                    v_antecedencia_insuficiente := TRUE;',
'                END IF;',
'            END IF;',
'',
'        WHEN 6 THEN',
'            IF v_dias_uteis < 5 THEN',
'                IF v_validar_datas THEN',
unistr('                    RAISE_APPLICATION_ERROR(-20007, ''Refei\00E7\00F5es simplificadas exigem 5 dias \00FAteis.'');'),
'                ELSE',
'                    v_antecedencia_insuficiente := TRUE;',
'                END IF;',
'            END IF;',
'',
'        WHEN 7 THEN',
'            IF v_qtd < 30 THEN',
unistr('                RAISE_APPLICATION_ERROR(-20008, ''M\00EDnimo de 30 pessoas para lunch box.'');'),
'            END IF;',
'',
'            IF v_qtd BETWEEN 30 AND 99 THEN',
'                IF v_dias_uteis < 5 THEN',
'                    IF v_validar_datas THEN',
unistr('                        RAISE_APPLICATION_ERROR(-20009, ''Lunch box exige 5 dias \00FAteis.'');'),
'                    ELSE',
'                        v_antecedencia_insuficiente := TRUE;',
'                    END IF;',
'                END IF;',
'            ELSIF v_qtd BETWEEN 100 AND 550 THEN',
'                IF v_dias_uteis < 15 THEN',
'                    IF v_validar_datas THEN',
unistr('                        RAISE_APPLICATION_ERROR(-20010, ''Lunch box (100 a 550 pax) exige 15 dias \00FAteis.'');'),
'                    ELSE',
'                        v_antecedencia_insuficiente := TRUE;',
'                    END IF;',
'                END IF;',
'            END IF;',
'',
'        WHEN 8 THEN',
'            IF v_dias_uteis < 5 THEN',
'                IF v_validar_datas THEN',
unistr('                    RAISE_APPLICATION_ERROR(-20011, ''Caf\00E9 da manh\00E3 exige 5 dias \00FAteis.'');'),
'                ELSE',
'                    v_antecedencia_insuficiente := TRUE;',
'                END IF;',
'            END IF;',
'',
'            IF v_qtd > 100 THEN',
unistr('                RAISE_APPLICATION_ERROR(-20012, ''M\00E1ximo de 100 pessoas.'');'),
'            END IF;',
'',
'        WHEN 9 THEN',
'            IF v_dias_corridos < 2 THEN',
'                IF v_validar_datas THEN',
unistr('                    RAISE_APPLICATION_ERROR(-20013, ''Servi\00E7o de apoio exige 48 horas.'');'),
'                ELSE',
'                    v_antecedencia_insuficiente := TRUE;',
'                END IF;',
'            END IF;',
'',
'            IF v_qtd > 150 THEN',
unistr('                RAISE_APPLICATION_ERROR(-20014, ''Limite de 150 pessoas para o servi\00E7o de apoio.'');'),
'            END IF;',
'',
'        WHEN 10 THEN',
'            IF v_dias_corridos < 15 THEN',
'                IF v_validar_datas THEN',
'                    RAISE_APPLICATION_ERROR(-20015, ''Bebida especial exige 15 dias.'');',
'                ELSE',
'                    v_antecedencia_insuficiente := TRUE;',
'                END IF;',
'            END IF;',
'',
'        WHEN 11 THEN',
'            IF v_dias_corridos < 7 THEN',
'                IF v_validar_datas THEN',
'                    RAISE_APPLICATION_ERROR(-20016, ''Apoio especial exige 7 dias.'');',
'                ELSE',
'                    v_antecedencia_insuficiente := TRUE;',
'                END IF;',
'            END IF;',
'',
'        WHEN 12 THEN',
'            IF v_dias_corridos < 20 THEN',
'                IF v_validar_datas THEN',
'                    RAISE_APPLICATION_ERROR(-20017, ''Apoio VIP exige 20 dias.'');',
'                ELSE',
'                    v_antecedencia_insuficiente := TRUE;',
'                END IF;',
'            END IF;',
'',
'        WHEN 13 THEN',
'            IF v_dias_uteis < 5 THEN',
'                IF v_validar_datas THEN',
unistr('                    RAISE_APPLICATION_ERROR(-20018, ''Brunch exige 5 dias \00FAteis.'');'),
'                ELSE',
'                    v_antecedencia_insuficiente := TRUE;',
'                END IF;',
'            END IF;',
'',
'    END CASE;',
'    ',
'    UPDATE buf_descricao',
'    SET qtd_disponivel = qtd_disponivel - v_qtd',
'    WHERE id_desc = :P302_ITEM;',
'',
'    INSERT INTO buf_item_solicitacao (',
'        fk_id_solicitacao,',
'        fk_id_desc,',
'        dat_servico,',
'        qtd_pessoas,',
'        valor_item,',
'        status,',
'        local,',
'        obs,',
'        motivo_qtd',
'    ) VALUES (',
'        :P302_ID_SOLICITACAO,',
'        :P302_ITEM,',
'        :P302_DAT_SERVICO,',
'        :P302_QTD_PESSOAS,',
'        v_valor,',
unistr('        ''Em negocia\00E7\00E3o'','),
'        :P302_LOCAL,',
'        :P302_OBS,',
'        :P302_MOTIVO_QTD',
'    )',
'    RETURNING id_item INTO :P302_ID_ITEM;',
'',
'    IF v_conflito_data OR v_antecedencia_insuficiente THEN',
'        UPDATE buf_solicitacao',
'        SET ind_excecao = ''S''',
'        WHERE id_solicitacao = :P302_ID_SOLICITACAO;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(738919331310992480)
,p_internal_uid=>523041784122766824
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(758919825365267087)
,p_process_sequence=>20
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Deletar Itens sem Horario'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    -- 1) Repor quantidade na BUF_DESCRICAO',
'    UPDATE buf_descricao d',
'    SET d.qtd_disponivel = d.qtd_disponivel + (',
'        SELECT NVL(SUM(bis.qtd_pessoas), 0)',
'        FROM buf_item_solicitacao bis',
'        JOIN buf_solicitacao bs ON bs.id_solicitacao = bis.fk_id_solicitacao',
'        WHERE bis.fk_id_desc = d.id_desc',
'          AND bis.fk_id_solicitacao = :P273_ID_SOLICITACAO',
'          AND bs.ind_pendente = ''S''',
'          AND NOT EXISTS (',
'                SELECT 1',
'                FROM buf_hor_item bhi',
'                WHERE bhi.fk_id_item = bis.id_item',
'          )',
'    )',
'    WHERE EXISTS (',
'        SELECT 1',
'        FROM buf_item_solicitacao bis',
'        JOIN buf_solicitacao bs ON bs.id_solicitacao = bis.fk_id_solicitacao',
'        WHERE bis.fk_id_desc = d.id_desc',
'          AND bis.fk_id_solicitacao = :P273_ID_SOLICITACAO',
'          AND bs.ind_pendente = ''S''',
'          AND NOT EXISTS (',
'                SELECT 1',
'                FROM buf_hor_item bhi',
'                WHERE bhi.fk_id_item = bis.id_item',
'          )',
'    );',
'',
'    -- 2) Deletar os itens',
'    DELETE FROM buf_item_solicitacao bis',
'    WHERE bis.fk_id_solicitacao = :P273_ID_SOLICITACAO',
'      AND EXISTS (',
'          SELECT 1',
'          FROM buf_solicitacao bs',
'          WHERE bs.id_solicitacao = bis.fk_id_solicitacao',
'            AND bs.ind_pendente = ''S''',
'      )',
'      AND NOT EXISTS (',
'            SELECT 1',
'            FROM buf_hor_item bhi',
'            WHERE bhi.fk_id_item = bis.id_item',
'      );',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(735328297431195901)
,p_internal_uid=>543042103959041430
);
