wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(252287229562378513)
,p_plug_name=>unistr('Solicita\00E7\00E3o Atual')
,p_region_name=>'senac'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(711817305933954668)
,p_plug_display_sequence=>40
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_total_itens NUMBER;',
'    v_primeiro BOOLEAN;',
'',
'    v_url_asqualog  CLOB;',
'    v_url_deletar   CLOB;',
'',
'    v_existe        NUMBER;',
'BEGIN',
'',
'    SELECT COUNT(DISTINCT s.id_solicitacao) INTO v_existe',
'    FROM buf_solicitacao s',
'    JOIN buf_item_solicitacao i',
'        ON i.fk_id_solicitacao = s.id_solicitacao',
'    WHERE s.id_solicitacao = :P303_ID_SOLICITACAO',
'        AND s.ind_pendente = ''S''',
'        AND s.ind_excecao = ''S'';',
'',
'    IF v_existe = 0 THEN',
'        htp.p(''',
'            <div class="t-Alert t-Alert--warning t-Alert--horizontal t-Alert--defaultIcons">',
'                <div class="t-Alert-wrap">',
'                    <div class="t-Alert-icon">',
'                        <span class="t-Icon fa fa-info-circle"></span>',
'                    </div>',
'                    <div class="t-Alert-content">',
'                        <div class="t-Alert-header">',
'                            <h2 class="t-Alert-title">',
unistr('                                N\00E3o h\00E1 itens cadastrados para este evento.'),
'                            </h2>',
'                        </div>',
'                    </div>',
'                </div>',
'            </div>',
'        '');',
'    ELSE',
'        htp.p(''<table class="tbl-buffet">'');',
'',
'        htp.p(''',
'        <thead>',
'        <tr>',
'            <th></th>',
'            <th class="col-solicitante">Solicitante</th>',
unistr('            <th class="col-orgao">\00D3rg\00E3o</th>'),
'            <th class="col-evento">Evento</th>',
unistr('            <th class="col-servico">Servi\00E7o</th>'),
'            <th class="col-data">Data</th>',
'            <th class="col-pessoas">Pessoas</th>',
'            <th class="col-local">Local</th>',
'            <th class="col-status">Status</th>',
'            <th class="col-valor">Valor</th>',
'            <th class="col-detalhes">Detalhes</th>',
'        </tr>',
'        </thead>',
'        <tbody>',
'        '');',
'',
'        FOR sol IN (',
'            SELECT',
'                s.id_solicitacao,',
'                s.nom_solicitante,',
'                s.sgl_orgao,',
'                s.nom_evento',
'            FROM buf_solicitacao s',
'            WHERE s.id_solicitacao = :P303_ID_SOLICITACAO',
'                AND s.ind_pendente = ''S''',
'                AND s.ind_excecao = ''S''',
'        )',
'        LOOP',
'            v_url_deletar := apex_util.prepare_url(',
'                    ''f?p='' || :APP_ID || '':379:'' || :APP_SESSION ||',
'                    ''::NO::P379_ID_SOLICITACAO:'' || sol.id_solicitacao',
'                );',
'',
'            SELECT COUNT(*)',
'            INTO v_total_itens',
'            FROM buf_item_solicitacao',
'            WHERE fk_id_solicitacao = sol.id_solicitacao;',
'',
'            v_primeiro := TRUE;',
'',
'            FOR item IN (',
'                SELECT',
'                    i.id_item,',
'                    i.fk_id_desc || '' - '' || d.descricao AS descricao,',
'                    i.dat_servico,',
'                    i.qtd_pessoas,',
'                    i.local,',
'                    i.status,',
'                    i.valor_item',
'                FROM buf_item_solicitacao i',
'                JOIN buf_descricao d',
'                    ON d.id_desc = i.fk_id_desc',
'                WHERE i.fk_id_solicitacao = sol.id_solicitacao',
'            )',
'            LOOP',
'',
'                v_url_asqualog := apex_util.prepare_url(',
'                    ''f?p='' || :APP_ID || '':374:'' || :APP_SESSION ||',
'                    ''::NO::P374_ID_ITEM:'' || item.id_item',
'                );',
'',
'                htp.p(''<tr>'');',
'',
'                IF v_primeiro THEN',
'                    htp.p(',
'                        ''<td rowspan="''||v_total_itens||''" class="central">',
'                            <a href="''||v_url_deletar||''"',
'                               class="t-Button t-Button--small t-Button--danger">',
'                               <span class="fa fa-trash-o"></span>',
'                            </a>',
'                         </td>''',
'                    );',
'',
'                    htp.p(''<td rowspan="''||v_total_itens||''" class="col-solicitante">''||sol.nom_solicitante||''</td>'');',
'                    htp.p(''<td rowspan="''||v_total_itens||''" class="col-orgao central">''||sol.sgl_orgao||''</td>'');',
'                    htp.p(''<td rowspan="''||v_total_itens||''" class="col-evento">''||sol.nom_evento||''</td>'');',
'',
'                    v_primeiro := FALSE;',
'                END IF;',
'',
'                htp.p(''<td class="col-servico">''||item.descricao||''</td>'');',
'                htp.p(''<td class="col-data central">''||',
'                TO_CHAR(item.dat_servico,''DD/MM/YYYY'')||',
'                ''</td>'');',
'                htp.p(''<td class="col-pessoas central">''||',
'                item.qtd_pessoas||',
'                ''</td>'');',
'                htp.p(''<td class="col-local central">''||',
'                item.local||',
'                ''</td>'');',
'                htp.p(''<td class="col-status central">''||',
'                item.status||',
'                ''</td>'');',
'                htp.p(''<td class="col-valor valor">R$ ''||',
'                TO_CHAR(item.valor_item,''FM999G999G990D00'')||',
'                ''</td>'');',
'                htp.p(',
'                    ''<td class="col-detalhes central">',
'                        <a href="''||v_url_asqualog||''"',
'                           class="t-Button t-Button--small">',
'                           <span class="fa fa-eye"></span>',
'                        </a>',
'                    </td>''',
'                );',
'',
'                htp.p(''</tr>'');',
'',
'            END LOOP;',
'            htp.p(''',
'                <tr>',
'                    <td colspan="11" class="separador"></td>',
'                </tr>',
'            '');',
'',
'        END LOOP;',
'        htp.p(''</tbody></table>'');',
'    END IF;',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P303_ID_SOLICITACAO'
);
