wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(252287428416378515)
,p_name=>'P303_SENAC_DGER'
,p_item_sequence=>20
,p_item_default=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_existe_senac NUMBER;',
'    v_existe_dger  NUMBER;',
'BEGIN',
'    SELECT COUNT(DISTINCT s.id_solicitacao)',
'    INTO v_existe_senac',
'    FROM buf_solicitacao s',
'    JOIN buf_item_solicitacao i ON i.fk_id_solicitacao = s.id_solicitacao',
'    WHERE s.id_solicitacao = :P303_ID_SOLICITACAO',
'        AND s.ind_pendente = ''S''',
'        AND s.ind_excecao = ''S'';',
'    ',
'    SELECT COUNT(DISTINCT s.id_solicitacao)',
'    INTO v_existe_dger',
'    FROM buf_solicitacao s',
'    JOIN buf_item_solicitacao i ON i.fk_id_solicitacao = s.id_solicitacao',
'    WHERE s.id_solicitacao = :P303_ID_SOLICITACAO',
'        AND s.ind_pendente = ''S''',
'        AND s.ind_excecao = ''N'';',
'',
'    IF v_existe_senac = 0 AND v_existe_dger = 0 THEN',
'        RETURN ''nenhum'';',
'    ELSIF v_existe_senac = 0 THEN',
'        RETURN ''dger'';',
'    ELSIF v_existe_dger = 0 THEN',
'        RETURN ''senac'';',
'    END IF;',
'END;'))
,p_item_default_type=>'FUNCTION_BODY'
,p_item_default_language=>'PLSQL'
,p_display_as=>'NATIVE_HIDDEN'
,p_attribute_01=>'N'
);
