wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(738917736936992464)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Confirmar Evento e Enviar e-mail'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_evento               VARCHAR2(4000);',
'    v_nome_solicitante     VARCHAR2(200);',
'    v_email_destino_dger     VARCHAR2(200) := ''DGER@senado.leg.br'';',
'    v_email_remetente      VARCHAR2(200);',
'    v_email_cc             VARCHAR2(1000);',
unistr('    v_assunto_dger         VARCHAR2(200) := ''Solicita\00E7\00E3o de Buffet - Encaminhamento para Delibera\00E7\00E3o'';'),
unistr('    v_assunto_solicitante  VARCHAR2(200) := ''Solicita\00E7\00E3o de Buffet Recebida'';'),
'    v_mensagem_dger        CLOB;',
'    v_mensagem_solicitante CLOB;',
'    v_qtd_horarios         NUMBER;',
'    v_primeiro             BOOLEAN;',
'    l_mail_id_dger         NUMBER;',
'    l_mail_id_solicitante  NUMBER;',
'    v_qtd_itens_pendentes  NUMBER;',
'    v_link_sistema         VARCHAR2(4000);',
'    v_link_solicitacao     VARCHAR2(4000);',
'    v_valor_total          NUMBER := 0;',
'    v_email_solicitante    VARCHAR2(4000);',
'    v_cnt_solicitacao      NUMBER;',
'BEGIN',
'    SELECT COUNT(*)',
'      INTO v_cnt_solicitacao',
'      FROM buf_solicitacao',
'     WHERE id_solicitacao = :P303_ID_SOLICITACAO',
'        AND ind_pendente = ''S'';',
'',
'    IF v_cnt_solicitacao = 0 THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
unistr('            ''N\00E3o h\00E1 solicita\00E7\00E3o cadastrada para a confirma\00E7\00E3o e envio de e-mail.'''),
'        );',
'    END IF;',
'',
'',
'    UPDATE buf_solicitacao',
'       SET ind_analisado = ''N''',
'     WHERE id_solicitacao = :P303_ID_SOLICITACAO;',
'',
'    SELECT vs.nom_pessoa,',
'           u.txt_email_sf,',
'           bs.email_responsavel,',
'           bs.nom_evento',
'      INTO v_nome_solicitante,',
'           v_email_remetente,',
'           v_email_solicitante,',
'           v_evento',
'      FROM dda.vinculo_sf vs',
'      JOIN dda.usuario_rede u',
'        ON vs.num_cpf = u.num_cpf_pessoa',
'      JOIN buf_solicitacao bs',
'        ON bs.id_solicitacao = :P303_ID_SOLICITACAO',
'     WHERE u.txt_login_ad = :APP_USER;',
'',
'    v_email_cc := ''guilherme.schettini@senado.leg.br,LAFUENTE@senado.leg.br,JSOLON@senado.leg.br,asqualog@senado.leg.br,sequalog-equipe@senado.gov.br,'' ||',
'                  COALESCE(v_email_solicitante, '''');',
'',
'    v_email_cc := REGEXP_REPLACE(v_email_cc, '',$'', '''');',
'',
'    SELECT COUNT(*)',
'      INTO v_qtd_itens_pendentes',
'      FROM buf_item_solicitacao bis',
'      JOIN buf_solicitacao bs',
'        ON bis.fk_id_solicitacao = bs.id_solicitacao',
'     WHERE bs.ind_analisado = ''N'';',
'',
'    v_link_sistema     := ''https://dda.senado.leg.br/desenv/r/asqualog/buffet'';',
unistr('    -- ajuste para o padr\00E3o da sua aplica\00E7\00E3o (ex.: URL APEX):'),
'    v_link_solicitacao := v_link_sistema;',
'',
'    v_mensagem_dger :=',
'           ''<html>',
'              <body style="font-family: Arial, Helvetica, sans-serif; font-size:14px; color:#333;">',
'                <p>Prezados(as),</p>',
'',
'                <p>',
unistr('                  Foi registrada no Sistema de Buffet a solicita\00E7\00E3o abaixo, encaminhada para delibera\00E7\00E3o dessa Diretoria-Geral.'),
'                </p>',
'',
'                <p>',
unistr('                  Acesse a solicita\00E7\00E3o no sistema:<br>'),
'                  <a href="'' || v_link_solicitacao || ''">'' || v_link_solicitacao || ''</a>',
'                </p>',
'',
'                <p>',
'                  <b>Evento:</b> '' || v_evento || ''<br>',
'                  <b>Solicitante:</b> '' || v_nome_solicitante || ''<br>',
'                  <b>Unidade Solicitante:</b> '' || :SETOR_USUARIO || ''',
'                </p>',
'',
unistr('                <p><b>Servi\00E7os solicitados</b></p>'),
'',
'                <table style="',
'                    border-collapse:collapse;',
'                    width:100%;',
'                    max-width:800px;',
'                    margin-top:10px;',
'                    border:1px solid #ddd;',
'                ">',
'                    <tr style="background-color:#f2f2f2;">',
unistr('                        <th style="padding:8px;border:1px solid #ddd;">Servi\00E7o</th>'),
'                        <th style="padding:8px;border:1px solid #ddd;">Data</th>',
'                        <th style="padding:8px;border:1px solid #ddd;">Motivo Qtde</th>',
'                        <th style="padding:8px;border:1px solid #ddd;">Local</th>',
'                        <th style="padding:8px;border:1px solid #ddd;">Valor</th>',
unistr('                        <th style="padding:8px;border:1px solid #ddd;">Hor\00E1rio</th>'),
unistr('                        <th style="padding:8px;border:1px solid #ddd;">Qtd por Hor\00E1rio</th>'),
'                    </tr>'';',
'',
'    v_valor_total := 0;',
'',
'    FOR item IN (',
'        SELECT i.id_item,',
'               d.descricao,',
'               i.dat_servico,',
'               i.qtd_pessoas,',
'               i.motivo_qtd,',
'               i.local,',
'               i.valor_item',
'          FROM buf_item_solicitacao i',
'          JOIN buf_descricao d',
'            ON i.fk_id_desc = d.id_desc',
'         WHERE i.fk_id_solicitacao = :P303_ID_SOLICITACAO',
'         ORDER BY i.dat_servico',
'    )',
'    LOOP',
'        v_valor_total := v_valor_total + NVL(item.valor_item, 0);',
'',
'        SELECT COUNT(*)',
'          INTO v_qtd_horarios',
'          FROM buf_hor_item',
'         WHERE fk_id_item = item.id_item;',
'',
'        IF v_qtd_horarios = 0 THEN',
'            v_qtd_horarios := 1;',
'        END IF;',
'',
'        v_primeiro := TRUE;',
'',
'        FOR h IN (',
'            SELECT hor, qtd_hor',
'              FROM buf_hor_item',
'             WHERE fk_id_item = item.id_item',
'             ORDER BY hor',
'        )',
'        LOOP',
'            v_mensagem_dger := v_mensagem_dger || ''<tr>'';',
'',
'            IF v_primeiro THEN',
'                v_mensagem_dger := v_mensagem_dger ||',
'                    ''<td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;">''',
'                        || item.descricao || ''</td>',
'                     <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:center;">''',
'                        || TO_CHAR(item.dat_servico, ''DD/MM/YYYY'') || ''</td>',
'                     <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;">''',
'                        || NVL(item.motivo_qtd, ''-'') || ''</td>',
'                     <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;">''',
'                        || item.local || ''</td>',
'                     <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:right;">R$ ''',
'                        || TO_CHAR(item.valor_item, ''FM999G999G990D00'') || ''</td>'';',
'            END IF;',
'',
'            v_mensagem_dger := v_mensagem_dger ||',
'                ''<td style="padding:8px;border:1px solid #ddd;text-align:center;">''',
'                    || NVL(TO_CHAR(h.hor), ''-'') || ''</td>',
'                 <td style="padding:8px;border:1px solid #ddd;text-align:center;">''',
'                    || NVL(TO_CHAR(h.qtd_hor), ''-'') || ''</td>'';',
'',
'            v_mensagem_dger := v_mensagem_dger || ''</tr>'';',
'            v_primeiro := FALSE;',
'        END LOOP;',
'',
'        IF v_primeiro THEN',
'            v_mensagem_dger := v_mensagem_dger ||',
'            ''<tr>',
'                <td style="padding:8px;border:1px solid #ddd;">''||item.descricao||''</td>',
'                <td style="padding:8px;border:1px solid #ddd;text-align:center;">''||TO_CHAR(item.dat_servico,''DD/MM/YYYY'')||''</td>',
'                <td style="padding:8px;border:1px solid #ddd;">''||NVL(item.motivo_qtd, ''-'')||''</td>',
'                <td style="padding:8px;border:1px solid #ddd;">''||item.local||''</td>',
'                <td style="padding:8px;border:1px solid #ddd;text-align:right;">R$ ''||TO_CHAR(item.valor_item,''FM999G999G990D00'')||''</td>',
'                <td style="padding:8px;border:1px solid #ddd;text-align:center;">-</td>',
'                <td style="padding:8px;border:1px solid #ddd;text-align:center;">-</td>',
'            </tr>'';',
'        END IF;',
'    END LOOP;',
'',
'    v_mensagem_dger := v_mensagem_dger ||',
'        ''<tr style="background-color:#f9f9f9;">',
'           <td colspan="4" style="padding:8px;border:1px solid #ddd;text-align:right;"><b>Valor Total:</b></td>',
'           <td style="padding:8px;border:1px solid #ddd;text-align:right;"><b>R$ '' ||',
'              TO_CHAR(v_valor_total, ''FM999G999G990D00'') || ''</b></td>',
'           <td style="padding:8px;border:1px solid #ddd;"></td>',
'           <td style="padding:8px;border:1px solid #ddd;"></td>',
'        </tr>',
'        </table>',
'',
'        <br><br>',
'         <p>',
unistr('           Informamos que, al\00E9m da presente demanda, existem atualmente <b>'' ||'),
unistr('           v_qtd_itens_pendentes || ''</b> solicita\00E7\00F5es pendentes de delibera\00E7\00E3o no Sistema de Buffet.'),
'         </p>',
'',
'         <p>',
unistr('           Solicita-se, por gentileza, a an\00E1lise e manifesta\00E7\00E3o quanto \00E0 aprova\00E7\00E3o da demanda.'),
'         </p>',
'',
'         <p>',
'           Atenciosamente,<br>',
'           <b>Sistema de Buffet</b><br>',
unistr('           Assessoria de Qualidade de Atendimento e Log\00EDstica \2013 ASQUALOG<br>'),
'           Senado Federal',
'         </p>',
'',
'         <p style="font-size:12px;color:#666;margin-top:20px;">',
unistr('           Este \00E9 um e-mail autom\00E1tico do Sistema de Buffet.<br>'),
unistr('           Em caso de d\00FAvidas, contatar: <a href="mailto:asqualog@senado.leg.br">asqualog@senado.leg.br</a>'),
'         </p>',
'',
'        </body>',
'      </html>'';',
'',
'    l_mail_id_dger := APEX_MAIL.SEND(',
'        p_to        => v_email_destino_dger,',
'        p_cc      => v_email_cc,',
'        p_from      => v_email_remetente,',
'        p_subj      => v_assunto_dger,',
'        p_body      => NULL,',
'        p_body_html => v_mensagem_dger',
'    );',
'',
'    IF v_email_solicitante IS NOT NULL THEN',
'        v_mensagem_solicitante :=',
'           ''<html>',
'              <body style="font-family: Arial, Helvetica, sans-serif; font-size:14px; color:#333;">',
'                <p>Prezado(a),</p>',
'',
'                <p>',
unistr('                  Sua solicita\00E7\00E3o de servi\00E7o de buffet foi registrada com sucesso no Sistema de Buffet e ser\00E1 submetida \00E0 delibera\00E7\00E3o administrativa.'),
'                </p>',
'',
'                <p>',
unistr('                  Acompanhe a solicita\00E7\00E3o:<br>'),
'                  <a href="'' || v_link_solicitacao || ''">'' || v_link_solicitacao || ''</a>',
'                </p>',
'',
'                <p>',
'                  <b>Evento:</b> '' || v_evento || ''',
'                </p>',
'',
unistr('                <p><b>Servi\00E7os solicitados</b></p>'),
'',
'                <table style="',
'                    border-collapse:collapse;',
'                    width:100%;',
'                    max-width:800px;',
'                    margin-top:10px;',
'                    border:1px solid #ddd;',
'                ">',
'                    <tr style="background-color:#f2f2f2;">',
unistr('                        <th style="padding:8px;border:1px solid #ddd;">Servi\00E7o</th>'),
'                        <th style="padding:8px;border:1px solid #ddd;">Data</th>',
unistr('                        <th style="padding:8px;border:1px solid #ddd;">N\00BA de Pessoas</th>'),
unistr('                        <th style="padding:8px;border:1px solid #ddd;">Hor\00E1rio</th>'),
unistr('                        <th style="padding:8px;border:1px solid #ddd;">Quantidade por Hor\00E1rio</th>'),
'                        <th style="padding:8px;border:1px solid #ddd;">Local</th>',
'                        <th style="padding:8px;border:1px solid #ddd;">Valor</th>',
'                    </tr>'';',
'',
'        FOR item2 IN (',
'            SELECT i.id_item,',
'                   d.descricao,',
'                   i.dat_servico,',
'                   i.qtd_pessoas,',
'                   i.motivo_qtd,',
'                   i.local,',
'                   i.valor_item',
'              FROM buf_item_solicitacao i',
'              JOIN buf_descricao d',
'                ON i.fk_id_desc = d.id_desc',
'             WHERE i.fk_id_solicitacao = :P303_ID_SOLICITACAO',
'             ORDER BY i.dat_servico',
'        )',
'        LOOP',
'            SELECT COUNT(*)',
'              INTO v_qtd_horarios',
'              FROM buf_hor_item',
'             WHERE fk_id_item = item2.id_item;',
'',
'            IF v_qtd_horarios = 0 THEN',
'                v_qtd_horarios := 1;',
'            END IF;',
'',
'            v_primeiro := TRUE;',
'',
'            FOR h2 IN (',
'                SELECT hor, qtd_hor',
'                  FROM buf_hor_item',
'                 WHERE fk_id_item = item2.id_item',
'                 ORDER BY hor',
'            )',
'            LOOP',
'                v_mensagem_solicitante := v_mensagem_solicitante || ''<tr>'';',
'',
'                IF v_primeiro THEN',
'                    v_mensagem_solicitante := v_mensagem_solicitante ||',
'                        ''<td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;">''',
'                            || item2.descricao || ''</td>',
'                         <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:center;">''',
'                            || TO_CHAR(item2.dat_servico, ''DD/MM/YYYY'') || ''</td>',
'                         <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:center;">''',
'                            || NVL(TO_CHAR(item2.qtd_pessoas), ''-'') || ''</td>'';',
'                END IF;',
'',
'                v_mensagem_solicitante := v_mensagem_solicitante ||',
'                    ''<td style="padding:8px;border:1px solid #ddd;text-align:center;">''',
'                        || NVL(TO_CHAR(h2.hor), ''-'') || ''</td>',
'                     <td style="padding:8px;border:1px solid #ddd;text-align:center;">''',
'                        || NVL(TO_CHAR(h2.qtd_hor), ''-'') || ''</td>'';',
'',
'                IF v_primeiro THEN',
'                    v_mensagem_solicitante := v_mensagem_solicitante ||',
'                        ''<td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;">''',
'                            || item2.local || ''</td>',
'                         <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:right;">R$ ''',
'                            || TO_CHAR(item2.valor_item, ''FM999G999G990D00'') || ''</td>'';',
'                END IF;',
'',
'                v_mensagem_solicitante := v_mensagem_solicitante || ''</tr>'';',
'                v_primeiro := FALSE;',
'            END LOOP;',
'',
'            IF v_primeiro THEN',
'                v_mensagem_solicitante := v_mensagem_solicitante ||',
'                ''<tr>',
'                    <td style="padding:8px;border:1px solid #ddd;">''||item2.descricao||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">''||TO_CHAR(item2.dat_servico,''DD/MM/YYYY'')||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">''||NVL(TO_CHAR(item2.qtd_pessoas), ''-'')||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">-</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">-</td>',
'                    <td style="padding:8px;border:1px solid #ddd;">''||item2.local||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:right;">R$ ''||TO_CHAR(item2.valor_item,''FM999G999G990D00'')||''</td>',
'                </tr>'';',
'            END IF;',
'        END LOOP;',
'',
'        v_mensagem_solicitante := v_mensagem_solicitante ||',
'            ''</table>',
'',
'             <br><br>',
'             <p>',
unistr('               O solicitante ser\00E1 automaticamente comunicado sobre qualquer atualiza\00E7\00E3o do pedido.'),
'             </p>',
'',
'             <p>',
'               Atenciosamente,<br>',
'               <b>Sistema de Buffet</b><br>',
unistr('               Assessoria de Qualidade de Atendimento e Log\00EDstica \2013 ASQUALOG<br>'),
'               Senado Federal',
'             </p>',
'',
'             <p style="font-size:12px;color:#666;margin-top:20px;">',
unistr('               Este \00E9 um e-mail autom\00E1tico do Sistema de Buffet.<br>'),
unistr('               Em caso de d\00FAvidas, contatar: <a href="mailto:asqualog@senado.leg.br">asqualog@senado.leg.br</a>'),
'             </p>',
'',
'            </body>',
'          </html>'';',
'',
'        l_mail_id_solicitante := APEX_MAIL.SEND(',
'            p_to        => v_email_solicitante,',
'            p_cc        => v_email_cc,',
'            p_from      => v_email_remetente,',
'            p_subj      => v_assunto_solicitante,',
'            p_body      => NULL,',
'            p_body_html => v_mensagem_solicitante',
'        );',
'    END IF;',
'',
'    FOR a IN (',
'        SELECT anexo,',
'               filename,',
'               mimetype',
'          FROM buf_anexo',
'         WHERE fk_id_solicitacao = :P303_ID_SOLICITACAO',
'    )',
'    LOOP',
'        apex_mail.add_attachment(',
'            p_mail_id    => l_mail_id_dger,',
'            p_attachment => a.anexo,',
'            p_filename   => a.filename,',
'            p_mime_type  => a.mimetype',
'        );',
'    END LOOP;',
'',
'    APEX_MAIL.PUSH_QUEUE;',
'',
'    DELETE FROM buf_anexo',
'     WHERE fk_id_solicitacao = :P303_ID_SOLICITACAO;',
'',
'    UPDATE buf_solicitacao',
'    SET ind_pendente = ''N''',
'    WHERE id_solicitacao = :P303_ID_SOLICITACAO;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(738917519043992461)
,p_internal_uid=>523040015530766807
);
end;
/
begin
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(252287752029378518)
,p_process_sequence=>20
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Confirmar Evento e Enviar ASQUALOG'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_evento               VARCHAR2(4000);',
'    v_nome_solicitante     VARCHAR2(200);',
'    v_email_destino_dger     VARCHAR2(200) := ''ana.vieira@senac.br'';',
'    v_email_remetente      VARCHAR2(200);',
'    v_email_cc             VARCHAR2(1000);',
unistr('    v_assunto_dger         VARCHAR2(200) := ''Solicita\00E7\00E3o de Buffet - Encaminhamento para Delibera\00E7\00E3o'';'),
unistr('    v_assunto_solicitante  VARCHAR2(200) := ''Solicita\00E7\00E3o de Buffet Recebida'';'),
'    v_mensagem_dger        CLOB;',
'    v_mensagem_solicitante CLOB;',
'    v_qtd_horarios         NUMBER;',
'    v_primeiro             BOOLEAN;',
'    l_mail_id_dger         NUMBER;',
'    l_mail_id_solicitante  NUMBER;',
'    v_qtd_itens_pendentes  NUMBER;',
'    v_link_sistema         VARCHAR2(4000);',
'    v_link_solicitacao     VARCHAR2(4000);',
'    v_valor_total          NUMBER := 0;',
'    v_email_solicitante    VARCHAR2(4000);',
'    v_cnt_solicitacao      NUMBER;',
'BEGIN',
'    SELECT COUNT(*)',
'      INTO v_cnt_solicitacao',
'      FROM buf_solicitacao',
'     WHERE id_solicitacao = :P303_ID_SOLICITACAO',
'        AND ind_pendente = ''S'';',
'',
'    IF v_cnt_solicitacao = 0 THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
unistr('            ''N\00E3o h\00E1 solicita\00E7\00E3o cadastrada para a confirma\00E7\00E3o e envio de e-mail.'''),
'        );',
'    END IF;',
'',
'',
'    UPDATE buf_solicitacao',
'       SET ind_analisado = ''N''',
'     WHERE id_solicitacao = :P303_ID_SOLICITACAO;',
'',
'    SELECT vs.nom_pessoa,',
'           u.txt_email_sf,',
'           bs.email_responsavel,',
'           bs.nom_evento',
'      INTO v_nome_solicitante,',
'           v_email_remetente,',
'           v_email_solicitante,',
'           v_evento',
'      FROM dda.vinculo_sf vs',
'      JOIN dda.usuario_rede u',
'        ON vs.num_cpf = u.num_cpf_pessoa',
'      JOIN buf_solicitacao bs',
'        ON bs.id_solicitacao = :P303_ID_SOLICITACAO',
'     WHERE u.txt_login_ad = :APP_USER;',
'',
'    v_email_cc := ''valquiria.hernandes@senac.br,paula.guimaraes@senac.br,francinete.brito@senac.br,asqualog@senado.leg.br,sequalog-equipe@senado.gov.br,'' ||',
'                  COALESCE(v_email_solicitante, '''');',
'',
'    v_email_cc := REGEXP_REPLACE(v_email_cc, '',$'', '''');',
'',
'    SELECT COUNT(*)',
'      INTO v_qtd_itens_pendentes',
'      FROM buf_item_solicitacao bis',
'      JOIN buf_solicitacao bs',
'        ON bis.fk_id_solicitacao = bs.id_solicitacao',
'     WHERE bs.ind_analisado = ''N'';',
'',
'    v_link_sistema     := ''https://dda.senado.leg.br/desenv/r/asqualog/buffet'';',
'    v_link_solicitacao := v_link_sistema;',
'',
'    v_mensagem_dger :=',
'           ''<html>',
'              <body style="font-family: Arial, Helvetica, sans-serif; font-size:14px; color:#333;">',
'                <p>Prezados(as),</p>',
'',
'                <p>',
unistr('                  Foi registrada no Sistema de Buffet a solicita\00E7\00E3o abaixo, encaminhada para delibera\00E7\00E3o dessa Diretoria-Geral.'),
'                </p>',
'',
'                <p>',
unistr('                  Acesse a solicita\00E7\00E3o no sistema:<br>'),
'                  <a href="'' || v_link_solicitacao || ''">'' || v_link_solicitacao || ''</a>',
'                </p>',
'',
'                <p>',
'                  <b>Evento:</b> '' || v_evento || ''<br>',
'                  <b>Solicitante:</b> '' || v_nome_solicitante || ''<br>',
'                  <b>Unidade Solicitante:</b> '' || :SETOR_USUARIO || ''',
'                </p>',
'',
unistr('                <p><b>Servi\00E7os solicitados</b></p>'),
'',
'                <table style="',
'                    border-collapse:collapse;',
'                    width:100%;',
'                    max-width:800px;',
'                    margin-top:10px;',
'                    border:1px solid #ddd;',
'                ">',
'                    <tr style="background-color:#f2f2f2;">',
unistr('                        <th style="padding:8px;border:1px solid #ddd;">Servi\00E7o</th>'),
'                        <th style="padding:8px;border:1px solid #ddd;">Data</th>',
'                        <th style="padding:8px;border:1px solid #ddd;">Motivo Qtde</th>',
'                        <th style="padding:8px;border:1px solid #ddd;">Local</th>',
'                        <th style="padding:8px;border:1px solid #ddd;">Valor</th>',
unistr('                        <th style="padding:8px;border:1px solid #ddd;">Hor\00E1rio</th>'),
unistr('                        <th style="padding:8px;border:1px solid #ddd;">Qtd por Hor\00E1rio</th>'),
'                    </tr>'';',
'',
'    v_valor_total := 0;',
'',
'    FOR item IN (',
'        SELECT i.id_item,',
'               d.descricao,',
'               i.dat_servico,',
'               i.qtd_pessoas,',
'               i.motivo_qtd,',
'               i.local,',
'               i.valor_item',
'          FROM buf_item_solicitacao i',
'          JOIN buf_descricao d',
'            ON i.fk_id_desc = d.id_desc',
'         WHERE i.fk_id_solicitacao = :P303_ID_SOLICITACAO',
'         ORDER BY i.dat_servico',
'    )',
'    LOOP',
'        v_valor_total := v_valor_total + NVL(item.valor_item, 0);',
'',
'        SELECT COUNT(*)',
'          INTO v_qtd_horarios',
'          FROM buf_hor_item',
'         WHERE fk_id_item = item.id_item;',
'',
'        IF v_qtd_horarios = 0 THEN',
'            v_qtd_horarios := 1;',
'        END IF;',
'',
'        v_primeiro := TRUE;',
'',
'        FOR h IN (',
'            SELECT hor, qtd_hor',
'              FROM buf_hor_item',
'             WHERE fk_id_item = item.id_item',
'             ORDER BY hor',
'        )',
'        LOOP',
'            v_mensagem_dger := v_mensagem_dger || ''<tr>'';',
'',
'            IF v_primeiro THEN',
'                v_mensagem_dger := v_mensagem_dger ||',
'                    ''<td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;">''',
'                        || item.descricao || ''</td>',
'                     <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:center;">''',
'                        || TO_CHAR(item.dat_servico, ''DD/MM/YYYY'') || ''</td>',
'                     <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;">''',
'                        || NVL(item.motivo_qtd, ''-'') || ''</td>',
'                     <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;">''',
'                        || item.local || ''</td>',
'                     <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:right;">R$ ''',
'                        || TO_CHAR(item.valor_item, ''FM999G999G990D00'') || ''</td>'';',
'            END IF;',
'',
'            v_mensagem_dger := v_mensagem_dger ||',
'                ''<td style="padding:8px;border:1px solid #ddd;text-align:center;">''',
'                    || NVL(TO_CHAR(h.hor), ''-'') || ''</td>',
'                 <td style="padding:8px;border:1px solid #ddd;text-align:center;">''',
'                    || NVL(TO_CHAR(h.qtd_hor), ''-'') || ''</td>'';',
'',
'            v_mensagem_dger := v_mensagem_dger || ''</tr>'';',
'            v_primeiro := FALSE;',
'        END LOOP;',
'',
'        IF v_primeiro THEN',
'            v_mensagem_dger := v_mensagem_dger ||',
'            ''<tr>',
'                <td style="padding:8px;border:1px solid #ddd;">''||item.descricao||''</td>',
'                <td style="padding:8px;border:1px solid #ddd;text-align:center;">''||TO_CHAR(item.dat_servico,''DD/MM/YYYY'')||''</td>',
'                <td style="padding:8px;border:1px solid #ddd;">''||NVL(item.motivo_qtd, ''-'')||''</td>',
'                <td style="padding:8px;border:1px solid #ddd;">''||item.local||''</td>',
'                <td style="padding:8px;border:1px solid #ddd;text-align:right;">R$ ''||TO_CHAR(item.valor_item,''FM999G999G990D00'')||''</td>',
'                <td style="padding:8px;border:1px solid #ddd;text-align:center;">-</td>',
'                <td style="padding:8px;border:1px solid #ddd;text-align:center;">-</td>',
'            </tr>'';',
'        END IF;',
'    END LOOP;',
'',
'    v_mensagem_dger := v_mensagem_dger ||',
'        ''<tr style="background-color:#f9f9f9;">',
'           <td colspan="4" style="padding:8px;border:1px solid #ddd;text-align:right;"><b>Valor Total:</b></td>',
'           <td style="padding:8px;border:1px solid #ddd;text-align:right;"><b>R$ '' ||',
'              TO_CHAR(v_valor_total, ''FM999G999G990D00'') || ''</b></td>',
'           <td style="padding:8px;border:1px solid #ddd;"></td>',
'           <td style="padding:8px;border:1px solid #ddd;"></td>',
'        </tr>',
'        </table>',
'',
'        <br><br>',
'         <p>',
unistr('           Informamos que, al\00E9m da presente demanda, existem atualmente <b>'' ||'),
unistr('           v_qtd_itens_pendentes || ''</b> solicita\00E7\00F5es pendentes de delibera\00E7\00E3o no Sistema de Buffet.'),
'         </p>',
'',
'         <p>',
unistr('           Solicita-se, por gentileza, a an\00E1lise e manifesta\00E7\00E3o quanto \00E0 aprova\00E7\00E3o da demanda.'),
'         </p>',
'',
'         <p>',
'           Atenciosamente,<br>',
'           <b>Sistema de Buffet</b><br>',
unistr('           Assessoria de Qualidade de Atendimento e Log\00EDstica \2013 ASQUALOG<br>'),
'           Senado Federal',
'         </p>',
'',
'         <p style="font-size:12px;color:#666;margin-top:20px;">',
unistr('           Este \00E9 um e-mail autom\00E1tico do Sistema de Buffet.<br>'),
unistr('           Em caso de d\00FAvidas, contatar: <a href="mailto:asqualog@senado.leg.br">asqualog@senado.leg.br</a>'),
'         </p>',
'',
'        </body>',
'      </html>'';',
'',
'    -- l_mail_id_dger := APEX_MAIL.SEND(',
'    --     p_to        => v_email_destino_dger,',
'    --     p_cc      => v_email_cc,',
'    --     p_from      => v_email_remetente,',
'    --     p_subj      => v_assunto_dger,',
'    --     p_body      => NULL,',
'    --     p_body_html => v_mensagem_dger',
'    -- );',
'',
'    IF v_email_solicitante IS NOT NULL THEN',
'        v_mensagem_solicitante :=',
'           ''<html>',
'              <body style="font-family: Arial, Helvetica, sans-serif; font-size:14px; color:#333;">',
'                <p>Prezado(a),</p>',
'',
'                <p>',
unistr('                  Sua solicita\00E7\00E3o de servi\00E7o de buffet foi registrada com sucesso no Sistema de Buffet e ser\00E1 submetida \00E0 delibera\00E7\00E3o administrativa.'),
'                </p>',
'',
'                <p>',
unistr('                  Acompanhe a solicita\00E7\00E3o:<br>'),
'                  <a href="'' || v_link_solicitacao || ''">'' || v_link_solicitacao || ''</a>',
'                </p>',
'',
'                <p>',
'                  <b>Evento:</b> '' || v_evento || ''',
'                </p>',
'',
unistr('                <p><b>Servi\00E7os solicitados</b></p>'),
'',
'                <table style="',
'                    border-collapse:collapse;',
'                    width:100%;',
'                    max-width:800px;',
'                    margin-top:10px;',
'                    border:1px solid #ddd;',
'                ">',
'                    <tr style="background-color:#f2f2f2;">',
unistr('                        <th style="padding:8px;border:1px solid #ddd;">Servi\00E7o</th>'),
'                        <th style="padding:8px;border:1px solid #ddd;">Data</th>',
unistr('                        <th style="padding:8px;border:1px solid #ddd;">N\00BA de Pessoas</th>'),
unistr('                        <th style="padding:8px;border:1px solid #ddd;">Hor\00E1rio</th>'),
unistr('                        <th style="padding:8px;border:1px solid #ddd;">Quantidade por Hor\00E1rio</th>'),
'                        <th style="padding:8px;border:1px solid #ddd;">Local</th>',
'                        <th style="padding:8px;border:1px solid #ddd;">Valor</th>',
'                    </tr>'';',
'',
'        FOR item2 IN (',
'            SELECT i.id_item,',
'                   d.descricao,',
'                   i.dat_servico,',
'                   i.qtd_pessoas,',
'                   i.motivo_qtd,',
'                   i.local,',
'                   i.valor_item',
'              FROM buf_item_solicitacao i',
'              JOIN buf_descricao d',
'                ON i.fk_id_desc = d.id_desc',
'             WHERE i.fk_id_solicitacao = :P303_ID_SOLICITACAO',
'             ORDER BY i.dat_servico',
'        )',
'        LOOP',
'            SELECT COUNT(*)',
'              INTO v_qtd_horarios',
'              FROM buf_hor_item',
'             WHERE fk_id_item = item2.id_item;',
'',
'            IF v_qtd_horarios = 0 THEN',
'                v_qtd_horarios := 1;',
'            END IF;',
'',
'            v_primeiro := TRUE;',
'',
'            FOR h2 IN (',
'                SELECT hor, qtd_hor',
'                  FROM buf_hor_item',
'                 WHERE fk_id_item = item2.id_item',
'                 ORDER BY hor',
'            )',
'            LOOP',
'                v_mensagem_solicitante := v_mensagem_solicitante || ''<tr>'';',
'',
'                IF v_primeiro THEN',
'                    v_mensagem_solicitante := v_mensagem_solicitante ||',
'                        ''<td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;">''',
'                            || item2.descricao || ''</td>',
'                         <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:center;">''',
'                            || TO_CHAR(item2.dat_servico, ''DD/MM/YYYY'') || ''</td>',
'                         <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:center;">''',
'                            || NVL(TO_CHAR(item2.qtd_pessoas), ''-'') || ''</td>'';',
'                END IF;',
'',
'                v_mensagem_solicitante := v_mensagem_solicitante ||',
'                    ''<td style="padding:8px;border:1px solid #ddd;text-align:center;">''',
'                        || NVL(TO_CHAR(h2.hor), ''-'') || ''</td>',
'                     <td style="padding:8px;border:1px solid #ddd;text-align:center;">''',
'                        || NVL(TO_CHAR(h2.qtd_hor), ''-'') || ''</td>'';',
'',
'                IF v_primeiro THEN',
'                    v_mensagem_solicitante := v_mensagem_solicitante ||',
'                        ''<td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;">''',
'                            || item2.local || ''</td>',
'                         <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:right;">R$ ''',
'                            || TO_CHAR(item2.valor_item, ''FM999G999G990D00'') || ''</td>'';',
'                END IF;',
'',
'                v_mensagem_solicitante := v_mensagem_solicitante || ''</tr>'';',
'                v_primeiro := FALSE;',
'            END LOOP;',
'',
'            IF v_primeiro THEN',
'                v_mensagem_solicitante := v_mensagem_solicitante ||',
'                ''<tr>',
'                    <td style="padding:8px;border:1px solid #ddd;">''||item2.descricao||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">''||TO_CHAR(item2.dat_servico,''DD/MM/YYYY'')||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">''||NVL(TO_CHAR(item2.qtd_pessoas), ''-'')||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">-</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">-</td>',
'                    <td style="padding:8px;border:1px solid #ddd;">''||item2.local||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:right;">R$ ''||TO_CHAR(item2.valor_item,''FM999G999G990D00'')||''</td>',
'                </tr>'';',
'            END IF;',
'        END LOOP;',
'',
'        v_mensagem_solicitante := v_mensagem_solicitante ||',
'            ''</table>',
'',
'             <br><br>',
'             <p>',
unistr('               O solicitante ser\00E1 automaticamente comunicado sobre qualquer atualiza\00E7\00E3o do pedido.'),
'             </p>',
'',
'             <p>',
'               Atenciosamente,<br>',
'               <b>Sistema de Buffet</b><br>',
unistr('               Assessoria de Qualidade de Atendimento e Log\00EDstica \2013 ASQUALOG<br>'),
'               Senado Federal',
'             </p>',
'',
'             <p style="font-size:12px;color:#666;margin-top:20px;">',
unistr('               Este \00E9 um e-mail autom\00E1tico do Sistema de Buffet.<br>'),
unistr('               Em caso de d\00FAvidas, contatar: <a href="mailto:asqualog@senado.leg.br">asqualog@senado.leg.br</a>'),
'             </p>',
'',
'            </body>',
'          </html>'';',
'',
'        l_mail_id_solicitante := APEX_MAIL.SEND(',
'            --p_to        => v_email_solicitante,',
'            --p_cc        => ''sequalog-equipe@senado.gov.br'',',
