unistr('var valor = $v(''P370_HOR'').replace(/\005CD/g, ''''); // Remove tudo que n\00E3o \00E9 n\00FAmero '),
'',
'if (valor.length === 3) { ',
'    valor = valor.substring(0,1) + '':'' + valor.substring(1); ',
'} else if (valor.length >= 4) { ',
'    valor = valor.substring(0,2) + '':'' + valor.substring(2,4); ',
'} // Atualiza o campo ',
