);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(738920088981992487)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('Inserir Hor\00E1rio')
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_count NUMBER;',
'    v_hor_minuto NUMBER;',
'    v_hor_minuto_fim NUMBER;',
'    v_tempo_minutos NUMBER;',
'    v_horario_formatado VARCHAR2(10);',
'    v_conflitos VARCHAR2(4000);',
'',
'    v_hora   VARCHAR2(2);',
'    v_minuto VARCHAR2(2);',
'BEGIN',
'    IF :P370_HOR IS NULL ',
'       OR NOT REGEXP_LIKE(:P370_HOR, ''^\d{1,2}:\d{1,2}$'') THEN',
unistr('        RAISE_APPLICATION_ERROR(-20010, ''Hor\00E1rio inv\00E1lido. Use HH:MM.'');'),
'    END IF;',
'',
'    v_hora   := LPAD(REGEXP_SUBSTR(:P370_HOR, ''^\d{1,2}''), 2, ''0'');',
'    v_minuto := LPAD(REGEXP_SUBSTR(:P370_HOR, ''\d{1,2}$''), 2, ''0'');',
'',
'    v_horario_formatado := v_hora || '':'' || v_minuto;',
'',
'    v_hor_minuto := TO_NUMBER(v_hora) * 60 + TO_NUMBER(v_minuto);',
'',
'    SELECT NVL(bd.tempo_minutos, 0)',
'    INTO v_tempo_minutos',
'    FROM buf_descricao bd',
'    JOIN buf_item_solicitacao bi ',
'        ON bi.fk_id_desc = bd.id_desc',
'    WHERE bi.id_item = :P370_ID_ITEM;',
'',
'    v_hor_minuto_fim := v_hor_minuto + v_tempo_minutos;',
'',
'    IF (v_hor_minuto BETWEEN 720 AND 900) ',
'       OR (v_hor_minuto_fim BETWEEN 720 AND 900) THEN',
unistr('        RAISE_APPLICATION_ERROR(-20002, ''N\00E3o \00E9 permitido entre 12:00 e 15:00.'');'),
'    END IF;',
'',
'    SELECT LISTAGG(',
unistr('               DISTINCT ''Conflito: '' || h.hor || '' at\00E9 '' || '),
'               LPAD(FLOOR((h.hor_minuto + NVL(bd.tempo_minutos, 0)) / 60), 2, ''0'') || '':'' || ',
'               LPAD(MOD((h.hor_minuto + NVL(bd.tempo_minutos, 0)), 60), 2, ''0'') || '' (Interno)'' || CHR(10)',
'           ) WITHIN GROUP (ORDER BY h.hor)',
'    INTO v_conflitos',
'    FROM buf_hor_item h',
'    JOIN buf_item_solicitacao i ON i.id_item = h.fk_id_item',
'    JOIN buf_descricao bd ON bd.id_desc = i.fk_id_desc',
'    WHERE i.dat_servico = (',
'            SELECT dat_servico ',
'            FROM buf_item_solicitacao ',
'            WHERE id_item = :P370_ID_ITEM',
'      )',
'      AND (',
'            (h.hor_minuto < v_hor_minuto_fim AND (h.hor_minuto + NVL(bd.tempo_minutos, 0)) > v_hor_minuto)',
'      );',
'',
'        IF v_conflitos IS NULL THEN',
'        SELECT LISTAGG(',
'                   DISTINCT ''Conflito: '' || ',
'                   LPAD(TO_NUMBER(SUBSTR(ie.hor_inicio,1,INSTR(ie.hor_inicio,'':'')-1)), 2, ''0'') || '':'' ||',
unistr('                   LPAD(TO_NUMBER(SUBSTR(ie.hor_inicio,INSTR(ie.hor_inicio,'':'')+1)), 2, ''0'') || '' at\00E9 '' ||'),
'                   LPAD(FLOOR((',
'                        (',
'                          TO_NUMBER(SUBSTR(ie.hor_inicio,1,INSTR(ie.hor_inicio,'':'')-1)) * 60',
'                        + TO_NUMBER(SUBSTR(ie.hor_inicio,INSTR(ie.hor_inicio,'':'')+1))',
'                        )',
'                        + NVL(bd.tempo_minutos, 0)',
'                   ) / 60), 2, ''0'') || '':'' ||',
'                   LPAD(MOD((',
'                        (',
'                          TO_NUMBER(SUBSTR(ie.hor_inicio,1,INSTR(ie.hor_inicio,'':'')-1)) * 60',
'                        + TO_NUMBER(SUBSTR(ie.hor_inicio,INSTR(ie.hor_inicio,'':'')+1))',
'                        )',
'                        + NVL(bd.tempo_minutos, 0)',
'                   ), 60), 2, ''0'') || ',
'                   '' (Externo - '' || se.nom_evento || '')'' || CHR(10)',
'               ) WITHIN GROUP (ORDER BY ie.hor_inicio, ie.hor_minuto)',
'        INTO v_conflitos',
'        FROM buf_item_solicitacao_ext ie',
'        JOIN buf_solicitacao_ext se ON se.id_solicitacao_ext = ie.fk_id_solicitacao_ext',
'        JOIN buf_descricao bd ON bd.id_desc = ie.fk_id_desc',
'        WHERE ie.dat_evento = (',
'                SELECT dat_servico ',
'                FROM buf_item_solicitacao ',
'                WHERE id_item = :P370_ID_ITEM',
'        )',
'          AND (',
'                (',
'                  (',
'                    TO_NUMBER(SUBSTR(ie.hor_inicio,1,INSTR(ie.hor_inicio,'':'')-1)) * 60',
'                  + TO_NUMBER(SUBSTR(ie.hor_inicio,INSTR(ie.hor_inicio,'':'')+1))',
'                  ) < v_hor_minuto_fim',
'                AND',
'                  (',
'                    (',
'                      TO_NUMBER(SUBSTR(ie.hor_inicio,1,INSTR(ie.hor_inicio,'':'')-1)) * 60',
'                    + TO_NUMBER(SUBSTR(ie.hor_inicio,INSTR(ie.hor_inicio,'':'')+1))',
'                    )',
'                    + NVL(bd.tempo_minutos, 0)',
'                  ) > v_hor_minuto',
'                )',
'          );',
'    END IF;',
'',
'    IF v_conflitos IS NOT NULL THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20003,',
unistr('            ''J\00E1 existe um hor\00E1rio cadastrado que conflita com este intervalo:'' || CHR(10) || v_conflitos'),
'        );',
'    END IF;',
'',
'    IF TO_NUMBER(NVL(:P370_QTD_HOR, ''0'')) > TO_NUMBER(NVL(:P370_QTD_REST, ''0'')) THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20099,',
'            ''QTD_HOR='' || :P370_QTD_HOR || '' | QTD_REST='' || :P370_QTD_REST',
'        );',
'    END IF;',
'',
'    INSERT INTO buf_hor_item (',
'        hor,',
'        qtd_hor,',
'        fk_id_item,',
'        hor_minuto,',
'        hor_minuto_fim',
'    ) VALUES (',
'        v_horario_formatado,',
'        TO_NUMBER(:P370_QTD_HOR),',
'        :P370_ID_ITEM,',
'        v_hor_minuto,',
'        v_hor_minuto_fim',
'    );',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>523042367575766830
);
end;
/
