wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(738952670982086741)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Deletar Item'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_qtd_pessoas   NUMBER;',
'    v_id_desc       NUMBER;',
'    v_dat_servico   DATE;',
'',
'    v_antecedencia  NUMBER;',
'    v_dias_faltam   NUMBER;',
'BEGIN',
'    SELECT qtd_pessoas, fk_id_desc, dat_servico',
'    INTO v_qtd_pessoas, v_id_desc, v_dat_servico',
'    FROM buf_item_solicitacao',
'    WHERE id_item = :P371_ID_ITEM;',
'',
'    SELECT antecedencia INTO v_antecedencia',
'    FROM buf_descricao',
'    WHERE id_desc = v_id_desc;',
'',
'    v_dias_faltam := TRUNC(v_dat_servico) - TRUNC(SYSDATE);',
'',
'    IF v_dias_faltam <= v_antecedencia THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
unistr('            ''N\00E3o \00E9 poss\00EDvel deletar este item. O prazo de anteced\00EAncia m\00EDnimo de '' || v_antecedencia || '' dia(s) n\00E3o foi respeitado.'''),
'        );',
'    END IF;',
'',
'    UPDATE buf_descricao',
'    SET qtd_disponivel = qtd_disponivel + v_qtd_pessoas',
'    WHERE id_desc = v_id_desc;',
'',
'    DELETE FROM buf_hor_item',
'    WHERE fk_id_item = :P371_ID_ITEM;',
'',
'    -- Exclui o item',
'    DELETE FROM buf_item_solicitacao',
'    WHERE id_item = :P371_ID_ITEM;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(738946106578086710)
,p_internal_uid=>523074949575861084
);
end;
