wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(744184753853623531)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Deletar Evento e Itens'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_evento            VARCHAR2(4000);',
'',
'    v_nome_solicitante  VARCHAR2(200);',
'    v_email_destino     VARCHAR2(200) := ''sequalog-equipe@senado.gov.br'';',
'    v_email_remetente   VARCHAR2(200);',
'    v_email_cc          VARCHAR2(4000);',
'',
unistr('    v_assunto           VARCHAR2(200) := ''Cancelamento de Solicita\00E7\00E3o de Buffet'';'),
'    v_mensagem          CLOB;',
'',
'    v_qtd_horarios      NUMBER;',
'    v_primeiro          BOOLEAN;',
'',
'    v_itens_invalidos   NUMBER;',
'    v_link_solicitacao  VARCHAR2(4000);',
'    v_ind_analisado     VARCHAR2(1);',
'    v_email_solicitante VARCHAR2(4000);',
'BEGIN',
'    SELECT vs.nom_pessoa, u.txt_email_sf ',
'      INTO v_nome_solicitante, v_email_remetente',
'      FROM dda.vinculo_sf vs',
'      JOIN dda.usuario_rede u ',
'        ON vs.num_cpf = u.num_cpf_pessoa',
'     WHERE u.txt_login_ad = :APP_USER;',
'',
'    SELECT nom_evento,',
'           email_responsavel,',
'           ind_analisado',
'      INTO v_evento,',
'           v_email_solicitante,',
'           v_ind_analisado',
'      FROM buf_solicitacao',
'     WHERE id_solicitacao = :P372_ID_SOLICITACAO;',
'',
unistr('    -- monta v_email_cc com lista fixa + respons\00E1veis'),
'    v_email_cc := ''guilherme.schettini@senado.leg.br,LAFUENTE@senado.leg.br,asqualog@senado.leg.br,'' ||',
'                  COALESCE(v_email_solicitante, '''');',
'',
'    v_email_cc := REGEXP_REPLACE(v_email_cc, '',$'', '''');',
'',
unistr('    -- monta link para a solicita\00E7\00E3o no sistema (ajuste a URL conforme sua aplica\00E7\00E3o)'),
'    v_link_solicitacao := ''https://dda.senado.leg.br/desenv/r/asqualog/buffet'';',
'',
'    SELECT COUNT(*)',
'      INTO v_itens_invalidos',
'      FROM buf_item_solicitacao i',
'      JOIN buf_descricao d ON i.fk_id_desc = d.id_desc',
'     WHERE i.fk_id_solicitacao = :P372_ID_SOLICITACAO',
'       AND (TRUNC(i.dat_servico) - TRUNC(SYSDATE)) <= d.antecedencia;',
'',
'    IF v_itens_invalidos > 0 THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
unistr('            ''N\00E3o \00E9 poss\00EDvel cancelar esse evento. Um ou mais itens n\00E3o possuem a anteced\00EAncia m\00EDnima.'''),
'        );',
'    END IF;',
'',
'    v_mensagem :=',
'       ''<html>',
'            <body style="font-family: Arial, Helvetica, sans-serif; font-size:14px; color:#333;">',
'                <p>Prezados(as),</p>',
'',
'                <p>',
unistr('                    Informamos o cancelamento total ou parcial da solicita\00E7\00E3o de servi\00E7o de buffet abaixo identificada, conforme registro efetuado no Sistema de Buffet.'),
'                </p>',
'',
'                <p>',
unistr('                    O cancelamento poder\00E1 abranger a integralidade da solicita\00E7\00E3o ou apenas parte dos servi\00E7os originalmente previstos, devendo prevalecer as informa\00E7\00F5es atualizadas constantes no sistema.'),
'                </p>',
'',
'                <p>',
unistr('                    <b>Acesso \00E0 solicita\00E7\00E3o no sistema:</b><br>'),
'                    <a href="'' || v_link_solicitacao || ''">'' || v_link_solicitacao || ''</a>',
'                </p>',
'',
'                <p>',
'                    <b>Evento:</b> '' || v_evento || ''<br>',
'                    <b>Solicitante:</b> '' || v_nome_solicitante || ''<br>',
'                    <b>Unidade Solicitante:</b> '' || :SETOR_USUARIO || ''',
'                </p>',
'',
unistr('                <p><b>Servi\00E7os cancelados</b></p>'),
'',
'                <table style="',
'                    border-collapse:collapse;',
'                    width:100%;',
'                    max-width:800px;',
'                    margin-top:10px;',
'                    border:1px solid #ddd;',
'                ">',
'                    <tr style="background-color:#f8d7da;">',
unistr('                        <th style="padding:8px;border:1px solid #ddd;">Servi\00E7o</th>'),
'                        <th style="padding:8px;border:1px solid #ddd;">Data</th>',
unistr('                        <th style="padding:8px;border:1px solid #ddd;">N\00BA de Pessoas</th>'),
unistr('                        <th style="padding:8px;border:1px solid #ddd;">Hor\00E1rio</th>'),
unistr('                        <th style="padding:8px;border:1px solid #ddd;">Quantidade por Hor\00E1rio</th>'),
'                        <th style="padding:8px;border:1px solid #ddd;">Local</th>',
'                        <th style="padding:8px;border:1px solid #ddd;">Valor</th>',
'                    </tr>'';',
'',
'    FOR item IN (',
'        SELECT',
'            i.id_item, ',
'            i.fk_id_desc,',
'            d.descricao,',
'            i.dat_servico,',
'            i.qtd_pessoas,',
'            i.local,',
'            i.valor_item,',
'            i.status',
'          FROM buf_item_solicitacao i',
'          JOIN buf_descricao d ',
'            ON i.fk_id_desc = d.id_desc',
'         WHERE i.fk_id_solicitacao = :P372_ID_SOLICITACAO',
'         ORDER BY i.dat_servico, d.descricao',
'    )',
'    LOOP',
unistr('        -- Regra de devolu\00E7\00E3o de estoque:'),
unistr('        -- 1) Sempre devolve se Contratado ou Em negocia\00E7\00E3o'),
unistr('        IF item.status IN (''Contratado'', ''Em negocia\00E7\00E3o'') THEN'),
'            UPDATE buf_descricao',
'               SET qtd_disponivel = qtd_disponivel + item.qtd_pessoas',
'             WHERE id_desc = item.fk_id_desc;',
'        END IF;',
'',
unistr('        -- 2) Se ind_analisado = ''N'', tamb\00E9m devolve os Cancelados'),
'        IF v_ind_analisado = ''N''',
'           AND item.status = ''Cancelado'' THEN',
'            UPDATE buf_descricao',
'               SET qtd_disponivel = qtd_disponivel + item.qtd_pessoas',
'             WHERE id_desc = item.fk_id_desc;',
'        END IF;',
'',
'        SELECT COUNT(*)',
'          INTO v_qtd_horarios',
'          FROM buf_hor_item',
'         WHERE fk_id_item = item.id_item;',
'',
'        IF v_qtd_horarios = 0 THEN',
'            v_qtd_horarios := 1;',
'        END IF;',
'',
'        v_primeiro := TRUE;',
'',
'        FOR h IN (',
'            SELECT hor, qtd_hor',
'              FROM buf_hor_item',
'             WHERE fk_id_item = item.id_item',
'             ORDER BY hor',
'        )',
'        LOOP',
'            v_mensagem := v_mensagem || ''<tr>'';',
'',
'            IF v_primeiro THEN',
'                v_mensagem := v_mensagem ||',
'                    ''<td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;">''',
'                        || item.descricao || ''</td>',
'                     <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:center;">''',
'                        || TO_CHAR(item.dat_servico,''DD/MM/YYYY'') || ''</td>',
'                     <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:center;">''',
'                        || item.qtd_pessoas || ''</td>'';',
'            END IF;',
'',
'            v_mensagem := v_mensagem ||',
'                ''<td style="padding:8px;border:1px solid #ddd;text-align:center;">''',
'                    || NVL(TO_CHAR(h.hor), ''-'') || ''</td>',
'                 <td style="padding:8px;border:1px solid #ddd;text-align:center;">''',
'                    || NVL(TO_CHAR(h.qtd_hor), ''-'') || ''</td>'';',
'',
'            IF v_primeiro THEN',
'                v_mensagem := v_mensagem ||',
'                    ''<td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;">''',
'                        || item.local || ''</td>',
'                     <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:right;">R$ ''',
'                        || TO_CHAR(item.valor_item,''FM999G999G990D00'') || ''</td>'';',
'',
'                v_primeiro := FALSE;',
'            END IF;',
'',
'            v_mensagem := v_mensagem || ''</tr>'';',
'        END LOOP;',
'',
'        IF v_primeiro THEN',
'            v_mensagem := v_mensagem ||',
'                ''<tr>',
'                    <td style="padding:8px;border:1px solid #ddd;">''||item.descricao||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">''||TO_CHAR(item.dat_servico,''DD/MM/YYYY'')||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">''||item.qtd_pessoas||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">-</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">-</td>',
'                    <td style="padding:8px;border:1px solid #ddd;">''||item.local||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:right;">R$ ''||TO_CHAR(item.valor_item,''FM999G999G990D00'')||''</td>',
'                </tr>'';',
'        END IF;',
'',
'    END LOOP;',
'',
'    v_mensagem := v_mensagem ||',
'        ''</table>',
'         <br><br>',
'         <p>',
'            Atenciosamente,<br>',
'            <b>Sistema de Buffet</b><br>',
unistr('            Assessoria de Qualidade de Atendimento e Log\00EDstica \2013 ASQUALOG<br>'),
'            Senado Federal',
'         </p>',
'',
'         <p style="font-size:12px;color:#666;margin-top:20px;">',
unistr('            Este \00E9 um e-mail autom\00E1tico do Sistema de Buffet.<br>'),
unistr('            Em caso de d\00FAvidas, contatar: <a href="mailto:asqualog@senado.leg.br">asqualog@senado.leg.br</a>'),
'         </p>',
'        </body>',
'    </html>'';',
'',
'    APEX_MAIL.SEND (',
'        p_to        => v_email_destino,',
'        p_cc        => v_email_cc,',
'        p_from      => v_email_remetente,',
'        p_subj      => v_assunto,',
'        p_body      => NULL,',
'        p_body_html => v_mensagem',
'    );',
'',
'    APEX_MAIL.PUSH_QUEUE;',
'',
'    DELETE FROM buf_feedback',
'     WHERE fk_id_solicitacao = :P372_ID_SOLICITACAO;',
'',
'    DELETE FROM buf_anexo',
'     WHERE fk_id_solicitacao = :P372_ID_SOLICITACAO;',
'',
'    DELETE FROM buf_hor_item',
'     WHERE fk_id_item IN (',
'            SELECT id_item',
'              FROM buf_item_solicitacao',
'             WHERE fk_id_solicitacao = :P372_ID_SOLICITACAO',
'     );',
'',
'    DELETE FROM buf_item_solicitacao',
'     WHERE fk_id_solicitacao = :P372_ID_SOLICITACAO;',
'',
'    DELETE FROM buf_solicitacao',
'     WHERE id_solicitacao = :P372_ID_SOLICITACAO;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>528307032447397874
);
end;
