'BEGIN',
'    DECLARE',
'        v_minuto_ini        NUMBER;',
'        v_minuto_duracao    NUMBER;',
'        v_minuto_fim        NUMBER;',
'        v_hora_fim          NUMBER;',
'        v_min_fim           NUMBER;',
'    BEGIN',
'        SELECT hor_minuto INTO v_minuto_ini',
'        FROM buf_item_solicitacao_ext',
'        WHERE id_item_solicitacao_ext = :P373_ID_ITEM;',
'',
'        SELECT tempo_minutos INTO v_minuto_duracao',
'        FROM buf_descricao',
'        WHERE id_desc = (',
'            SELECT fk_id_desc',
'            FROM buf_item_solicitacao_ext',
'            WHERE id_item_solicitacao_ext = :P373_ID_ITEM',
'        );',
'',
'        v_minuto_fim := v_minuto_ini + v_minuto_duracao;',
'        v_hora_fim := TRUNC(v_minuto_fim / 60);',
'        v_min_fim := MOD(v_minuto_fim, 60);',
'',
'        RETURN LPAD(v_hora_fim, 2, ''0'') || '':'' || LPAD(v_min_fim, 2, ''0'');',
'        ',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            RETURN ''-'';',
'        WHEN OTHERS THEN',
'            RETURN ''Erro'';',
'    END;',
'END;'))
