wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(748719277313756492)
,p_process_sequence=>20
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Adicionar Item'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_conflitos VARCHAR2(4000);',
'    v_total_qtd     NUMBER;',
'    v_qtd_pessoas   NUMBER;',
'    v_hor_minuto    NUMBER;',
'    v_hor_minuto_fim NUMBER;',
'    v_tempo_minutos NUMBER;',
'    v_horario_formatado VARCHAR2(10);',
'    v_fk_id_desc    NUMBER;',
'BEGIN',
'    IF :P375_HORARIO IS NOT NULL THEN',
'',
unistr('        -- Formatar hor\00E1rio para sempre ter 2 d\00EDgitos (9:00 vira 09:00)'),
'        v_horario_formatado := LPAD(SUBSTR(:P375_HORARIO, 1, INSTR(:P375_HORARIO, '':'') - 1), 2, ''0'') || '':'' || SUBSTR(:P375_HORARIO, INSTR(:P375_HORARIO, '':'') + 1);',
'',
'        -- Converter HH:MM para minutos',
'        v_hor_minuto := (TO_NUMBER(SUBSTR(v_horario_formatado, 1, 2)) * 60) + ',
'                        TO_NUMBER(SUBSTR(v_horario_formatado, 4, 2));',
'',
unistr('        -- Buscar tempo_minutos da descri\00E7\00E3o'),
'        SELECT bis.fk_id_desc, bd.tempo_minutos',
'        INTO v_fk_id_desc, v_tempo_minutos',
'        FROM buf_item_solicitacao bis',
'        JOIN buf_descricao bd ON bd.id_desc = bis.fk_id_desc',
'        WHERE bis.id_item = :P375_ID_ITEM;',
'',
'        -- Calcular hor_minuto_fim',
'        v_hor_minuto_fim := v_hor_minuto + NVL(v_tempo_minutos, 0);',
'',
unistr('        -- Validar se hor_minuto ou hor_minuto_fim est\00E3o entre 720-900'),
'        IF v_fk_id_desc <> 7 THEN',
'            IF (v_hor_minuto BETWEEN 720 AND 899) OR (v_hor_minuto_fim BETWEEN 720 AND 899) THEN',
'                RAISE_APPLICATION_ERROR(',
'                    -20002,',
unistr('                    ''Hor\00E1rio n\00E3o permitido. O intervalo entre 12:00 (720 minutos) e 15:00 (900 minutos) \00E9 indispon\00EDvel.'''),
'                );',
'            END IF;',
'        END IF;',
'',
unistr('        -- Verificar conflitos com eventos INTERNOS considerando o tempo de dura\00E7\00E3o do servi\00E7o'),
'        SELECT LISTAGG(',
unistr('                   DISTINCT TO_CHAR(i.dat_servico, ''DD/MM/YYYY'') || '' - '' || h.hor || '' at\00E9 '' || '),
'                   LPAD(FLOOR((h.hor_minuto + NVL(bd.tempo_minutos, 0)) / 60), 2, ''0'') || '':'' || ',
'                   LPAD(MOD((h.hor_minuto + NVL(bd.tempo_minutos, 0)), 60), 2, ''0'') || '' (Interno)'' || CHR(10)',
'               ) WITHIN GROUP (ORDER BY TO_CHAR(i.dat_servico, ''DD/MM/YYYY''), h.hor)',
'        INTO v_conflitos',
'        FROM buf_hor_item h',
'        JOIN buf_item_solicitacao i ON i.id_item = h.fk_id_item',
'        JOIN buf_descricao bd ON bd.id_desc = i.fk_id_desc',
'        WHERE i.dat_servico = :P375_DAT_SERVICO',
'          AND h.fk_id_item != :P375_ID_ITEM',
'          AND (',
unistr('                -- Conflito: hor\00E1rio existente se sobrep\00F5e com o novo'),
'                (h.hor_minuto < v_hor_minuto_fim AND (h.hor_minuto + NVL(bd.tempo_minutos, 0)) > v_hor_minuto)',
'          );',
'',
'        -- Verificar conflitos com eventos EXTERNOS',
'        SELECT LISTAGG(',
'                   DISTINCT TO_CHAR(ie.dat_evento, ''DD/MM/YYYY'') || '' - '' || ',
unistr('                   LPAD(ie.hor_inicio, 2, ''0'') || '':'' || LPAD(ie.hor_minuto, 2, ''0'') || '' at\00E9 '' ||'),
'                   LPAD(FLOOR((ie.hor_minuto + NVL(bd.tempo_minutos, 0)) / 60), 2, ''0'') || '':'' ||',
'                   LPAD(MOD((ie.hor_minuto + NVL(bd.tempo_minutos, 0)), 60), 2, ''0'') || '' (Externo - '' || se.nom_evento || '')'' || CHR(10)',
'               ) WITHIN GROUP (ORDER BY TO_CHAR(ie.dat_evento, ''DD/MM/YYYY''))',
'        INTO v_conflitos',
'        FROM buf_item_solicitacao_ext ie',
'        JOIN buf_solicitacao_ext se ON se.id_solicitacao_ext = ie.fk_id_solicitacao_ext',
'        JOIN buf_descricao bd ON bd.id_desc = ie.fk_id_desc',
'        WHERE ie.dat_evento = :P375_DAT_SERVICO',
'          AND (',
unistr('                -- Conflito: hor\00E1rio externo se sobrep\00F5e com o novo'),
'                (ie.hor_minuto < v_hor_minuto_fim AND (ie.hor_minuto + NVL(bd.tempo_minutos, 0)) > v_hor_minuto)',
'          );',
'',
'    ELSE',
'        SELECT LISTAGG(info, CHR(10))',
'               WITHIN GROUP (ORDER BY info)',
'        INTO v_conflitos',
'        FROM (',
'            SELECT DISTINCT',
'                   TO_CHAR(i1.dat_servico, ''DD/MM/YYYY'') || '' - '' || h1.hor AS info',
'            FROM buf_hor_item h1',
'            JOIN buf_item_solicitacao i1',
'              ON i1.id_item = h1.fk_id_item',
'            WHERE h1.fk_id_item = :P375_ID_ITEM',
'              AND i1.dat_servico = :P375_DAT_SERVICO',
'              AND EXISTS (',
'                    SELECT 1',
'                    FROM buf_hor_item h2',
'                    JOIN buf_item_solicitacao i2',
'                      ON i2.id_item = h2.fk_id_item',
'                    WHERE h2.hor = h1.hor',
'                      AND i2.dat_servico = i1.dat_servico',
'                      AND h2.fk_id_item != h1.fk_id_item',
'              )',
'        );',
'',
'        SELECT NVL(SUM(qtd_hor), 0)',
'        INTO v_total_qtd',
'        FROM buf_hor_item',
'        WHERE fk_id_item = :P375_ID_ITEM;',
'',
'        SELECT qtd_pessoas',
'        INTO v_qtd_pessoas',
'        FROM buf_item_solicitacao i ',
'        WHERE i.id_item = :P375_ID_ITEM;',
'',
'        IF v_total_qtd != v_qtd_pessoas THEN',
'            RAISE_APPLICATION_ERROR(',
'                -20001,',
unistr('                ''A soma das quantidades dos hor\00E1rios deve ser igual \00E0 quantidade de pessoas.'''),
'            );',
'        END IF;',
'',
'    END IF;',
'',
'    IF v_conflitos IS NOT NULL THEN',
'        DELETE FROM buf_hor_item',
'        WHERE fk_id_item = :P375_ID_ITEM;',
'',
'        RAISE_APPLICATION_ERROR(',
'            -20003,',
unistr('            ''Conflito de hor\00E1rio:'' || CHR(10) || v_conflitos'),
'        );',
'',
'    ELSIF :P375_HORARIO IS NOT NULL THEN',
'        INSERT INTO buf_hor_item (',
'            hor,',
'            qtd_hor,',
'            fk_id_item,',
'            hor_minuto,',
'            hor_minuto_fim',
'        ) VALUES (',
'            v_horario_formatado,',
'            :P375_QTD,',
'            :P375_ID_ITEM,',
'            v_hor_minuto,',
'            v_hor_minuto_fim',
'        );',
'    END IF;',
'',
'    COMMIT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(748705311266756372)
,p_internal_uid=>532841555907530835
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(758918501160267073)
,p_process_sequence=>30
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Deletar Evento'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_qtd_pessoas   NUMBER;',
'    v_id_desc       NUMBER;',
'BEGIN',
'    SELECT qtd_pessoas, fk_id_desc',
'    INTO v_qtd_pessoas, v_id_desc',
'    FROM buf_item_solicitacao',
'    WHERE id_item = :P375_ID_ITEM;',
'',
'    UPDATE buf_descricao',
'    SET qtd_disponivel = qtd_disponivel + v_qtd_pessoas',
'    WHERE id_desc = v_id_desc;',
'',
'    DELETE FROM buf_hor_item',
'    WHERE fk_id_item = :P375_ID_ITEM;',
'',
'    -- Exclui o item',
'    DELETE FROM buf_item_solicitacao',
'    WHERE id_item = :P375_ID_ITEM;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(758918249646267071)
,p_internal_uid=>543040779754041416
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(758920683954267095)
,p_process_sequence=>40
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('Adicionar Cafe da Manh\00E3')
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_conflitos         VARCHAR2(4000);',
'    v_total_qtd         NUMBER;',
'    v_qtd_pessoas       NUMBER;',
'    v_hor_minuto        NUMBER;',
'    v_hor_minuto_fim    NUMBER;',
'    v_tempo_minutos     NUMBER;',
'    v_horario_formatado VARCHAR2(10);',
'',
'    v_hor_inicio_num    NUMBER;',
'BEGIN',
'    IF :P375_HORARIO_CAFE IS NOT NULL THEN',
'',
'        -- Garante formato HH:MM (ex.: 9:00 vira 09:00)',
'        v_horario_formatado := LPAD(SUBSTR(:P375_HORARIO_CAFE, 1, INSTR(:P375_HORARIO_CAFE, '':'') - 1), 2, ''0'') ',
'                               || '':'' || SUBSTR(:P375_HORARIO_CAFE, INSTR(:P375_HORARIO_CAFE, '':'') + 1);',
'',
'        -- Converter HH:MM para minutos (seguro)',
'        v_hor_minuto := (TO_NUMBER(SUBSTR(v_horario_formatado, 1, 2)) * 60) + ',
'                        TO_NUMBER(SUBSTR(v_horario_formatado, 4, 2));',
'',
unistr('        -- Buscar tempo_minutos da descri\00E7\00E3o'),
'        SELECT tempo_minutos',
'          INTO v_tempo_minutos',
'          FROM buf_descricao',
'         WHERE id_desc = (',
'                SELECT fk_id_desc',
'                  FROM buf_item_solicitacao',
'                 WHERE id_item = :P375_ID_ITEM',
'              );',
'',
'        -- Calcular hor_minuto_fim',
'        v_hor_minuto_fim := v_hor_minuto + NVL(v_tempo_minutos, 0);',
'',
unistr('        -- Validar intervalo proibido (12:00\201315:00)'),
'        IF (v_hor_minuto BETWEEN 720 AND 900) OR (v_hor_minuto_fim BETWEEN 720 AND 900) THEN',
'            RAISE_APPLICATION_ERROR(',
'                -20002,',
unistr('                ''Hor\00E1rio n\00E3o permitido. O intervalo entre 12:00 (720 minutos) e 15:00 (900 minutos) \00E9 indispon\00EDvel.'''),
'            );',
'        END IF;',
'',
'        SELECT LISTAGG(',
unistr('                   DISTINCT TO_CHAR(i.dat_servico, ''DD/MM/YYYY'') || '' - '' || h.hor || '' at\00E9 '' || '),
'                   LPAD(FLOOR((h.hor_minuto + NVL(bd.tempo_minutos, 0)) / 60), 2, ''0'') || '':'' || ',
'                   LPAD(MOD((h.hor_minuto + NVL(bd.tempo_minutos, 0)), 60), 2, ''0'') || '' (Interno)'' || CHR(10)',
'               ) WITHIN GROUP (ORDER BY TO_CHAR(i.dat_servico, ''DD/MM/YYYY''), h.hor)',
'          INTO v_conflitos',
'          FROM buf_hor_item h',
'          JOIN buf_item_solicitacao i ON i.id_item = h.fk_id_item',
'          JOIN buf_descricao bd ON bd.id_desc = i.fk_id_desc',
'         WHERE i.dat_servico = :P375_DAT_SERVICO',
'           AND h.fk_id_item != :P375_ID_ITEM',
'           AND (h.hor_minuto < v_hor_minuto_fim AND (h.hor_minuto + NVL(bd.tempo_minutos, 0)) > v_hor_minuto);',
'',
'        IF v_conflitos IS NULL THEN',
'            SELECT LISTAGG(',
'                       DISTINCT TO_CHAR(ie.dat_evento, ''DD/MM/YYYY'') || '' - '' || ',
unistr('                       LPAD(TO_NUMBER(ie.hor_inicio), 2, ''0'') || '':'' || LPAD(ie.hor_minuto, 2, ''0'') || '' at\00E9 '' ||'),
'                       LPAD(FLOOR(((TO_NUMBER(ie.hor_inicio) * 60 + ie.hor_minuto) + NVL(bd.tempo_minutos, 0)) / 60), 2, ''0'') || '':'' ||',
'                       LPAD(MOD(((TO_NUMBER(ie.hor_inicio) * 60 + ie.hor_minuto) + NVL(bd.tempo_minutos, 0)), 60), 2, ''0'') || ',
'                       '' (Externo - '' || se.nom_evento || '')'' || CHR(10)',
'                   ) WITHIN GROUP (ORDER BY TO_CHAR(ie.dat_evento, ''DD/MM/YYYY''))',
'              INTO v_conflitos',
'              FROM buf_item_solicitacao_ext ie',
'              JOIN buf_solicitacao_ext se ON se.id_solicitacao_ext = ie.fk_id_solicitacao_ext',
'              JOIN buf_descricao bd ON bd.id_desc = ie.fk_id_desc',
'             WHERE ie.dat_evento = :P375_DAT_SERVICO',
unistr('               AND REGEXP_LIKE(ie.hor_inicio, ''^\005Cd+$'')  -- s\00F3 hor\00E1rios num\00E9ricos'),
'               AND (',
'                    ((TO_NUMBER(ie.hor_inicio) * 60 + ie.hor_minuto) < v_hor_minuto_fim AND ',
'                     ((TO_NUMBER(ie.hor_inicio) * 60 + ie.hor_minuto) + NVL(bd.tempo_minutos, 0)) > v_hor_minuto)',
'               );',
'        END IF;',
'',
'    END IF;',
'',
'    IF v_conflitos IS NOT NULL THEN',
'        DELETE FROM buf_hor_item',
'        WHERE fk_id_item = :P375_ID_ITEM;',
'',
'        RAISE_APPLICATION_ERROR(',
'            -20003,',
unistr('            ''Conflito de hor\00E1rio:'' || CHR(10) || v_conflitos'),
'        );',
'',
'    ELSIF :P375_HORARIO_CAFE IS NOT NULL THEN',
'        INSERT INTO buf_hor_item (',
'            hor,',
'            qtd_hor,',
'            fk_id_item,',
'            hor_minuto,',
'            hor_minuto_fim',
'        ) VALUES (',
'            v_horario_formatado,',
'            :P375_QTD,',
'            :P375_ID_ITEM,',
'            v_hor_minuto,',
'            v_hor_minuto_fim',
'        );',
'    END IF;',
'',
'    COMMIT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(758920565354267094)
,p_internal_uid=>543042962548041438
);
end;
