wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(757779432556945286)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Deletar Item'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_email_destino VARCHAR2(200) := ''sequalog-equipe@senado.gov.br'';',
'    v_email_cc      VARCHAR2(4000);',
'    v_subj          VARCHAR2(200) := ''Item de Buffet cancelado'';',
'',
'    v_qtd_pessoas       NUMBER;',
'    v_id_desc           NUMBER;',
'    v_nom_evento        VARCHAR2(4000);',
'    v_nom_descricao     VARCHAR2(4000);',
'    v_dat_servico       DATE;',
'    v_local             VARCHAR2(200);',
'    v_valor_item        NUMBER;',
'    v_email_body        CLOB;',
'BEGIN',
'    SELECT ',
'        bis.qtd_pessoas,',
'        bis.fk_id_desc,',
'        bis.dat_servico,',
'        bis.local,',
'        bis.valor_item,',
'        bs.nom_evento,',
'        bd.descricao,',
'        bs.email_responsavel',
'    INTO ',
'        v_qtd_pessoas,',
'        v_id_desc,',
'        v_dat_servico,',
'        v_local,',
'        v_valor_item,',
'        v_nom_evento,',
'        v_nom_descricao,',
'        v_email_cc',
'    FROM buf_item_solicitacao bis',
'    INNER JOIN buf_solicitacao bs ON bis.fk_id_solicitacao = bs.id_solicitacao',
'    INNER JOIN buf_descricao bd ON bis.fk_id_desc = bd.id_desc',
'    WHERE bis.id_item = :P376_ID_ITEM;',
'    ',
'    v_email_body := ''<html><body>'' || CHR(10) ||',
'        ''<h3>Cancelamento de Item de Buffet</h3>'' || CHR(10) ||',
'        ''<p><strong>Evento:</strong> '' || v_nom_evento || ''</p>'' || CHR(10) ||',
'        ''<p><strong>Item:</strong> '' || v_nom_descricao || ''</p>'' || CHR(10) ||',
unistr('        ''<p><strong>Data do Servi\00E7o:</strong> '' || TO_CHAR(v_dat_servico, ''DD/MM/YYYY'') || ''</p>'' || CHR(10) ||'),
'        ''<p><strong>Local:</strong> '' || v_local || ''</p>'' || CHR(10) ||',
'        ''<p><strong>Quantidade de Pessoas:</strong> '' || v_qtd_pessoas || ''</p>'' || CHR(10) ||',
unistr('        ''<p><strong>Valor Unit\00E1rio:</strong> R$ '' || TO_CHAR(v_valor_item, ''9999.99'') || ''</p>'' || CHR(10) ||'),
'        ''<p><strong>Valor Total:</strong> R$ '' || TO_CHAR(v_valor_item * v_qtd_pessoas, ''9999.99'') || ''</p>'' || CHR(10) ||',
unistr('        ''<p>O item foi <strong>cancelado</strong> e a quantidade foi devolvida ao estoque dispon\00EDvel.</p>'' || CHR(10) ||'),
'        ''</body></html>'';',
'    ',
'    APEX_MAIL.SEND(',
'        p_to        => v_email_destino,',
'        p_cc        => v_email_cc,',
'        p_from      => ''asqualog@senado.leg.br'',',
'        p_body      => NULL,',
'        p_subj      => v_subj,',
'        p_body_html => v_email_body',
'    );',
'',
'    APEX_MAIL.PUSH_QUEUE;',
'',
'    SELECT qtd_pessoas, fk_id_desc',
'    INTO v_qtd_pessoas, v_id_desc',
'    FROM buf_item_solicitacao',
'    WHERE id_item = :P376_ID_ITEM;',
'',
'    UPDATE buf_descricao',
'    SET qtd_disponivel = qtd_disponivel + v_qtd_pessoas',
'    WHERE id_desc = v_id_desc;',
'',
'    DELETE FROM buf_hor_item',
'    WHERE fk_id_item = :P376_ID_ITEM;',
'',
'    DELETE FROM buf_item_solicitacao',
'    WHERE id_item = :P376_ID_ITEM;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(757775550112945282)
,p_internal_uid=>541901711150719629
);
end;
