,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_taxa_conversao NUMBER;',
'    v_total_itens NUMBER;',
'    v_itens_contratados NUMBER;',
'BEGIN',
'    SELECT ',
'        COUNT(*) INTO v_total_itens',
'    FROM "BUF_ITEM_SOLICITACAO"',
'    WHERE TRUNC("DAT_SERVICO") >= TRUNC(SYSDATE) - 30;',
'    ',
'    SELECT ',
'        COUNT(*) INTO v_itens_contratados',
'    FROM "BUF_ITEM_SOLICITACAO"',
'    WHERE "STATUS" = ''Contratado''',
'      AND TRUNC("DAT_SERVICO") >= TRUNC(SYSDATE) - 30;',
'    ',
'    IF v_total_itens > 0 THEN',
'        v_taxa_conversao := ROUND((v_itens_contratados * 100.0) / v_total_itens, 2);',
'    ELSE',
'        v_taxa_conversao := 0;',
'    END IF;',
'    ',
'    htp.p(''<div style="padding: 20px; background-color: #f8f9fa; border-radius: 8px; border-left: 5px solid #00305C; box-shadow: 0 2px 8px rgba(0,0,0,0.08);">'');',
unistr('    htp.p(''  <h3 style="margin: 0 0 8px 0; color: #00305C; font-size: 16px; font-weight: 600;">Taxa de Convers\00E3o de Solicita\00E7\00F5es</h3>'');'),
unistr('    htp.p(''  <p style="margin: 0 0 12px 0; color: #666; font-size: 12px; line-height: 1.4;">Percentual de itens que foram contratados em rela\00E7\00E3o ao total solicitado (\00FAltimos 30 dias)</p>'');'),
'    htp.p(''  <p style="margin: 0; font-size: 36px; font-weight: bold; color: #00305C;">'' || v_taxa_conversao || ''%</p>'');',
'    htp.p(''  <div style="margin-top: 12px; padding-top: 12px; border-top: 1px solid #e0e0e0;">'');',
'    htp.p(''    <p style="margin: 0; color: #999; font-size: 11px;"><span style="color: #00305C; font-weight: 600;">'' || v_itens_contratados || ''</span> de <span style="color: #00305C; font-weight: 600;">'' || v_total_itens || ''</span> itens contratado'
||'s</p>'');',
'    htp.p(''  </div>'');',
'    htp.p(''</div>'');',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
