,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_receita_total NUMBER;',
'    v_receita_formatada VARCHAR2(100);',
'BEGIN',
'    SELECT ',
'        NVL(SUM("VALOR_ITEM"), 0) INTO v_receita_total',
'    FROM "BUF_ITEM_SOLICITACAO"',
'    WHERE "STATUS" = ''Contratado''',
'      AND TRUNC("DAT_SERVICO") >= TRUNC(SYSDATE) - 30',
'      AND TRUNC("DAT_SERVICO") < TRUNC(SYSDATE) + 1;',
'    ',
'    v_receita_formatada := TO_CHAR(v_receita_total, ''FM999,999,999.00'');',
'    ',
'    htp.p(''<div style="padding: 20px; background-color: #f8f9fa; border-radius: 8px; border-left: 5px solid #00305C; box-shadow: 0 2px 8px rgba(0,0,0,0.08);">'');',
'    htp.p(''  <h3 style="margin: 0 0 8px 0; color: #00305C; font-size: 16px; font-weight: 600;">Valor Total de Receita</h3>'');',
unistr('    htp.p(''  <p style="margin: 0 0 12px 0; color: #666; font-size: 12px; line-height: 1.4;">Soma total dos valores dos itens contratados (\00FAltimos 30 dias)</p>'');'),
'    htp.p(''  <p style="margin: 0; font-size: 36px; font-weight: bold; color: #00305C;">R$ '' || v_receita_formatada || ''</p>'');',
'    htp.p(''  <div style="margin-top: 12px; padding-top: 12px; border-top: 1px solid #e0e0e0;">'');',
unistr('    htp.p(''    <p style="margin: 0; color: #999; font-size: 11px;">Per\00EDodo: \00FAltimos 30 dias</p>'');'),
'    htp.p(''  </div>'');',
'    htp.p(''</div>'');',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
