,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_media_pessoas NUMBER;',
'    v_minimo_pessoas NUMBER;',
'    v_maximo_pessoas NUMBER;',
'BEGIN',
'    SELECT ',
'        ROUND(AVG("QTD_PESSOAS"), 2),',
'        MIN("QTD_PESSOAS"),',
'        MAX("QTD_PESSOAS")',
'    INTO v_media_pessoas, v_minimo_pessoas, v_maximo_pessoas',
'    FROM "BUF_ITEM_SOLICITACAO"',
'    WHERE "STATUS" = ''Contratado''',
'      AND TRUNC("DAT_SERVICO") >= TRUNC(SYSDATE) - 30;',
'    ',
'    htp.p(''<div style="padding: 20px; background-color: #f8f9fa; border-radius: 8px; border-left: 5px solid #00305C; box-shadow: 0 2px 8px rgba(0,0,0,0.08);">'');',
unistr('    htp.p(''  <h3 style="margin: 0 0 8px 0; color: #00305C; font-size: 16px; font-weight: 600;">M\00E9dia de Pessoas por Evento</h3>'');'),
unistr('    htp.p(''  <p style="margin: 0 0 12px 0; color: #666; font-size: 12px; line-height: 1.4;">Quantidade m\00E9dia de pessoas solicitadas nos eventos contratados (\00FAltimos 30 dias)</p>'');'),
'    htp.p(''  <p style="margin: 0; font-size: 36px; font-weight: bold; color: #00305C;">'' || NVL(v_media_pessoas, 0) || ''</p>'');',
'    htp.p(''  <div style="display: flex; gap: 16px; margin-top: 12px; padding-top: 12px; border-top: 1px solid #e0e0e0; flex-wrap: wrap;">'');',
'    htp.p(''    <div style="text-align: center;">'');',
'    htp.p(''      <p style="margin: 0; font-size: 14px; font-weight: 600; color: #00305C;">'' || NVL(v_minimo_pessoas, 0) || ''</p>'');',
unistr('    htp.p(''      <p style="margin: 4px 0 0 0; font-size: 11px; color: #999;">M\00EDnimo</p>'');'),
'    htp.p(''    </div>'');',
'    htp.p(''    <div style="text-align: center;">'');',
'    htp.p(''      <p style="margin: 0; font-size: 14px; font-weight: 600; color: #00305C;">'' || NVL(v_maximo_pessoas, 0) || ''</p>'');',
unistr('    htp.p(''      <p style="margin: 4px 0 0 0; font-size: 11px; color: #999;">M\00E1ximo</p>'');'),
'    htp.p(''    </div>'');',
'    htp.p(''  </div>'');',
'    htp.p(''</div>'');',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(744234928063090390)
,p_plug_name=>unistr('Tempo M\00E9dio de Anteced\00EAncia')
,p_parent_plug_id=>wwv_flow_imp.id(738921810748992504)
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--noBorder:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(711817305933954668)
,p_plug_display_sequence=>60
,p_plug_display_point=>'SUB_REGIONS'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_dias_medio NUMBER;',
'    v_minimo_dias NUMBER;',
'    v_maximo_dias NUMBER;',
'BEGIN',
'    SELECT ',
'        ROUND(AVG(TRUNC("DAT_SERVICO") - TRUNC("DAT_CRIACAO")), 1),',
'        MIN(TRUNC("DAT_SERVICO") - TRUNC("DAT_CRIACAO")),',
'        MAX(TRUNC("DAT_SERVICO") - TRUNC("DAT_CRIACAO"))',
'    INTO v_dias_medio, v_minimo_dias, v_maximo_dias',
'    FROM "BUF_ITEM_SOLICITACAO" bis',
'    INNER JOIN "BUF_SOLICITACAO" bs ON bis."FK_ID_SOLICITACAO" = bs."ID_SOLICITACAO"',
'    WHERE bis."STATUS" = ''Contratado''',
'      AND TRUNC(bis."DAT_SERVICO") >= TRUNC(SYSDATE) - 30;',
'    ',
'    htp.p(''<div style="padding: 20px; background-color: #f8f9fa; border-radius: 8px; border-left: 5px solid #00305C; box-shadow: 0 2px 8px rgba(0,0,0,0.08);">'');',
unistr('    htp.p(''  <h3 style="margin: 0 0 8px 0; color: #00305C; font-size: 16px; font-weight: 600;">Tempo M\00E9dio de Anteced\00EAncia</h3>'');'),
unistr('    htp.p(''  <p style="margin: 0 0 12px 0; color: #666; font-size: 12px; line-height: 1.4;">M\00E9dia de dias entre a cria\00E7\00E3o da solicita\00E7\00E3o e a data do servi\00E7o (\00FAltimos 30 dias)</p>'');'),
'    htp.p(''  <p style="margin: 0; font-size: 36px; font-weight: bold; color: #00305C;">'' || NVL(v_dias_medio, 0) || '' <span style="font-size: 18px; font-weight: 400;">dias</span></p>'');',
'    htp.p(''  <div style="display: flex; gap: 16px; margin-top: 12px; padding-top: 12px; border-top: 1px solid #e0e0e0; flex-wrap: wrap;">'');',
'    htp.p(''    <div style="text-align: center;">'');',
'    htp.p(''      <p style="margin: 0; font-size: 14px; font-weight: 600; color: #00923F;">'' || NVL(v_minimo_dias, 0) || ''</p>'');',
unistr('    htp.p(''      <p style="margin: 4px 0 0 0; font-size: 11px; color: #999;">M\00EDnimo</p>'');'),
'    htp.p(''    </div>'');',
'    htp.p(''    <div style="text-align: center;">'');',
'    htp.p(''      <p style="margin: 0; font-size: 14px; font-weight: 600; color: #00923F;">'' || NVL(v_maximo_dias, 0) || ''</p>'');',
unistr('    htp.p(''      <p style="margin: 4px 0 0 0; font-size: 11px; color: #999;">M\00E1ximo</p>'');'),
'    htp.p(''    </div>'');',
'    htp.p(''  </div>'');',
'    htp.p(''</div>'');',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(744235182785090392)
,p_plug_name=>'Quantidade de Eventos Agendados'
,p_parent_plug_id=>wwv_flow_imp.id(738921810748992504)
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--noBorder:t-Region--scrollBody'
