,p_plug_display_sequence=>70
,p_plug_new_grid_row=>false
,p_plug_display_point=>'SUB_REGIONS'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_total_eventos NUMBER;',
'    v_contratados NUMBER;',
'    v_negociacao NUMBER;',
'    v_cancelados NUMBER;',
'BEGIN',
'    SELECT ',
'        COUNT(DISTINCT "FK_ID_SOLICITACAO"),',
'        SUM(CASE WHEN "STATUS" = ''Contratado'' THEN 1 ELSE 0 END),',
unistr('        SUM(CASE WHEN "STATUS" = ''Em negocia\00E7\00E3o'' THEN 1 ELSE 0 END),'),
'        SUM(CASE WHEN "STATUS" = ''Cancelado'' THEN 1 ELSE 0 END)',
'    INTO v_total_eventos, v_contratados, v_negociacao, v_cancelados',
'    FROM "BUF_ITEM_SOLICITACAO"',
'    WHERE TRUNC("DAT_SERVICO") >= TRUNC(SYSDATE) - 30',
'      AND TRUNC("DAT_SERVICO") < TRUNC(SYSDATE) + 1;',
'    ',
'    htp.p(''<div style="padding: 20px; background-color: #f8f9fa; border-radius: 8px; border-left: 5px solid #00305C; box-shadow: 0 2px 8px rgba(0,0,0,0.08);">'');',
'    htp.p(''  <h3 style="margin: 0 0 8px 0; color: #00305C; font-size: 16px; font-weight: 600;">Quantidade de Eventos Agendados</h3>'');',
unistr('    htp.p(''  <p style="margin: 0 0 12px 0; color: #666; font-size: 12px; line-height: 1.4;">Total de eventos \00FAnicos com itens solicitados (\00FAltimos 30 dias)</p>'');'),
'    htp.p(''  <p style="margin: 0; font-size: 36px; font-weight: bold; color: #00305C; text-shadow: 1px 1px 1px rgba(0,0,0,0.1);">'' || v_total_eventos || ''</p>'');',
'    htp.p(''  <div style="display: flex; gap: 16px; margin-top: 12px; padding-top: 12px; border-top: 1px solid #e0e0e0; flex-wrap: wrap;">'');',
'    htp.p(''    <div style="text-align: center;">'');',
'    htp.p(''      <p style="margin: 0; font-size: 14px; font-weight: 600; color: #00923F;">'' || NVL(v_contratados, 0) || ''</p>'');',
'    htp.p(''      <p style="margin: 4px 0 0 0; font-size: 11px; color: #999;">Contratados</p>'');',
'    htp.p(''    </div>'');',
'    htp.p(''    <div style="text-align: center;">'');',
'    htp.p(''      <p style="margin: 0; font-size: 14px; font-weight: 600; color: #F39C12;">'' || NVL(v_negociacao, 0) || ''</p>'');',
unistr('    htp.p(''      <p style="margin: 4px 0 0 0; font-size: 11px; color: #999;">Em Negocia\00E7\00E3o</p>'');'),
'    htp.p(''    </div>'');',
'    htp.p(''    <div style="text-align: center;">'');',
'    htp.p(''      <p style="margin: 0; font-size: 14px; font-weight: 600; color: #C0392B;">'' || NVL(v_cancelados, 0) || ''</p>'');',
'    htp.p(''      <p style="margin: 4px 0 0 0; font-size: 11px; color: #999;">Cancelados</p>'');',
'    htp.p(''    </div>'');',
'    htp.p(''  </div>'');',
'    htp.p(''</div>'');',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
