'BEGIN',
'    SELECT ',
'        COUNT(*) INTO v_total_itens',
'    FROM "BUF_ITEM_SOLICITACAO"',
'    WHERE TRUNC("DAT_SERVICO") >= TRUNC(SYSDATE) - 90;',
'    ',
'    SELECT ',
'        COUNT(*) INTO v_itens_cancelados',
'    FROM "BUF_ITEM_SOLICITACAO"',
'    WHERE "STATUS" = ''Cancelado''',
