unistr('    htp.p(''  <p style="margin: 0 0 12px 0; color: #666; font-size: 12px; line-height: 1.4;">Percentual de itens cancelados em rela\00E7\00E3o ao total de solicita\00E7\00F5es (\00FAltimos 90 dias)</p>'');'),
'    htp.p(''  <p style="margin: 0; font-size: 36px; font-weight: bold; color: #00305C;">'' || v_taxa_cancelamento || ''%</p>'');',
'    htp.p(''  <div style="margin-top: 12px; padding-top: 12px; border-top: 1px solid #e0e0e0;">'');',
'    htp.p(''    <p style="margin: 0; color: #999; font-size: 11px;"><span style="color: #00305C; font-weight: 600;">'' || v_itens_cancelados || ''</span> de <span style="color: #00305C; font-weight: 600;">'' || v_total_itens || ''</span> itens cancelados<'
||'/p>'');',
'    htp.p(''  </div>'');',
'    htp.p(''</div>'');',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
