,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_valor_item    NUMBER;',
'    v_qtd           NUMBER;',
'    v_valor         NUMBER;',
'BEGIN',
'    SELECT d.valor ',
'    INTO v_valor_item',
'    FROM buf_descricao d',
'    JOIN buf_item_solicitacao i ON i.fk_id_desc = d.id_desc',
'    WHERE i.id_item = :P570_ID_ITEM;',
'',
'    v_qtd := :P570_QTD;',
'',
'    v_valor := v_valor_item * v_qtd;',
'',
'    :P570_VALOR := ''R$ '' || TO_CHAR(v_valor, ''FM999G999G999D00'', ''NLS_NUMERIC_CHARACTERS = '''',.'''''');',
'END;'))
,p_attribute_02=>'P570_ID_ITEM,P570_QTD'
,p_attribute_03=>'P570_VALOR'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
