wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(757736803735795960)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Confirmar o item'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_qtd_antiga        NUMBER;',
'    v_qtd_nova          NUMBER := :P570_QTD;',
'',
'    v_diferenca         NUMBER;',
'    v_fk_id_desc        NUMBER;',
'    ',
'    v_qtd_disponivel    NUMBER;',
'    v_qtd_maxima        NUMBER;',
'',
'    v_valor_unitario    NUMBER;',
'    v_valor_item        NUMBER;',
'BEGIN',
'    FOR i IN 1 .. APEX_APPLICATION.G_F01.COUNT LOOP',
'        UPDATE buf_hor_item',
'        SET qtd_hor = TO_NUMBER(APEX_APPLICATION.G_F01(i))',
'        WHERE id_hor_item = APEX_APPLICATION.G_F02(i);',
'    END LOOP;',
'',
'    SELECT NVL(SUM(qtd_hor), 0)',
'    INTO v_qtd_nova',
'    FROM buf_hor_item',
'    WHERE fk_id_item = :P570_ID_ITEM;',
'',
'    SELECT qtd_pessoas, fk_id_desc',
'    INTO v_qtd_antiga, v_fk_id_desc',
'    FROM buf_item_solicitacao',
'    WHERE id_item = :P570_ID_ITEM;',
'',
'    SELECT qtd_disponivel, valor',
'    INTO v_qtd_disponivel, v_valor_unitario',
'    FROM buf_descricao',
'    WHERE id_desc = v_fk_id_desc;',
'',
'    v_qtd_maxima := v_qtd_antiga + v_qtd_disponivel;',
'',
'    IF v_qtd_nova > v_qtd_maxima THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
unistr('            ''Quantidade indispon\00EDvel. '' ||'),
'            ''Quantidade atual: '' || v_qtd_antiga || '' | '' ||',
unistr('            ''Dispon\00EDvel em estoque: '' || v_qtd_disponivel || '' | '' ||'),
unistr('            ''M\00E1ximo permitido: '' || v_qtd_maxima || '' | '' ||'),
'            ''Solicitado: '' || v_qtd_nova',
'        );',
'    END IF;',
'',
'    v_diferenca := v_qtd_nova - v_qtd_antiga;',
'',
'    v_valor_item := v_qtd_nova * v_valor_unitario;',
'',
'    UPDATE buf_item_solicitacao',
'    SET status = ''Contratado'',',
'        qtd_pessoas = v_qtd_nova,',
'        valor_item = v_valor_item',
'    WHERE id_item = :P570_ID_ITEM;',
'',
'    UPDATE buf_descricao',
'    SET qtd_disponivel = qtd_disponivel - v_diferenca',
'    WHERE id_desc = v_fk_id_desc;',
'',
'    COMMIT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(757729781442795916)
,p_internal_uid=>541859082329570303
);
end;
