wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(754711326691073790)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('Colocar a Autoriza\00E7\00E3o')
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_blob              BLOB;',
'    v_filename          VARCHAR2(200);',
'    v_mimetype          VARCHAR2(200);',
'',
'    v_evento            VARCHAR2(4000);',
'    v_setor_solicitante VARCHAR2(200);',
'    v_email_destino     VARCHAR2(200);',
'    v_email_remetente   VARCHAR2(200) := ''DGER@senado.leg.br'';',
'    v_email_cc          VARCHAR2(4000);',
unistr('    v_assunto           VARCHAR2(200) := ''Solicita\00E7\00E3o de Buffet Autorizada \2013 Provid\00EAncias Operacionais'';'),
'    v_mensagem          CLOB;',
'    l_mail_id           NUMBER;',
'',
'    v_qtd_horarios      NUMBER;',
'    v_primeiro          BOOLEAN;',
'    v_email_solicitante VARCHAR2(4000);',
'    v_emails_responsaveis VARCHAR2(4000);',
'',
'    v_nome_dger  VARCHAR2(200);',
'    v_setor_dger        VARCHAR2(200);',
'BEGIN',
unistr('    -- Busca do arquivo tempor\00E1rio'),
'    SELECT blob_content, mime_type, filename',
'      INTO v_blob, v_mimetype, v_filename',
'      FROM apex_application_temp_files',
'     WHERE name = :P571_AUTORIZACAO;',
'',
'    -- Devolve quantidade ao estoque para itens Cancelados',
'    UPDATE buf_descricao bd',
'       SET qtd_disponivel = qtd_disponivel + (',
'           SELECT SUM(bis.qtd_pessoas)',
'             FROM buf_item_solicitacao bis',
'            WHERE bis.fk_id_desc = bd.id_desc',
'              AND bis.fk_id_solicitacao = :P571_ID_SOLICITACAO',
'              AND bis.status = ''Cancelado''',
'       )',
'     WHERE EXISTS (',
'           SELECT 1',
'             FROM buf_item_solicitacao bis',
'            WHERE bis.fk_id_desc = bd.id_desc',
'              AND bis.fk_id_solicitacao = :P571_ID_SOLICITACAO',
'              AND bis.status = ''Cancelado''',
'              AND NVL(bis.ind_negado_senac, ''N'') <> ''S''',
'       );',
'',
unistr('    -- Atualiza a solicita\00E7\00E3o com o BLOB e marca como analisado'),
'    UPDATE buf_solicitacao',
'       SET aprovacao_dger = v_blob,',
'           mimetype       = v_mimetype,',
'           filename       = v_filename,',
'           ind_analisado  = ''S''',
'     WHERE id_solicitacao = :P571_ID_SOLICITACAO;',
'',
'    -- Nome do solicitante e e-mail remetente',
'    SELECT vs.nom_pessoa, u.txt_email_sf',
'      INTO v_nome_dger, v_email_remetente',
'      FROM dda.vinculo_sf vs',
'      JOIN dda.usuario_rede u',
'        ON vs.num_cpf = u.num_cpf_pessoa',
'     WHERE LOWER(u.txt_login_ad) = LOWER(:APP_USER);',
'    ',
'    SELECT o.sgl_orgao || '' - '' || o.nom_orgao INTO v_setor_dger',
'    FROM dda.orgao o',
'    JOIN dda.vinculo_sf vs ON o.sgl_orgao = vs.sgl_orgao_exercicio',
'    WHERE vs.ind_vinculo_ativo = ''S''',
'        AND vs.num_cpf = (',
'            SELECT u.num_cpf_pessoa',
'            FROM dda.usuario_rede u',
'            WHERE LOWER(u.txt_login_ad) = LOWER(:APP_USER)',
'        );',
'',
unistr('    -- Nome do evento e e-mails respons\00E1veis (solicitante)'),
'    SELECT nom_evento, email_responsavel, sgl_orgao',
'      INTO v_evento, v_emails_responsaveis, v_setor_solicitante',
'      FROM buf_solicitacao',
'     WHERE id_solicitacao = :P571_ID_SOLICITACAO;',
'',
'    -- Primeiro e-mail de email_responsavel como destino',
'    v_email_destino :=',
'        REGEXP_SUBSTR(v_emails_responsaveis, ''[^,]+'', 1, 1);',
'',
unistr('    -- Vari\00E1vel usada no texto do e-mail (permanece igual)'),
'    v_email_solicitante := v_emails_responsaveis;',
'',
unistr('    -- Monta v_email_cc com lista fixa + respons\00E1veis'),
'    v_email_cc :=',
'          ''sequalog-equipe@senado.gov.br,'' ||',
'          ''guilherme.schettini@senado.leg.br,''',
'        || ''LAFUENTE@senado.leg.br,''',
'        || ''asqualog@senado.leg.br,''',
'        || COALESCE(v_email_solicitante, '''');',
'    v_email_cc := REGEXP_REPLACE(v_email_cc, '',$'', '''');',
'',
'    v_mensagem :=',
'           ''<html>',
'                <body style="font-family: Arial, Helvetica, sans-serif; font-size:14px; color:#333;">',
'                    <p>Prezados(as),</p>',
'',
'                    <p>',
unistr('                        Informamos que a solicita\00E7\00E3o de servi\00E7o de buffet abaixo identificada, a ser realizada por meio do acionamento do CT n\00BA 2024/0115, foi <b>AUTORIZADA</b> pela Diretoria-Geral, nos termos do documento de autoriza\00E7\00E3o anexo.'),
'                    </p>',
'',
'                    <p>',
unistr('                        A autoriza\00E7\00E3o poder\00E1 corresponder integralmente \00E0 solicita\00E7\00E3o original ou contemplar ajustes definidos pela Diretoria-Geral, devendo prevalecer as condi\00E7\00F5es constantes da autoriza\00E7\00E3o anexa.'),
'                    </p>',
'',
'                    <p>',
'                        <b>Evento:</b> '' || v_evento || ''<br>',
'                        <b>Unidade Solicitante:</b> '' || v_setor_solicitante || ''<br>',
unistr('                        <b>E-mail(s) do(s) Respons\00E1vel(is) pelo Evento:</b> '' || NVL(v_email_solicitante, ''-'') || '''),
'                    </p>'';',
'',
'    v_mensagem := v_mensagem ||',
unistr('        ''<p><b>Servi\00E7os autorizados (Contratados)</b></p>'),
'',
'         <table style="',
'             border-collapse:collapse;',
'             width:100%;',
'             max-width:800px;',
'             margin-top:10px;',
'             border:1px solid #ddd;',
'         ">',
'             <tr style="background-color:#d4edda;">',
unistr('                 <th style="padding:8px;border:1px solid #ddd;">Servi\00E7o</th>'),
'                 <th style="padding:8px;border:1px solid #ddd;">Data</th>',
unistr('                 <th style="padding:8px;border:1px solid #ddd;">N\00BA de Pessoas</th>'),
unistr('                 <th style="padding:8px;border:1px solid #ddd;">Hor\00E1rio</th>'),
unistr('                 <th style="padding:8px;border:1px solid #ddd;">Quantidade por Hor\00E1rio</th>'),
'                 <th style="padding:8px;border:1px solid #ddd;">Local</th>',
'                 <th style="padding:8px;border:1px solid #ddd;">Valor</th>',
'             </tr>'';',
'',
'    FOR item IN (',
'        SELECT',
'            i.id_item,',
'            d.descricao,',
'            i.dat_servico,',
'            i.qtd_pessoas       AS qtd_total,',
'            i.local,',
'            i.valor_item',
'        FROM buf_item_solicitacao i',
'        JOIN buf_descricao d',
'          ON i.fk_id_desc = d.id_desc',
'       WHERE i.fk_id_solicitacao = :P571_ID_SOLICITACAO',
'         AND i.status = ''Contratado''',
'         AND NVL(i.ind_negado_senac, ''N'') <> ''S''',
'       ORDER BY i.dat_servico, d.descricao',
'    )',
'    LOOP',
unistr('        -- conta hor\00E1rios para o item (para o rowspan)'),
'        SELECT COUNT(*)',
'          INTO v_qtd_horarios',
'          FROM buf_hor_item h',
'         WHERE h.fk_id_item = item.id_item;',
'',
'        IF v_qtd_horarios = 0 THEN',
'            v_qtd_horarios := 1;',
'        END IF;',
'',
'        v_primeiro := TRUE;',
'',
'        FOR h IN (',
'            SELECT hor, qtd_hor',
'              FROM buf_hor_item',
'             WHERE fk_id_item = item.id_item',
'             ORDER BY hor_minuto',
'        )',
'        LOOP',
'            v_mensagem := v_mensagem || ''<tr>'';',
'',
'            IF v_primeiro THEN',
'                -- colunas fixas com rowspan',
'                v_mensagem := v_mensagem ||',
'                    ''<td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;">'' ||',
'                        item.descricao || ''</td>',
'                     <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:center;">'' ||',
'                        TO_CHAR(item.dat_servico, ''DD/MM/YYYY'') || ''</td>',
'                     <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:center;">'' ||',
'                        NVL(TO_CHAR(item.qtd_total), ''-'') || ''</td>'';',
'            END IF;',
'',
unistr('            -- colunas vari\00E1veis por hor\00E1rio'),
'            v_mensagem := v_mensagem ||',
'                 ''<td style="padding:8px;border:1px solid #ddd;text-align:center;">'' ||',
'                     NVL(h.hor, ''-'') || ''</td>',
'                  <td style="padding:8px;border:1px solid #ddd;text-align:center;">'' ||',
'                     NVL(TO_CHAR(h.qtd_hor), ''-'') || ''</td>'';',
'',
'            IF v_primeiro THEN',
'                v_mensagem := v_mensagem ||',
'                    ''<td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;">'' ||',
'                        NVL(item.local, ''-'') || ''</td>',
'                     <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:right;">R$ '' ||',
'                        NVL(TO_CHAR(item.valor_item, ''FM999G999G990D00''), ''-'') || ''</td>'';',
'            END IF;',
'',
'            v_mensagem := v_mensagem || ''</tr>'';',
'            v_primeiro := FALSE;',
'        END LOOP;',
'',
unistr('        -- caso n\00E3o tenha nenhum registro em BUF_HOR_ITEM'),
'        IF v_primeiro THEN',
'            v_mensagem := v_mensagem ||',
'                ''<tr>',
'                    <td style="padding:8px;border:1px solid #ddd;">''||item.descricao||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">''||TO_CHAR(item.dat_servico,''DD/MM/YYYY'')||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">''||NVL(TO_CHAR(item.qtd_total), ''-'')||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">-</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">-</td>',
'                    <td style="padding:8px;border:1px solid #ddd;">''||NVL(item.local,''-'')||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:right;">R$ ''||',
'                        NVL(TO_CHAR(item.valor_item,''FM999G999G990D00''),''-'')||''</td>',
'                </tr>'';',
'        END IF;',
'    END LOOP;',
'',
'    v_mensagem := v_mensagem || ''</table>'';',
'',
'    v_mensagem := v_mensagem ||',
'        ''<br><br>',
unistr('         <p><b>Servi\00E7os cancelados</b></p>'),
'',
'         <table style="',
'             border-collapse:collapse;',
'             width:100%;',
'             max-width:800px;',
'             margin-top:10px;',
'             border:1px solid #ddd;',
'         ">',
'             <tr style="background-color:#f8d7da;">',
unistr('                 <th style="padding:8px;border:1px solid #ddd;">Servi\00E7o</th>'),
'                 <th style="padding:8px;border:1px solid #ddd;">Data</th>',
unistr('                 <th style="padding:8px;border:1px solid #ddd;">N\00BA de Pessoas</th>'),
unistr('                 <th style="padding:8px;border:1px solid #ddd;">Hor\00E1rio</th>'),
unistr('                 <th style="padding:8px;border:1px solid #ddd;">Quantidade por Hor\00E1rio</th>'),
'                 <th style="padding:8px;border:1px solid #ddd;">Local</th>',
'                 <th style="padding:8px;border:1px solid #ddd;">Valor</th>',
'             </tr>'';',
'',
'    FOR item_c IN (',
'        SELECT',
'            i.id_item,',
'            d.descricao,',
'            i.dat_servico,',
'            i.qtd_pessoas       AS qtd_total,',
'            i.local,',
'            i.valor_item',
'        FROM buf_item_solicitacao i',
'        JOIN buf_descricao d',
'          ON i.fk_id_desc = d.id_desc',
'       WHERE i.fk_id_solicitacao = :P571_ID_SOLICITACAO',
'         AND i.status = ''Cancelado''',
'         AND NVL(i.ind_negado_senac, ''N'') <> ''S''',
'       ORDER BY i.dat_servico, d.descricao',
'    )',
'    LOOP',
'        SELECT COUNT(*)',
'          INTO v_qtd_horarios',
'          FROM buf_hor_item h',
'         WHERE h.fk_id_item = item_c.id_item;',
'',
'        IF v_qtd_horarios = 0 THEN',
'            v_qtd_horarios := 1;',
'        END IF;',
'',
'        v_primeiro := TRUE;',
'',
'        FOR h2 IN (',
'            SELECT hor, qtd_hor',
'              FROM buf_hor_item',
'             WHERE fk_id_item = item_c.id_item',
'             ORDER BY hor_minuto',
'        )',
'        LOOP',
'            v_mensagem := v_mensagem || ''<tr>'';',
'',
'            IF v_primeiro THEN',
'                v_mensagem := v_mensagem ||',
'                    ''<td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;">'' ||',
'                        item_c.descricao || ''</td>',
'                     <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:center;">'' ||',
'                        TO_CHAR(item_c.dat_servico, ''DD/MM/YYYY'') || ''</td>',
'                     <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:center;">'' ||',
'                        NVL(TO_CHAR(item_c.qtd_total), ''-'') || ''</td>'';',
'            END IF;',
'',
'            v_mensagem := v_mensagem ||',
'                 ''<td style="padding:8px;border:1px solid #ddd;text-align:center;">'' ||',
'                     NVL(h2.hor, ''-'') || ''</td>',
'                  <td style="padding:8px;border:1px solid #ddd;text-align:center;">'' ||',
'                     NVL(TO_CHAR(h2.qtd_hor), ''-'') || ''</td>'';',
'',
'            IF v_primeiro THEN',
'                v_mensagem := v_mensagem ||',
'                    ''<td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;">'' ||',
'                        NVL(item_c.local, ''-'') || ''</td>',
'                     <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:right;">R$ '' ||',
'                        NVL(TO_CHAR(item_c.valor_item, ''FM999G999G990D00''), ''-'') || ''</td>'';',
'            END IF;',
'',
'            v_mensagem := v_mensagem || ''</tr>'';',
'            v_primeiro := FALSE;',
'        END LOOP;',
'',
'        IF v_primeiro THEN',
'            v_mensagem := v_mensagem ||',
'                ''<tr>',
'                    <td style="padding:8px;border:1px solid #ddd;">''||item_c.descricao||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">''||TO_CHAR(item_c.dat_servico,''DD/MM/YYYY'')||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">''||NVL(TO_CHAR(item_c.qtd_total), ''-'')||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">-</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">-</td>',
'                    <td style="padding:8px;border:1px solid #ddd;">''||NVL(item_c.local,''-'')||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:right;">R$ ''||',
'                        NVL(TO_CHAR(item_c.valor_item,''FM999G999G990D00''),''-'')||''</td>',
'                </tr>'';',
'        END IF;',
'    END LOOP;',
'',
'    v_mensagem := v_mensagem ||',
'           ''</table>',
'            <br><br>',
'            <p>',
unistr('                Encaminha-se ao Servi\00E7o Nacional de Aprendizagem Comercial \2013 SENAC para ado\00E7\00E3o das provid\00EAncias operacionais necess\00E1rias \00E0 execu\00E7\00E3o do servi\00E7o.'),
'            </p>',
'',
'            <p>',
unistr('                Tratativas relativas \00E0 defini\00E7\00E3o de card\00E1pio, ajustes operacionais e demais alinhamentos pertinentes podem ser realizadas com os e-mails em c\00F3pia dos respons\00E1veis pelo evento.'),
'            </p>',
'',
'            <p>',
'                Atenciosamente,<br>',
'                '' || v_nome_dger || ''<br>',
'                '' || v_setor_dger || ''<br> ',
'                <b>Sistema de Buffet</b><br>',
'                Senado Federal',
'            </p>',
'',
'            <p style="font-size:12px;color:#666;margin-top:20px;">',
unistr('                Este \00E9 um e-mail autom\00E1tico do Sistema de Buffet.<br>'),
unistr('                Em caso de d\00FAvidas, contatar: <a href="mailto:asqualog@senado.leg.br">asqualog@senado.leg.br</a>'),
'            </p>',
'',
'        </body>',
'    </html>'';',
'',
'    l_mail_id := APEX_MAIL.SEND(',
'        p_to        => v_email_destino,',
'        p_cc        => v_email_cc,',
'        p_from      => v_email_remetente,',
'        p_subj      => v_assunto,',
'        p_body      => NULL,',
'        p_body_html => v_mensagem',
'    );',
'',
'    apex_mail.add_attachment(',
'        p_mail_id    => l_mail_id,',
'        p_attachment => v_blob,',
'        p_filename   => v_filename,',
'        p_mime_type  => v_mimetype',
'    );',
'',
'    APEX_MAIL.PUSH_QUEUE;',
'',
'    COMMIT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>538833605284848133
);
end;
