,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    se.id_solicitacao_ext                                   AS "ID",',
'    ie.dat_evento                                           AS "Data do Evento",',
'    se.nom_evento                                           AS "Evento",',
unistr('    d.descricao                                             AS "Tipo de Servi\00E7o",'),
'    TO_CHAR(',
'        TO_DATE(ie.hor_inicio, ''HH24:MI''),',
'        ''HH24"h"MI''',
'    )',
unistr('    || '' \00E0s '' ||'),
'    TO_CHAR(',
'        TO_DATE(ie.hor_inicio, ''HH24:MI'')',
'        + (d.tempo_minutos / 1440),',
'        ''HH24"h"MI''',
unistr('    )                                                       AS "Dura\00E7\00E3o do Evento",'),
unistr('    ''N\00E3o''                                                   AS "Contrato",'),
'    ie.local                                                AS "Local"',
'FROM buf_solicitacao_ext se',
'JOIN buf_item_solicitacao_ext ie',
'    ON ie.fk_id_solicitacao_ext = se.id_solicitacao_ext',
'JOIN buf_descricao d',
'    ON d.id_desc = ie.fk_id_desc',
'WHERE se.ind_pendente = ''N''',
'ORDER BY',
'    ie.dat_evento,',
'    ie.hor_minuto'))
