wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(971183774490382585)
,p_event_id=>wwv_flow_imp.id(971183655372382584)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('// ------------------- IN\00CDCIO DO C\00D3DIGO DE ATUALIZA\00C7\00C3O AP\00D3S DOWNLOAD -------------------'),
'',
'let pdfDownloadIniciado = false;',
'',
unistr('// Listener de clique no bot\00E3o original do di\00E1logo de download'),
'document.addEventListener(''click'', function(event) {',
'',
'    const downloadButton = event.target.closest(',
'        ''.a-IRR-dialog--download .ui-dialog-buttonpane .ui-button--hot''',
'    );',
'',
'    if (downloadButton) {',
'        const formatoSelecionado =',
'            document.getElementById(''externo_download_format'')?.value;',
'',
'        if (formatoSelecionado === ''PDF'') {',
'            alert(',
unistr('                ''O seu relat\00F3rio PDF ser\00E1 preparado. '' +'),
unistr('                ''A p\00E1gina ser\00E1 atualizada automaticamente ap\00F3s o download.'''),
'            );',
'',
'            pdfDownloadIniciado = true;',
'        } else {',
'            setTimeout(function () {',
'                apex.region("externo").refresh();',
'            }, 500);',
'        }',
'    }',
'});',
'',
'// Listener para quando a janela volta ao foco',
'window.addEventListener(''focus'', function() {',
'    if (pdfDownloadIniciado) {',
'        apex.region("externo").refresh();',
'',
'        pdfDownloadIniciado = false;',
'    }',
'});',
'',
'const actionsButton = $(''#externo_actions_button'');',
'const menuSelector =',
'    ''#'' + actionsButton.attr(''data-menu'');',
'if (actionsButton.length === 0) {',
'',
'    console.error(',
unistr('        "Bot\00E3o ''A\00E7\00F5es'' n\00E3o encontrado."'),
'    );',
'} else {',
unistr('    // Abre o menu "A\00E7\00F5es"'),
'    if (!actionsButton.hasClass(''is-active'')) {',
'        actionsButton.click();',
'    }',
'    // Espera renderizar e clica em "Fazer Download"',
'    setTimeout(function () {',
'        const menuElement = $(menuSelector);',
'        const downloadButtonInMenu =',
'            menuElement.find(',
'                ''button:contains("Fazer Download")''',
'            );',
'',
'        if (downloadButtonInMenu.length > 0) {',
'            const nativeButton =',
'                downloadButtonInMenu[0];',
'',
'            nativeButton.focus();',
'            nativeButton.dispatchEvent(',
'                new MouseEvent(''mousedown'', {',
'                    bubbles: true,',
'                    cancelable: true',
'                })',
'            );',
'            nativeButton.dispatchEvent(',
'                new MouseEvent(''mouseup'', {',
'                    bubbles: true,',
'                    cancelable: true',
'                })',
'            );',
'            nativeButton.dispatchEvent(',
'                new MouseEvent(''click'', {',
'                    bubbles: true,',
'                    cancelable: true',
'                })',
'            );',
'        } else {',
'            console.error(',
unistr('                "Bot\00E3o ''Fazer Download'' n\00E3o encontrado."'),
'            );',
'        }',
'    }, 200);',
'}'))
);
end;
