prompt --application/pages/page_00602
begin
wwv_flow_imp_page.create_page(
 p_id=>602
,p_name=>'Itens do Evento'
,p_alias=>'ITENS-DO-EVENTO'
,p_step_title=>'Itens do Evento'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function atualizarTextoAjuda() {',
'    var tipo = $v(''P602_ITEM'');',
'',
'    apex.server.process(',
'        ''GET_TEXTO_AJUDA'',',
'        {',
'            pageItems: ''#P602_ITEM''',
'        },',
'        {',
'            dataType: ''json'',',
'            success: function (data) {',
'                if (data && data.responseText) {',
