,p_plug_new_grid_column=>false
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ie.id_item_solicitacao_ext AS "ID",',
'    ie.fk_id_solicitacao_ext AS "FK",',
'    d.descricao AS "Item do Buffet",',
'    ie.dat_evento AS "Data do Evento",',
'    ie.hor_inicio AS "Hora",',
'    ie.hor_minuto AS "Minuto",',
'    LPAD(TRUNC((ie.hor_minuto + d.tempo_minutos) / 60), 2, ''0'') || '':'' || ',
'        LPAD(MOD(ie.hor_minuto + d.tempo_minutos, 60), 2, ''0'') AS "Hora de Fim",',
'    ie.local AS "Local"',
'FROM buf_item_solicitacao_ext ie',
'JOIN buf_descricao d ON ie.fk_id_desc = d.id_desc',
'WHERE fk_id_solicitacao_ext = :P602_ID_SOLICITACAO',
'ORDER BY ie.dat_evento, ie.hor_inicio, ie.hor_minuto'))
