wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(773881706641571966)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_TEXTO_AJUDA'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_html CLOB := '''';',
'BEGIN',
unistr('    -- Busca descri\00E7\00E3o (sem quebrar se n\00E3o existir)'),
'    BEGIN',
'        SELECT ',
unistr('            ''Tempo de servi\00E7o: '' || NVL(d.tempo_servico, ''-'') || ''<br>'' ||'),
unistr('            ''Valor unit\00E1rio: '' || NVL(TO_CHAR(d.valor), ''-'') || ''<br>'' ||'),
unistr('            ''Anteced\00EAncia: '' || NVL(TO_CHAR(d.antecedencia), ''-'') || '' dias \00FAteis<br>'' || '),
unistr('            ''Quantidade dispon\00EDvel: '' || NVL(TO_CHAR(d.qtd_disponivel), ''-'') || ''<br><br>'''),
'        INTO v_html',
'        FROM buf_descricao d',
'        WHERE d.id_desc = TO_NUMBER(:P602_ITEM);',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
unistr('            v_html := ''Nenhuma descri\00E7\00E3o encontrada.'';'),
'    END;',
'',
unistr('    -- Especifica\00E7\00F5es'),
'    FOR esp IN (',
'        SELECT detalhe',
'        FROM buf_especificacao',
'        WHERE fk_id_desc = TO_NUMBER(:P602_ITEM)',
'    ) LOOP',
'        v_html := v_html || esp.detalhe || ''<br>'';',
'    END LOOP;',
'',
'    -- Retornar como JSON',
'    apex_json.open_object;',
'    apex_json.write(''responseText'', v_html);',
'    apex_json.close_object;',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        apex_json.open_object;',
'        apex_json.write(''responseText'', ''Erro: '' || SQLERRM);',
'        apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>558003985235346309
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(773978461338225140)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Salvar Primeira Parte'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_data_evento   DATE;',
'    v_hor_inicio    VARCHAR2(10);',
'    v_hor_minuto    NUMBER;',
'',
'BEGIN',
'    v_data_evento := TRUNC(TO_DATE(:P602_DAT_SERVICO, ''DD/MM/YYYY''));',
'    v_hor_inicio := :P602_HOR_INICIO;',
'    v_hor_minuto := :P602_HOR_MINUTO;',
'',
'    INSERT INTO buf_item_solicitacao_ext (',
'        fk_id_solicitacao_ext,',
'        fk_id_desc,',
'        dat_evento,',
'        hor_inicio,',
'        hor_minuto,',
'        local',
'    ) VALUES (',
'        :P602_ID_SOLICITACAO,',
'        :P602_ITEM,',
'        v_data_evento,',
'        v_hor_inicio,',
'        v_hor_minuto,',
'        :P602_LOCAL',
'    )',
'    RETURNING id_item_solicitacao_ext INTO :P602_ID_ITEM;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(773976304920225138)
,p_internal_uid=>558100739931999483
);
