wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1293509325672598686)
,p_plug_name=>unistr('Solicita\00E7\00E3o Atual')
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(711817305933954668)
,p_plug_display_sequence=>20
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_total_itens NUMBER;',
'    v_primeiro BOOLEAN;',
'',
'    v_url_asqualog  CLOB;',
'    v_url_deletar   CLOB;',
'',
'    v_limite        CONSTANT NUMBER := 15;',
'    v_pagina        NUMBER := NVL(:P300_PAGINA,1);',
'    v_total_registros   NUMBER;',
'    v_total_paginas     NUMBER;',
'',
'    v_inicio        NUMBER;',
'    v_fim           NUMBER;',
'    v_existe        NUMBER;',
'BEGIN',
'',
'    SELECT COUNT(DISTINCT se.id_solicitacao_ext) INTO v_existe',
'    FROM buf_solicitacao_ext se',
'    JOIN buf_item_solicitacao_ext ie',
'        ON ie.fk_id_solicitacao_ext = se.id_solicitacao_ext',
'    WHERE se.id_solicitacao_ext = :P603_ID_SOLICITACAO',
'        AND se.ind_pendente = ''S'';',
'',
'    IF v_existe = 0 THEN',
'        htp.p(''',
'            <div class="t-Alert t-Alert--warning t-Alert--horizontal t-Alert--defaultIcons">',
'                <div class="t-Alert-wrap">',
'                    <div class="t-Alert-icon">',
'                        <span class="t-Icon fa fa-info-circle"></span>',
'                    </div>',
'                    <div class="t-Alert-content">',
'                        <div class="t-Alert-header">',
'                            <h2 class="t-Alert-title">',
unistr('                                N\00E3o h\00E1 eventos externos cadastrados.'),
'                            </h2>',
'                        </div>',
'                    </div>',
'                </div>',
'            </div>',
'        '');',
'    ELSE',
'        v_inicio := (v_pagina - 1) * v_limite + 1;',
'        v_fim    := v_pagina * v_limite;',
'',
'        SELECT COUNT(DISTINCT se.id_solicitacao_ext) INTO v_total_registros',
'        FROM buf_solicitacao_ext se',
'        JOIN buf_item_solicitacao_ext ie',
'            ON ie.fk_id_solicitacao_ext = se.id_solicitacao_ext',
'        WHERE se.id_solicitacao_ext = :P603_ID_SOLICITACAO',
'            AND se.ind_pendente = ''S'';',
'',
'        v_total_paginas := CEIL(v_total_registros / v_limite);',
'',
unistr('        -- Verifica se h\00E1 itens para a p\00E1gina atual'),
'        SELECT COUNT(*)',
'        INTO v_total_itens',
'        FROM (',
'            SELECT se.id_solicitacao_ext',
'            FROM buf_solicitacao_ext se',
'            JOIN buf_item_solicitacao_ext ie',
'                ON ie.fk_id_solicitacao_ext = se.id_solicitacao_ext',
'            WHERE se.id_solicitacao_ext = :P603_ID_SOLICITACAO',
'                AND se.ind_pendente = ''S''',
'            GROUP BY se.id_solicitacao_ext',
'        )',
'        WHERE ROWNUM BETWEEN v_inicio AND v_fim;',
'',
'        IF v_total_itens = 0 THEN',
'            htp.p(''',
'                <div class="t-Alert t-Alert--warning t-Alert--horizontal t-Alert--defaultIcons">',
'                    <div class="t-Alert-wrap">',
'                        <div class="t-Alert-icon">',
'                            <span class="t-Icon fa fa-info-circle"></span>',
'                        </div>',
'                        <div class="t-Alert-content">',
'                            <div class="t-Alert-header">',
'                                <h2 class="t-Alert-title">',
unistr('                                    N\00E3o h\00E1 eventos externos a ser confirmados.'),
'                                </h2>',
'                            </div>',
'                        </div>',
'                    </div>',
'                </div>',
'            '');',
'        ELSE',
'            htp.p(''<table class="tbl-buffet">'');',
'',
'            htp.p(''',
'            <thead>',
'            <tr>',
'                <th></th>',
'                <th class="col-evento">Evento</th>',
unistr('                <th class="col-servico">Servi\00E7o</th>'),
'                <th class="col-data">Data</th>',
'                <th class="col-hora">Hora</th>',
'                <th class="col-local">Local</th>',
'                <th class="col-detalhes">Detalhes</th>',
'            </tr>',
'            </thead>',
'            <tbody>',
'            '');',
'',
'            FOR sol IN (',
'                SELECT *',
'                FROM (',
'                    SELECT',
'                        se.id_solicitacao_ext,',
'                        se.nom_evento,',
'                        MIN(ie.dat_evento) AS primeira_data,',
'                        ROW_NUMBER() OVER (ORDER BY MIN(ie.dat_evento) DESC) rn',
'                    FROM buf_solicitacao_ext se',
'                    JOIN buf_item_solicitacao_ext ie',
'                        ON ie.fk_id_solicitacao_ext = se.id_solicitacao_ext',
'                    WHERE se.id_solicitacao_ext = :P603_ID_SOLICITACAO',
'                        AND se.ind_pendente = ''S''',
'                    GROUP BY',
'                        se.id_solicitacao_ext,',
'                        se.nom_evento',
'                )',
'                WHERE rn BETWEEN v_inicio AND v_fim',
'            )',
'            LOOP',
'                v_url_deletar := apex_util.prepare_url(',
'                        ''f?p='' || :APP_ID || '':672:'' || :APP_SESSION ||',
'                        ''::NO::P672_ID_SOLICITACAO:'' || sol.id_solicitacao_ext',
'                    );',
'',
'                SELECT COUNT(*)',
'                INTO v_total_itens',
'                FROM buf_item_solicitacao_ext',
'                WHERE fk_id_solicitacao_ext = sol.id_solicitacao_ext;',
'',
'                v_primeiro := TRUE;',
'',
'                FOR item IN (',
'                    SELECT',
'                        ie.id_item_solicitacao_ext,',
'                        ie.fk_id_desc || '' - '' || d.descricao AS descricao,',
'                        ie.dat_evento,',
'                        ie.hor_inicio,',
'                        ie.hor_minuto,',
'                        ie.local',
'                    FROM buf_item_solicitacao_ext ie',
'                    JOIN buf_descricao d',
'                        ON d.id_desc = ie.fk_id_desc',
'                    WHERE ie.fk_id_solicitacao_ext = sol.id_solicitacao_ext',
'                )',
'                LOOP',
'',
'                    v_url_asqualog := apex_util.prepare_url(',
'                        ''f?p='' || :APP_ID || '':671:'' || :APP_SESSION ||',
'                        ''::NO::P671_ID_ITEM:'' || item.id_item_solicitacao_ext',
'                    );',
'',
'                    htp.p(''<tr>'');',
'',
'                    IF v_primeiro THEN',
'                        htp.p(',
'                            ''<td rowspan="''||v_total_itens||''" class="central">',
'                                <a href="''||v_url_deletar||''"',
'                                   class="t-Button t-Button--small t-Button--danger">',
'                                   <span class="fa fa-trash-o"></span>',
'                                </a>',
'                             </td>''',
'                        );',
'',
'                        htp.p(''<td rowspan="''||v_total_itens||''" class="col-evento">''||sol.nom_evento||''</td>'');',
'',
'                        v_primeiro := FALSE;',
'                    END IF;',
'',
'                    htp.p(''<td class="col-servico">''||item.descricao||''</td>'');',
'                    htp.p(''<td class="col-data central">''||',
'                    TO_CHAR(item.dat_evento,''DD/MM/YYYY'')||',
'                    ''</td>'');',
'                    htp.p(''<td class="col-hora central">''||',
'                    item.hor_inicio||',
'                    ''</td>'');',
'                    htp.p(''<td class="col-local central">''||',
'                    item.local||',
'                    ''</td>'');',
'                    htp.p(',
'                        ''<td class="col-detalhes central">',
'                            <a href="''||v_url_asqualog||''"',
'                               class="t-Button t-Button--small">',
'                               <span class="fa fa-eye"></span>',
'                            </a>',
'                        </td>''',
'                    );',
'',
'                    htp.p(''</tr>'');',
'',
'                END LOOP;',
'                htp.p(''',
'                    <tr>',
'                        <td colspan="7" class="separador"></td>',
'                    </tr>',
'                '');',
'',
'            END LOOP;',
'            htp.p(''</tbody></table>'');',
'',
'            DECLARE',
'                v_url_pag VARCHAR2(4000);',
'            BEGIN',
'                htp.p(''<div style="margin-top:15px;text-align:center;">'');',
'                FOR i IN 1..v_total_paginas LOOP',
'                    v_url_pag := apex_page.get_url(',
'                        p_page   => :APP_PAGE_ID,',
'                        p_items  => ''P300_PAGINA'',',
'                        p_values => i',
'                    );',
'',
'                    IF i = v_pagina THEN',
'                        htp.p(',
'                            ''<span class="t-Button t-Button--hot" ',
'                                   style="margin:0 4px;">''||i||''</span>''',
'                        );',
'                    ELSE',
'                        htp.p(',
'                            ''<a class="t-Button" ',
'                                style="margin:0 4px;"',
'                                href="''||v_url_pag||''">''||i||''</a>''',
'                        );',
'                    END IF;',
'                END LOOP;',
'                htp.p(''</div>'');',
'            END;',
'        END IF;',
'    END IF;',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P603_ID_SOLICITACAO'
);
