wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(775767239295239159)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Cadastrar Feedback'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_email_usuario   VARCHAR2(200);',
'    v_email_cc        VARCHAR2(4000);',
'    v_nom_evento      VARCHAR2(4000);',
'    v_mensagem        CLOB;',
'BEGIN',
'    INSERT INTO buf_feedback (',
'        fk_id_solicitacao,',
'        nota_geral,',
'        nota_sabor,',
'        nota_temperatura,',
'        nota_atendimento,',
'        obs_sugestao',
'    ) VALUES (',
'        :P700_ID_SOLICITACAO,',
'        :P700_NOTA_GERAL,',
'        :P700_NOTA_SABOR,',
'        :P700_NOTA_TEMP,',
'        :P700_NOTA_ATENDIMENTO,',
'        :P700_SUGESTAO',
'    );',
'',
'    UPDATE buf_solicitacao',
'    SET ind_feedback = ''S''',
'    WHERE id_solicitacao = :P700_ID_SOLICITACAO;',
'',
unistr('    -- Email do usu\00E1rio logado'),
'    SELECT u.txt_email_sf',
'      INTO v_email_usuario',
'      FROM dda.usuario_rede u',
'     WHERE u.txt_login_ad = :APP_USER;',
'',
unistr('    -- Email(s) respons\00E1vel(is) do evento'),
'    SELECT email_responsavel, nom_evento',
'      INTO v_email_cc, v_nom_evento',
'      FROM buf_solicitacao',
'     WHERE id_solicitacao = :P700_ID_SOLICITACAO;',
'',
'    v_mensagem := ''<html><body>'' ||',
unistr('                  ''<p>O formul\00E1rio de feedback do evento <b>'' || v_nom_evento || ''</b> foi respondido com sucesso.</p>'' ||'),
'                  ''</body></html>'';',
'',
'    APEX_MAIL.SEND(',
'        p_to        => v_email_usuario,',
'        p_cc        => v_email_cc,',
'        p_from      => ''asqualog@senado.leg.br'',',
'        p_subj      => ''Feedback respondido'',',
'        p_body      => NULL,',
'        p_body_html => v_mensagem',
'    );',
'',
'    APEX_MAIL.PUSH_QUEUE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>559889517889013502
);
end;
