wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(775768028809239167)
,p_plug_name=>unistr('M\00E9dia das notas da Temperatura')
,p_parent_plug_id=>wwv_flow_imp.id(1298859523105454773)
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--noBorder:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(711817305933954668)
,p_plug_display_sequence=>50
,p_plug_new_grid_row=>false
,p_plug_display_point=>'SUB_REGIONS'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_media NUMBER;',
'    v_minimo NUMBER;',
'    v_maximo NUMBER;',
'BEGIN',
'    SELECT ',
'        ROUND(AVG(CASE nota_temperatura',
'            WHEN ''S'' THEN 5',
'            WHEN ''M'' THEN 3',
'            WHEN ''N'' THEN 1',
'            WHEN ''NA'' THEN NULL',
'        END), 2),',
'        MIN(CASE nota_temperatura',
'            WHEN ''S'' THEN 5',
'            WHEN ''M'' THEN 3',
'            WHEN ''N'' THEN 1',
'            WHEN ''NA'' THEN NULL',
'        END),',
'        MAX(CASE nota_temperatura',
'            WHEN ''S'' THEN 5',
'            WHEN ''M'' THEN 3',
'            WHEN ''N'' THEN 1',
'            WHEN ''NA'' THEN NULL',
'        END)',
'    INTO v_media, v_minimo, v_maximo',
'    FROM buf_feedback;',
'',
'    htp.p(''<div style="padding: 20px; background-color: #f8f9fa; border-radius: 8px; border-left: 5px solid #00305C; box-shadow: 0 2px 8px rgba(0,0,0,0.08);">'');',
unistr('    htp.p(''  <h3 style="margin: 0 0 8px 0; color: #00305C; font-size: 16px; font-weight: 600;">M\00E9dia Nota Temperatura</h3>'');'),
unistr('    htp.p(''  <p style="margin: 0 0 12px 0; color: #666; font-size: 12px; line-height: 1.4;">M\00E9dia da avalia\00E7\00E3o de temperatura (Bom, M\00E9dio, Ruim).</p>'');'),
'    htp.p(''  <p style="margin: 0; font-size: 36px; font-weight: bold; color: #00305C;">'' || NVL(v_media,0) || ''</p>'');',
'    htp.p(''  <div style="display: flex; gap: 16px; margin-top: 12px; padding-top: 12px; border-top: 1px solid #e0e0e0; flex-wrap: wrap;">'');',
'    htp.p(''    <div style="text-align: center;">'');',
'    htp.p(''      <p style="margin: 0; font-size: 14px; font-weight: 600; color: #00923F;">'' || NVL(v_minimo,0) || ''</p>'');',
unistr('    htp.p(''      <p style="margin: 4px 0 0 0; font-size: 11px; color: #999;">M\00EDnimo</p>'');'),
'    htp.p(''    </div>'');',
'    htp.p(''    <div style="text-align: center;">'');',
'    htp.p(''      <p style="margin: 0; font-size: 14px; font-weight: 600; color: #00923F;">'' || NVL(v_maximo,0) || ''</p>'');',
unistr('    htp.p(''      <p style="margin: 4px 0 0 0; font-size: 11px; color: #999;">M\00E1ximo</p>'');'),
'    htp.p(''    </div>'');',
'    htp.p(''  </div>'');',
'    htp.p(''</div>'');',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(775768215730239168)
,p_plug_name=>'Taxa de Feedbacks'
,p_parent_plug_id=>wwv_flow_imp.id(1298859523105454773)
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--noBorder:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(711817305933954668)
,p_plug_display_sequence=>20
,p_plug_new_grid_row=>false
,p_plug_display_point=>'SUB_REGIONS'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_total_eventos NUMBER;',
'    v_total_feedbacks NUMBER;',
'    v_percent NUMBER;',
'BEGIN',
unistr('    -- Total de eventos conclu\00EDdos que deveriam ter feedback'),
'    SELECT COUNT(DISTINCT s.id_solicitacao)',
'      INTO v_total_eventos',
'      FROM buf_solicitacao s',
'      JOIN buf_item_solicitacao i',
'        ON i.fk_id_solicitacao = s.id_solicitacao',
'     WHERE s.ind_analisado = ''S''',
'       AND s.aprovacao_dger IS NOT NULL',
'       AND i.status = ''Contratado''',
'       AND NOT EXISTS (',
'           SELECT 1',
'             FROM buf_item_solicitacao i2',
'            WHERE i2.fk_id_solicitacao = s.id_solicitacao',
'              AND i2.status = ''Contratado''',
'              AND TRUNC(i2.dat_servico) >= TRUNC(SYSDATE)',
'       );',
'',
'    -- Total de feedbacks feitos para esses eventos',
'    SELECT COUNT(DISTINCT f.fk_id_solicitacao)',
'      INTO v_total_feedbacks',
'      FROM buf_feedback f',
'     WHERE f.fk_id_solicitacao IN (',
'           SELECT DISTINCT s.id_solicitacao',
'             FROM buf_solicitacao s',
'             JOIN buf_item_solicitacao i',
'               ON i.fk_id_solicitacao = s.id_solicitacao',
'            WHERE s.ind_analisado = ''S''',
'              AND s.aprovacao_dger IS NOT NULL',
'              AND i.status = ''Contratado''',
'              AND NOT EXISTS (',
'                  SELECT 1',
'                    FROM buf_item_solicitacao i2',
'                   WHERE i2.fk_id_solicitacao = s.id_solicitacao',
'                     AND i2.status = ''Contratado''',
'                     AND TRUNC(i2.dat_servico) >= TRUNC(SYSDATE)',
'              )',
'       );',
'',
'    IF v_total_eventos > 0 THEN',
'        v_percent := ROUND((v_total_feedbacks * 100) / v_total_eventos, 2);',
'    ELSE',
'        v_percent := 0;',
'    END IF;',
'',
'    htp.p(''<div style="padding: 20px; background-color: #f8f9fa; border-radius: 8px; border-left: 5px solid #00305C; box-shadow: 0 2px 8px rgba(0,0,0,0.08);">'');',
'    htp.p(''  <h3 style="margin: 0 0 8px 0; color: #00305C; font-size: 16px; font-weight: 600;">Feedbacks Recebidos</h3>'');',
unistr('    htp.p(''  <p style="margin: 0 0 12px 0; color: #666; font-size: 12px; line-height: 1.4;">Percentual de eventos conclu\00EDdos que j\00E1 receberam feedback</p>'');'),
'    htp.p(''  <p style="margin: 0; font-size: 36px; font-weight: bold; color: #00305C;">'' || v_percent || ''%</p>'');',
'    htp.p(''  <div style="margin-top: 12px; padding-top: 12px; border-top: 1px solid #e0e0e0;">'');',
'    htp.p(''    <p style="margin: 0; color: #999; font-size: 11px;"><span style="color: #00305C; font-weight: 600;">'' || v_total_feedbacks || ''</span> de <span style="color: #00305C; font-weight: 600;">'' || v_total_eventos || ''</span> eventos com feed'
||'back</p>'');',
'    htp.p(''  </div>'');',
'    htp.p(''</div>'');',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
