'    v_minimo NUMBER;',
'    v_maximo NUMBER;',
'BEGIN',
'    SELECT ',
'        ROUND(AVG(CASE nota_atendimento',
'            WHEN ''S'' THEN 5',
'            WHEN ''M'' THEN 3',
'            WHEN ''N'' THEN 1',
'            WHEN ''NA'' THEN NULL',
'        END), 2),',
'        MIN(CASE nota_atendimento',
'            WHEN ''S'' THEN 5',
'            WHEN ''M'' THEN 3',
'            WHEN ''N'' THEN 1',
'            WHEN ''NA'' THEN NULL',
'        END),',
'        MAX(CASE nota_atendimento',
'            WHEN ''S'' THEN 5',
'            WHEN ''M'' THEN 3',
'            WHEN ''N'' THEN 1',
'            WHEN ''NA'' THEN NULL',
'        END)',
'    INTO v_media, v_minimo, v_maximo',
'    FROM buf_feedback;',
'',
'    htp.p(''<div style="padding: 20px; background-color: #f8f9fa; border-radius: 8px; border-left: 5px solid #00305C; box-shadow: 0 2px 8px rgba(0,0,0,0.08);">'');',
unistr('    htp.p(''  <h3 style="margin: 0 0 8px 0; color: #00305C; font-size: 16px; font-weight: 600;">M\00E9dia Nota Atendimento</h3>'');'),
unistr('    htp.p(''  <p style="margin: 0 0 12px 0; color: #666; font-size: 12px; line-height: 1.4;">M\00E9dia da avalia\00E7\00E3o de atendimento (Bom, M\00E9dio, Ruim).</p>'');'),
'    htp.p(''  <p style="margin: 0; font-size: 36px; font-weight: bold; color: #00305C;">'' || NVL(v_media,0) || ''</p>'');',
