wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(843893186582148759)
,p_plug_name=>unistr('Eventos Confirmados n\00E3o Enviados ao Senac')
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(711817305933954668)
,p_plug_display_sequence=>10
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_total_itens NUMBER;',
'    v_primeiro BOOLEAN;',
'    ',
'    v_url_upload    VARCHAR2(4000);',
'    v_url_pag       VARCHAR2(4000);',
'    v_url_eye       VARCHAR2(4000);',
'',
'    v_limite        CONSTANT NUMBER := 15;',
'    v_pagina        NUMBER := NVL(:P500_PAGINA,1);',
'    v_total_registros   NUMBER;',
'    v_total_paginas     NUMBER;',
'',
'    v_inicio        NUMBER;',
'    v_fim           NUMBER;',
'    ',
'    v_output CLOB;',
'    v_temp   VARCHAR2(32767);',
'',
'BEGIN',
'',
'    DBMS_LOB.CREATETEMPORARY(v_output, TRUE);',
'',
'    v_inicio := (v_pagina - 1) * v_limite + 1;',
'    v_fim    := v_pagina * v_limite;',
'',
'    SELECT COUNT(DISTINCT s.id_solicitacao)',
'    INTO v_total_registros',
'    FROM buf_solicitacao s',
'    WHERE s.ind_analisado = ''S''',
'      AND s.ind_senac     = ''N''',
'      AND EXISTS (',
'          SELECT 1',
'          FROM buf_item_solicitacao ix',
'          WHERE ix.fk_id_solicitacao = s.id_solicitacao',
'            AND ix.status = ''Contratado''',
'      );',
'',
'    IF v_total_registros = 0 THEN',
'        v_temp := ''',
'            <div class="t-Alert t-Alert--warning t-Alert--horizontal t-Alert--defaultIcons">',
'                <div class="t-Alert-wrap">',
'                    <div class="t-Alert-icon">',
'                        <span class="t-Icon fa fa-info-circle"></span>',
'                    </div>',
'                    <div class="t-Alert-content">',
'                        <div class="t-Alert-header">',
'                            <h2 class="t-Alert-title">',
unistr('                                N\00E3o h\00E1 eventos confirmados para enviar ao Senac.'),
'                            </h2>',
'                        </div>',
'                    </div>',
'                </div>',
'            </div>',
'        '';',
'        DBMS_LOB.APPEND(v_output, v_temp);',
'    ELSE',
'        v_total_paginas := CEIL(v_total_registros / v_limite);',
'',
'        v_temp := ''<table class="tbl-buffet">'';',
'        DBMS_LOB.APPEND(v_output, v_temp);',
'',
'        v_temp := ''',
'        <thead>',
'        <tr>',
'            <th></th>',
'            <th class="col-solicitante">Solicitante</th>',
unistr('            <th class="col-orgao">\00D3rg\00E3o</th>'),
'            <th class="col-evento">Evento</th>',
unistr('            <th class="col-servico">Servi\00E7o</th>'),
'            <th class="col-data">Data</th>',
unistr('            <th class="col-horarios">Hor\00E1rios</th>'),
'            <th class="col-pessoas">Pessoas</th>',
'            <th class="col-local">Local</th>',
'            <th class="col-status">Status</th>',
'            <th class="col-valor">Valor</th>',
'            <th class="col-detalhes">Obs</th>',
'        </tr>',
'        </thead>',
'        <tbody>',
'        '';',
'        DBMS_LOB.APPEND(v_output, v_temp);',
'',
'        FOR sol IN (',
'            SELECT *',
'            FROM (',
'                SELECT',
'                    s.id_solicitacao,',
'                    s.nom_solicitante,',
'                    s.sgl_orgao,',
'                    s.nom_evento,',
'                    MIN(i.dat_servico) AS primeira_data,',
'                    ROW_NUMBER() OVER (ORDER BY MIN(i.dat_servico) DESC) rn',
'                FROM buf_solicitacao s',
'                JOIN buf_item_solicitacao i ON i.fk_id_solicitacao = s.id_solicitacao',
'                WHERE s.ind_analisado = ''S''',
'                  AND s.ind_senac     = ''N''',
'                  AND EXISTS (',
'                      SELECT 1',
'                      FROM buf_item_solicitacao ix',
'                      WHERE ix.fk_id_solicitacao = s.id_solicitacao',
'                        AND ix.status = ''Contratado''',
'                  )',
'                GROUP BY',
'                    s.id_solicitacao,',
'                    s.nom_solicitante,',
'                    s.sgl_orgao,',
'                    s.nom_evento',
'            )',
'            WHERE rn BETWEEN v_inicio AND v_fim',
'        )',
'        LOOP',
'            SELECT COUNT(*)',
'            INTO v_total_itens',
'            FROM buf_item_solicitacao',
'            WHERE fk_id_solicitacao = sol.id_solicitacao',
'              AND status = ''Contratado'';',
'',
'            v_url_upload := apex_util.prepare_url(',
'                    ''f?p='' || :APP_ID || '':871:'' || :APP_SESSION ||',
'                    ''::NO::P871_ID_SOLICITACAO:'' || sol.id_solicitacao',
'                );',
'',
'            v_primeiro := TRUE;',
'',
'            FOR item IN (',
'                SELECT',
'                    i.id_item,',
'                    i.fk_id_desc || '' - '' || d.descricao AS descricao,',
'                    i.dat_servico,',
'                    i.qtd_pessoas,',
'                    i.local,',
'                    i.status,',
'                    i.valor_item,',
'                    (',
'                        SELECT LISTAGG(h.hor, '', '') WITHIN GROUP (ORDER BY h.hor)',
'                        FROM buf_hor_item h',
'                        WHERE h.fk_id_item = i.id_item',
'                    ) AS horarios',
'                FROM buf_item_solicitacao i',
'                JOIN buf_descricao d',
'                    ON d.id_desc = i.fk_id_desc',
'                WHERE i.fk_id_solicitacao = sol.id_solicitacao',
'                  AND i.status = ''Contratado''',
'            )',
'            LOOP',
'                v_url_eye := apex_util.prepare_url(',
'                    ''f?p='' || :APP_ID || '':870:'' || :APP_SESSION ||',
'                    ''::NO::P870_ID_ITEM:'' || item.id_item',
'                );',
'',
'                v_temp := ''<tr>'';',
'                DBMS_LOB.APPEND(v_output, v_temp);',
'',
'                IF v_primeiro THEN',
'                    v_temp := ''',
'                        <td rowspan="''||v_total_itens||''" class="central">',
'                            <a href="''||v_url_upload||''"',
'                               class="t-Button t-Button--small t-Button--info"',
'                               title="Enviar e-mail">',
'                               <span class="fa fa-envelope-o"></span>',
'                            </a>',
'                         </td>'';',
'                    DBMS_LOB.APPEND(v_output, v_temp);',
'',
'                    v_temp := ''<td rowspan="''||v_total_itens||''" class="col-solicitante">''||sol.nom_solicitante||''</td>'';',
'                    DBMS_LOB.APPEND(v_output, v_temp);',
'',
'                    v_temp := ''<td rowspan="''||v_total_itens||''" class="col-orgao central">''||sol.sgl_orgao||''</td>'';',
'                    DBMS_LOB.APPEND(v_output, v_temp);',
'',
'                    v_temp := ''<td rowspan="''||v_total_itens||''" class="col-evento">''||sol.nom_evento||''</td>'';',
'                    DBMS_LOB.APPEND(v_output, v_temp);',
'',
'                    v_primeiro := FALSE;',
'                END IF;',
'',
'                v_temp := ''<td class="col-servico">''||item.descricao||''</td>'';',
'                DBMS_LOB.APPEND(v_output, v_temp);',
'',
'                v_temp := ''<td class="col-data central">''||TO_CHAR(item.dat_servico,''DD/MM/YYYY'')||''</td>'';',
'                DBMS_LOB.APPEND(v_output, v_temp);',
'',
'                v_temp := ''<td class="col-horarios central">''||NVL(item.horarios,''-'')||''</td>'';',
'                DBMS_LOB.APPEND(v_output, v_temp);',
'',
'                v_temp := ''<td class="col-pessoas central">''||item.qtd_pessoas||''</td>'';',
'                DBMS_LOB.APPEND(v_output, v_temp);',
'',
'                v_temp := ''<td class="col-local central">''||item.local||''</td>'';',
'                DBMS_LOB.APPEND(v_output, v_temp);',
'',
'                v_temp := ''<td class="col-status central">''||item.status||''</td>'';',
'                DBMS_LOB.APPEND(v_output, v_temp);',
'',
'                v_temp := ''<td class="col-valor valor">R$ ''||TO_CHAR(item.valor_item,''FM999G999G990D00'')||''</td>'';',
'                DBMS_LOB.APPEND(v_output, v_temp);',
'',
'                v_temp := ''',
'                    <td class="col-detalhes central">',
'                        <div style="display: flex; gap: 4px; justify-content: center; align-items: center;">',
'                            <a href="'' || v_url_eye || ''"',
'                               class="t-Button t-Button--small t-Button"',
'                               title="Visualizar"',
'                               style="opacity: 1;">',
'                               <span class="fa fa-eye"></span>',
'                            </a>',
'                        </div>',
'                    </td>'';',
'                DBMS_LOB.APPEND(v_output, v_temp);',
'',
'                v_temp := ''</tr>'';',
'                DBMS_LOB.APPEND(v_output, v_temp);',
'',
'            END LOOP;',
'',
'            v_temp := ''',
'                <tr>',
'                    <td colspan="12" class="separador"></td>',
'                </tr>',
'            '';',
'            DBMS_LOB.APPEND(v_output, v_temp);',
'',
'        END LOOP;',
'',
'        v_temp := ''</tbody></table>'';',
'        DBMS_LOB.APPEND(v_output, v_temp);',
'',
'        v_temp := ''<div style="margin-top:15px;text-align:center;">'';',
'        DBMS_LOB.APPEND(v_output, v_temp);',
'',
'        FOR i IN 1..v_total_paginas LOOP',
'            v_url_pag := apex_page.get_url(',
'                p_page   => :APP_PAGE_ID,',
'                p_items  => ''P500_PAGINA'',',
'                p_values => i',
'            );',
'',
'            IF i = v_pagina THEN',
'                v_temp := ''',
'                    <span class="t-Button t-Button--hot" ',
'                           style="margin:0 4px;">''||i||''</span>'';',
'            ELSE',
'                v_temp := ''',
'                    <a class="t-Button" ',
'                        style="margin:0 4px;"',
'                        href="''||v_url_pag||''">''||i||''</a>'';',
'            END IF;',
'            DBMS_LOB.APPEND(v_output, v_temp);',
'        END LOOP;',
'',
'        v_temp := ''</div>'';',
'        DBMS_LOB.APPEND(v_output, v_temp);',
'',
'    END IF;',
'    ',
'    RETURN v_output;',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(844009439747480064)
,p_plug_name=>'Breadcrumb'
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--noBorder:t-Region--scrollBody:margin-top-md'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(711817305933954668)
,p_plug_display_sequence=>10
,p_plug_display_point=>'REGION_POSITION_01'
,p_menu_id=>wwv_flow_imp.id(711719349587954595)
,p_plug_source_type=>'NATIVE_BREADCRUMB'
,p_menu_template_id=>wwv_flow_imp.id(712097450312954727)
);
end;
