wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(844065183747680143)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('Colocar a Autoriza\00E7\00E3o')
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_evento              VARCHAR2(4000);',
'    v_setor_solicitante   VARCHAR2(200);',
'    v_email_destino       VARCHAR2(200) := ''ana.vieira@senac.br'';',
'    v_email_cc            VARCHAR2(4000);',
'    v_assunto             VARCHAR2(300) := ''Itens contratados do evento'';',
'    v_mensagem            CLOB;',
'    l_mail_id             NUMBER;',
'',
'    v_qtd_horarios        NUMBER;',
'    v_primeiro            BOOLEAN;',
'    v_emails_responsaveis VARCHAR2(4000);',
'',
'    v_nome_asqualog       VARCHAR2(200);',
'',
unistr('    -- Din\00E2micos para o bloco final no modelo solicitado'),
'    v_qtd_total_itens     NUMBER;',
'    v_data_evento         DATE;',
'    v_hora_evento         VARCHAR2(5);',
'    v_nome_comissao       VARCHAR2(500);',
'',
'    v_blob_aprovacao    BLOB;',
'    v_filename          VARCHAR2(200);',
'    v_mimetype          VARCHAR2(200);',
'BEGIN',
'    SELECT vs.nom_pessoa INTO v_nome_asqualog',
'    FROM dda.vinculo_sf vs',
'    JOIN dda.usuario_rede u ON vs.num_cpf = u.num_cpf_pessoa',
'    WHERE u.txt_login_ad = :APP_USER;',
'',
unistr('    -- Dados da solicita\00E7\00E3o atual'),
'    SELECT nom_evento, sgl_orgao, email_responsavel',
'      INTO v_evento, v_setor_solicitante, v_emails_responsaveis',
'      FROM buf_solicitacao',
'     WHERE id_solicitacao = :P871_ID_SOLICITACAO;',
'    ',
'    SELECT nom_orgao INTO v_nome_comissao',
'    FROM dda.orgao',
'    WHERE situacao = ''ATIVO''',
'        AND sgl_orgao = v_setor_solicitante;',
'',
'    SELECT aprovacao_dger, filename, mimetype',
'    INTO v_blob_aprovacao, v_filename, v_mimetype',
'    FROM buf_solicitacao',
'    WHERE id_solicitacao = :P871_ID_SOLICITACAO;',
'',
'    v_email_cc :=',
'        ''valquiria.hernandes@senac.br,'' ||',
'        ''paula.guimaraes@senac.br,'' ||',
'        ''francinete.brito@senac.br,'' ||',
'        NVL(v_emails_responsaveis || '','', '''') ||',
'        ''asqualog@senado.leg.br,'' ||',
'        ''sequalog-equipe@senado.gov.br'';',
'',
'    v_email_cc := REGEXP_REPLACE(v_email_cc, ''(^,|,$)'', '''');',
'',
'    -- Total de "lunch-boxes" (aqui usando soma de qtd_pessoas dos itens contratados)',
'    SELECT NVL(SUM(i.qtd_pessoas), 0)',
'      INTO v_qtd_total_itens',
'      FROM buf_item_solicitacao i',
'     WHERE i.fk_id_solicitacao = :P871_ID_SOLICITACAO',
'       AND i.status = ''Contratado'';',
'',
unistr('    -- Data/hora de refer\00EAncia do evento (menor data e menor hor\00E1rio dos itens contratados)'),
'    SELECT MIN(i.dat_servico),',
'           MIN(SUBSTR(h.hor, 1, 5))',
'      INTO v_data_evento, v_hora_evento',
'      FROM buf_item_solicitacao i',
'      LEFT JOIN buf_hor_item h',
'        ON h.fk_id_item = i.id_item',
'     WHERE i.fk_id_solicitacao = :P871_ID_SOLICITACAO',
'       AND i.status = ''Contratado'';',
'',
unistr('    -- Fallbacks caso n\00E3o haja hor\00E1rio/data nos itens'),
'    IF v_data_evento IS NULL THEN',
'        v_data_evento := SYSDATE;',
'    END IF;',
'',
'    IF v_hora_evento IS NULL THEN',
'        v_hora_evento := ''--:--'';',
'    END IF;',
'',
'    -- Monta HTML',
'    v_mensagem :=',
'        ''<html>',
'         <body style="font-family: Arial, Helvetica, sans-serif; font-size:14px; color:#333; line-height:1.6;">',
'',
unistr('            <!-- 1. SAUDA\00C7\00C3O E TEXTO PRINCIPAL -->'),
'            <p>Prezadas,</p>',
'',
'            <p>',
unistr('                Encaminhamos, para conhecimento e provid\00EAncias, a autoriza\00E7\00E3o da Diretoria-Geral'),
unistr('                para disponibiliza\00E7\00E3o de <b>'' || TO_CHAR(v_qtd_total_itens) || '' ('' || numero_extenso(v_qtd_total_itens) || '')</b>'),
'                Lunch Boxes destinados aos participantes do evento',
'                <b>'' || v_evento || ''</b>,',
'                a ser realizado pela <b>'' || v_nome_comissao || ''</b>,',
'                no dia <b>'' ||',
'                    TO_CHAR(v_data_evento, ''DD "de" Month "de" YYYY'', ''NLS_DATE_LANGUAGE=PORTUGUESE'') ||',
unistr('                ''</b>, \00E0s <b>'' || v_hora_evento || ''</b>.'),
'            </p>',
'',
unistr('            <p>Solicito, por gentileza, o envio do card\00E1pio para aprova\00E7\00E3o.</p>'),
'',
'            <p>',
unistr('                Para eventuais detalhes, coloco em c\00F3pia a @Kamila,'),
unistr('                representante da \00E1rea demandante.'),
'            </p>',
'',
unistr('            <!-- 2. INTRODU\00C7\00C3O DA TABELA -->'),
'            <p>Segue resumo dos <b>itens contratados</b>:</p>',
'',
'            <!-- 3. EVENTO E UNIDADE -->',
'            <p>',
'                <b>Evento:</b> '' || v_evento || ''<br>',
'                <b>Unidade Solicitante:</b> '' || v_setor_solicitante || ''',
'            </p>',
'',
'            <!-- 4. TABELA DE ITENS -->',
'            <table style="',
'                border-collapse: collapse;',
'                width: 100%;',
'                max-width: 900px;',
'                margin-top: 10px;',
'                border: 1px solid #ddd;',
'            ">',
'                <tr style="background-color:#d4edda;">',
unistr('                    <th style="padding:8px; border:1px solid #ddd;">Servi\00E7o</th>'),
'                    <th style="padding:8px; border:1px solid #ddd;">Data</th>',
unistr('                    <th style="padding:8px; border:1px solid #ddd;">N\00BA de Pessoas</th>'),
unistr('                    <th style="padding:8px; border:1px solid #ddd;">Hor\00E1rio</th>'),
unistr('                    <th style="padding:8px; border:1px solid #ddd;">Quantidade por Hor\00E1rio</th>'),
'                    <th style="padding:8px; border:1px solid #ddd;">Local</th>',
'                    <th style="padding:8px; border:1px solid #ddd;">Valor</th>',
'                </tr>'';',
'',
'    FOR item IN (',
'        SELECT',
'            i.id_item,',
'            d.descricao,',
'            i.dat_servico,',
'            i.qtd_pessoas AS qtd_total,',
'            i.local,',
'            i.valor_item',
'        FROM buf_item_solicitacao i',
'        JOIN buf_descricao d',
'          ON d.id_desc = i.fk_id_desc',
'       WHERE i.fk_id_solicitacao = :P871_ID_SOLICITACAO',
'         AND i.status = ''Contratado''',
'       ORDER BY i.dat_servico, d.descricao',
'    )',
'    LOOP',
'        SELECT COUNT(*)',
'          INTO v_qtd_horarios',
'          FROM buf_hor_item h',
'         WHERE h.fk_id_item = item.id_item;',
'',
'        IF v_qtd_horarios = 0 THEN',
'            v_qtd_horarios := 1;',
'        END IF;',
'',
'        v_primeiro := TRUE;',
'',
'        FOR h IN (',
'            SELECT hor, qtd_hor',
'              FROM buf_hor_item',
'             WHERE fk_id_item = item.id_item',
'             ORDER BY hor_minuto',
'        )',
'        LOOP',
'            v_mensagem := v_mensagem || ''<tr>'';',
'',
'            IF v_primeiro THEN',
'                v_mensagem := v_mensagem ||',
'                    ''<td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;">'' ||',
'                        item.descricao || ''</td>',
'                     <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:center;">'' ||',
'                        TO_CHAR(item.dat_servico, ''DD/MM/YYYY'') || ''</td>',
'                     <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:center;">'' ||',
'                        NVL(TO_CHAR(item.qtd_total), ''-'') || ''</td>'';',
'            END IF;',
'',
'            v_mensagem := v_mensagem ||',
'                 ''<td style="padding:8px;border:1px solid #ddd;text-align:center;">'' ||',
'                     NVL(h.hor, ''-'') || ''</td>',
'                  <td style="padding:8px;border:1px solid #ddd;text-align:center;">'' ||',
'                     NVL(TO_CHAR(h.qtd_hor), ''-'') || ''</td>'';',
'',
'            IF v_primeiro THEN',
'                v_mensagem := v_mensagem ||',
'                    ''<td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;">'' ||',
'                        NVL(item.local, ''-'') || ''</td>',
'                     <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:right;">R$ '' ||',
'                        NVL(TO_CHAR(item.valor_item, ''FM999G999G990D00''), ''-'') || ''</td>'';',
'            END IF;',
'',
'            v_mensagem := v_mensagem || ''</tr>'';',
'            v_primeiro := FALSE;',
'        END LOOP;',
'',
unistr('        -- Se n\00E3o houver hor\00E1rios'),
'        IF v_primeiro THEN',
'            v_mensagem := v_mensagem ||',
'                ''<tr>',
'                    <td style="padding:8px;border:1px solid #ddd;">''||item.descricao||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">''||TO_CHAR(item.dat_servico,''DD/MM/YYYY'')||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">''||NVL(TO_CHAR(item.qtd_total), ''-'')||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">-</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">-</td>',
'                    <td style="padding:8px;border:1px solid #ddd;">''||NVL(item.local,''-'')||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:right;">R$ ''||',
'                        NVL(TO_CHAR(item.valor_item,''FM999G999G990D00''),''-'')||''</td>',
'                </tr>'';',
'        END IF;',
'    END LOOP;',
'',
'    v_mensagem := v_mensagem ||',
'        ''</table>',
'',
'         <!-- 5. ASSINATURA -->',
'         <br>',
'         <p style="margin-top:20px; color:#1a5276;">Atenciosamente,</p>',
'',
'         <p>',
'             <b style="color:#1a5276;">'' || v_nome_asqualog || ''</b><br>',
'             <span style="color:#1a5276;">',
unistr('             Assessoria de Qualidade de Atendimento e Log\00EDstica \2013 ASQUALOG<br>'),
'             Diretoria-Geral',
'             </span>',
'         </p>',
'',
'         <p><i>Mensagem encaminhada via Sistema de Buffet</i></p>',
'',
'         </body>',
'        </html>'';',
'',
'    l_mail_id := APEX_MAIL.SEND(',
'        p_to        => v_email_destino,',
'        p_cc      => v_email_cc,',
'        p_from      => ''asqualog@senado.leg.br'',',
'        p_subj      => v_assunto || '' - '' || v_evento,',
'        p_body      => NULL,',
'        p_body_html => v_mensagem',
'    );',
'',
'    apex_mail.add_attachment(',
'        p_mail_id    => l_mail_id,',
'        p_attachment => v_blob_aprovacao,',
'        p_filename   => v_filename,',
'        p_mime_type  => v_mimetype',
'    );',
'',
'    APEX_MAIL.PUSH_QUEUE;',
'',
'    UPDATE buf_solicitacao',
'       SET ind_senac = ''S''',
'     WHERE id_solicitacao = :P871_ID_SOLICITACAO;',
'',
'    COMMIT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>628187462341454486
);
end;
/
