wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1975094303321373336)
,p_plug_name=>'Detalhes do Buffet'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(711807441892954664)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT d.id_desc AS "Item",',
unistr('    d.descricao AS "Descri\00E7\00E3o",'),
unistr('    d.tempo_servico AS "Tempo de Servi\00E7o",'),
unistr('    ''R$ '' || TO_CHAR(d.valor, ''FM9999990D00'', ''NLS_NUMERIC_CHARACTERS = '''',.'''''') AS "Valor Unit\00E1rio",'),
unistr('    d.qtd_disponivel AS "Quantidade Dispon\00EDvel",'),
unistr('    LISTAGG(e.detalhe || ''<br>'') WITHIN GROUP (ORDER BY e.id_esp) AS "Especifica\00E7\00F5es",'),
'    apex_item.hidden(',
'        p_idx   => 2,',
'        p_value => id_desc',
'    ) ||',
'',
'    apex_item.text(',
'        p_idx        => 1,',
'        p_value      => qtd_disponivel,',
'        p_item_id    => ''QTD_'' || id_desc,',
'        p_size       => 5,',
'        p_maxlength  => 5',
'    ) AS nova_qtd',
'FROM buf_descricao d',
'JOIN buf_especificacao e ON d.id_desc = e.fk_id_desc',
'GROUP BY',
'    id_desc,',
'    descricao,',
'    tempo_servico,',
'    valor,',
'    qtd_disponivel'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'MILLIMETERS'
,p_prn_paper_size=>'A4'
,p_prn_width=>297
,p_prn_height=>210
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Detalhes do Buffet'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
,p_prn_body_font_color=>'#000000'
