'        IF :P1000_ACAO = ''CANCELAR'' THEN',
'            UPDATE buf_item_solicitacao',
'            SET status = ''Cancelado''',
'            WHERE id_item = :P1000_ID_ITEM;',
'        ELSIF :P1000_ACAO = ''NEGOCIAR'' THEN',
'            UPDATE buf_item_solicitacao',
unistr('            SET status = ''Em negocia\00E7\00E3o'''),
'            WHERE id_item = :P1000_ID_ITEM;',
'        ELSIF :P1000_ACAO = ''CONTRATAR'' THEN',
'            UPDATE buf_item_solicitacao',
'            SET status = ''Contratado''',
'            WHERE id_item = :P1000_ID_ITEM;',
'        END IF;',
'    END IF;',
'',
'    :P1000_ID_ITEM := NULL;',
'    :P1000_ACAO := NULL;',
'END;'))
,p_attribute_02=>'P1000_ID_ITEM,P1000_ACAO'
,p_attribute_03=>'P1000_ID_ITEM,P1000_ACAO'
