wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(252287900453378520)
,p_process_sequence=>20
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Enviar emails'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_blob              BLOB;',
'    v_filename          VARCHAR2(200);',
'    v_mimetype          VARCHAR2(200);',
'',
'    v_evento            VARCHAR2(4000);',
'    v_setor_solicitante VARCHAR2(200);',
'    v_email_remetente   VARCHAR2(200) := ''asqualog@senado.leg.br'';',
'    v_email_cc          VARCHAR2(4000);',
'    ',
'    v_mensagem          CLOB;',
'',
'    l_mail_id_senac           NUMBER;',
'    l_mail_id_dger            NUMBER;',
'    l_mail_id_solicitante     NUMBER;',
'',
'    v_qtd_horarios      NUMBER;',
'    v_primeiro          BOOLEAN;',
'    v_email_solicitante VARCHAR2(4000);',
'    v_emails_responsaveis VARCHAR2(4000);',
'',
'    v_nome_resp  VARCHAR2(200);',
'    v_setor_resp        VARCHAR2(200);',
'BEGIN',
unistr('    -- Busca do arquivo tempor\00E1rio'),
'    SELECT blob_content, mime_type, filename',
'      INTO v_blob, v_mimetype, v_filename',
'      FROM apex_application_temp_files',
'     WHERE name = :P1070_EMAIL;',
'',
'    -- Devolve quantidade ao estoque para itens Cancelados',
'    UPDATE buf_descricao bd',
'       SET qtd_disponivel = qtd_disponivel + (',
'           SELECT SUM(bis.qtd_pessoas)',
'             FROM buf_item_solicitacao bis',
'            WHERE bis.fk_id_desc = bd.id_desc',
'              AND bis.fk_id_solicitacao = :P1070_ID_SOLICITACAO',
'              AND bis.status = ''Cancelado''',
'       )',
'     WHERE EXISTS (',
'           SELECT 1',
'             FROM buf_item_solicitacao bis',
'            WHERE bis.fk_id_desc = bd.id_desc',
'              AND bis.fk_id_solicitacao = :P1070_ID_SOLICITACAO',
'              AND bis.status = ''Cancelado''',
'       );',
'',
unistr('    -- Atualiza a solicita\00E7\00E3o com o BLOB e marca como analisado'),
'    UPDATE buf_solicitacao',
'       SET email_senac = v_blob,',
'           mimetype_senac  = v_mimetype,',
'           filename_senac  = v_filename',
'     WHERE id_solicitacao = :P1070_ID_SOLICITACAO;',
'',
unistr('    -- Nome do evento e e-mails respons\00E1veis (solicitante)'),
'    SELECT nom_evento, email_responsavel, sgl_orgao',
'      INTO v_evento, v_emails_responsaveis, v_setor_solicitante',
'      FROM buf_solicitacao',
'     WHERE id_solicitacao = :P1070_ID_SOLICITACAO;',
'',
'    -- Nome do solicitante e e-mail remetente',
'    SELECT vs.nom_pessoa, u.txt_email_sf',
'      INTO v_nome_resp, v_email_remetente',
'      FROM dda.vinculo_sf vs',
'      JOIN dda.usuario_rede u',
'        ON vs.num_cpf = u.num_cpf_pessoa',
'     WHERE LOWER(u.txt_login_ad) = LOWER(:APP_USER);',
'    ',
'    SELECT o.sgl_orgao || '' - '' || o.nom_orgao INTO v_setor_resp',
'    FROM dda.orgao o',
'    JOIN dda.vinculo_sf vs ON o.sgl_orgao = vs.sgl_orgao_exercicio',
'    WHERE vs.ind_vinculo_ativo = ''S''',
'        AND vs.num_cpf = (',
'            SELECT u.num_cpf_pessoa',
'            FROM dda.usuario_rede u',
'            WHERE LOWER(u.txt_login_ad) = LOWER(:APP_USER)',
'        );',
'',
unistr('    -- Vari\00E1vel usada no texto do e-mail (permanece igual)'),
'    v_email_solicitante := v_emails_responsaveis;',
'',
unistr('    -- Monta v_email_cc com lista fixa + respons\00E1veis'),
'    v_email_cc :=',
'        ''valquiria.hernandes@senac.br,'' ||',
'        ''paula.guimaraes@senac.br,'' ||',
'        ''francinete.brito@senac.br,'' ||',
'        NVL(v_emails_responsaveis || '','', '''') ||',
'        ''sequalog-equipe@senado.gov.br'';',
'',
'    v_email_cc := REGEXP_REPLACE(v_email_cc, ''(^,|,$)'', '''');',
'',
'    v_mensagem :=',
'    ''<html>',
'        <body style="font-family: Arial, Helvetica, sans-serif; font-size:14px; color:#333; line-height:1.6;">',
'',
'            <p>Prezadas,</p>',
'',
'            <p>',
unistr('                Informamos que a solicita\00E7\00E3o de buffet referente ao evento'),
unistr('                <b>'' || v_evento || ''</b> foi enviada para an\00E1lise da Diretoria-Geral.'),
'            </p>',
'',
'            <p>',
unistr('                Podem iniciar as provid\00EAncias operacionais para atendimento da demanda,'),
unistr('                conforme autoriza\00E7\00E3o anexa.'),
'            </p>',
'',
'            <p>',
unistr('                Os respons\00E1veis pelo evento foram copiados neste e-mail para facilitar'),
unistr('                eventuais alinhamentos relativos ao card\00E1pio e \00E0 execu\00E7\00E3o do servi\00E7o.'),
'            </p>',
'',
'            <br>',
'',
'            <p>',
'                Atenciosamente,',
'            </p>',
'',
'            <p>',
'                <b>'' || v_nome_resp || ''</b><br>',
'                '' || v_setor_resp || ''<br>',
unistr('                Assessoria de Qualidade de Atendimento e Log\00EDstica \2013 ASQUALOG<br>'),
'                Senado Federal',
'            </p>',
'',
'            <p style="font-size:12px;color:#666;margin-top:20px;">',
unistr('                Este \00E9 um e-mail autom\00E1tico do Sistema de Buffet.'),
'            </p>',
'',
'        </body>',
'    </html>'';',
'',
'    l_mail_id_senac := APEX_MAIL.SEND(',
'        -- p_to        => ''ana.vieira@senac.br'',',
'        -- p_cc        => v_email_cc,',
'        p_to        => ''marcelo.kobayashi@senado.leg.br'',',
'        p_from      => v_email_remetente,',
unistr('        p_subj      => ''Solicita\00E7\00E3o de Buffet Autorizada - In\00EDcio das Provid\00EAncias'','),
'        p_body      => NULL,',
'        p_body_html => v_mensagem',
'    );',
'',
'    apex_mail.add_attachment(',
'        p_mail_id    => l_mail_id_senac,',
'        p_attachment => v_blob,',
'        p_filename   => v_filename,',
'        p_mime_type  => v_mimetype',
'    );',
'',
'    /*',
unistr('        In\00EDcio do email para a DGER'),
'    */',
'',
'    v_email_cc := ''guilherme.schettini@senado.leg.br,LAFUENTE@senado.leg.br,JSOLON@senado.leg.br,asqualog@senado.leg.br,sequalog-equipe@senado.gov.br,'' ||',
'                  COALESCE(v_email_solicitante, '''');',
'',
'    v_email_cc := REGEXP_REPLACE(v_email_cc, '',$'', '''');',
'',
'    v_mensagem :=',
'    ''<html>',
'        <body style="font-family: Arial, Helvetica, sans-serif; font-size:14px; color:#333;">',
'',
'            <p>Prezados(as),</p>',
'',
'            <p>',
unistr('                Informamos que a solicita\00E7\00E3o de buffet referente ao evento'),
'                <b>'' || v_evento || ''</b> foi autorizada pelo Senac.',
'            </p>',
'',
'            <p>',
unistr('                Seguem abaixo os servi\00E7os autorizados (contratados).'),
'            </p>',
'',
'            <p>',
'                <b>Evento:</b> '' || v_evento || ''<br>',
'                <b>Unidade Solicitante:</b> '' || v_setor_solicitante || ''',
'            </p>',
'',
'            <table style="',
'                border-collapse:collapse;',
'                width:100%;',
'                max-width:900px;',
'                margin-top:10px;',
'                border:1px solid #ddd;',
'            ">',
'                <tr style="background-color:#d4edda;">',
unistr('                    <th style="padding:8px;border:1px solid #ddd;">Servi\00E7o</th>'),
'                    <th style="padding:8px;border:1px solid #ddd;">Data</th>',
unistr('                    <th style="padding:8px;border:1px solid #ddd;">N\00BA de Pessoas</th>'),
unistr('                    <th style="padding:8px;border:1px solid #ddd;">Hor\00E1rio</th>'),
unistr('                    <th style="padding:8px;border:1px solid #ddd;">Quantidade por Hor\00E1rio</th>'),
'                    <th style="padding:8px;border:1px solid #ddd;">Local</th>',
'                    <th style="padding:8px;border:1px solid #ddd;">Valor</th>',
'                </tr>'';',
'    ',
'    FOR item IN (',
'        SELECT',
'            i.id_item,',
'            d.descricao,',
'            i.dat_servico,',
'            i.qtd_pessoas       AS qtd_total,',
'            i.local,',
'            i.valor_item',
'        FROM buf_item_solicitacao i',
'        JOIN buf_descricao d',
'          ON i.fk_id_desc = d.id_desc',
'       WHERE i.fk_id_solicitacao = :P1070_ID_SOLICITACAO',
'         AND i.status = ''Contratado''',
'       ORDER BY i.dat_servico, d.descricao',
'    )',
'    LOOP',
unistr('        -- conta hor\00E1rios para o item (para o rowspan)'),
'        SELECT COUNT(*)',
'          INTO v_qtd_horarios',
'          FROM buf_hor_item h',
'         WHERE h.fk_id_item = item.id_item;',
'',
'        IF v_qtd_horarios = 0 THEN',
'            v_qtd_horarios := 1;',
'        END IF;',
'',
'        v_primeiro := TRUE;',
'',
'        FOR h IN (',
'            SELECT hor, qtd_hor',
'              FROM buf_hor_item',
'             WHERE fk_id_item = item.id_item',
'             ORDER BY hor_minuto',
'        )',
'        LOOP',
'            v_mensagem := v_mensagem || ''<tr>'';',
'',
'            IF v_primeiro THEN',
'                -- colunas fixas com rowspan',
'                v_mensagem := v_mensagem ||',
'                    ''<td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;">'' ||',
'                        item.descricao || ''</td>',
'                     <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:center;">'' ||',
'                        TO_CHAR(item.dat_servico, ''DD/MM/YYYY'') || ''</td>',
'                     <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:center;">'' ||',
'                        NVL(TO_CHAR(item.qtd_total), ''-'') || ''</td>'';',
'            END IF;',
'',
unistr('            -- colunas vari\00E1veis por hor\00E1rio'),
'            v_mensagem := v_mensagem ||',
'                 ''<td style="padding:8px;border:1px solid #ddd;text-align:center;">'' ||',
'                     NVL(h.hor, ''-'') || ''</td>',
'                  <td style="padding:8px;border:1px solid #ddd;text-align:center;">'' ||',
'                     NVL(TO_CHAR(h.qtd_hor), ''-'') || ''</td>'';',
'',
'            IF v_primeiro THEN',
'                v_mensagem := v_mensagem ||',
'                    ''<td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;">'' ||',
'                        NVL(item.local, ''-'') || ''</td>',
'                     <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:right;">R$ '' ||',
'                        NVL(TO_CHAR(item.valor_item, ''FM999G999G990D00''), ''-'') || ''</td>'';',
'            END IF;',
'',
'            v_mensagem := v_mensagem || ''</tr>'';',
'            v_primeiro := FALSE;',
'        END LOOP;',
'',
unistr('        -- caso n\00E3o tenha nenhum registro em BUF_HOR_ITEM'),
'        IF v_primeiro THEN',
'            v_mensagem := v_mensagem ||',
'                ''<tr>',
'                    <td style="padding:8px;border:1px solid #ddd;">''||item.descricao||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">''||TO_CHAR(item.dat_servico,''DD/MM/YYYY'')||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">''||NVL(TO_CHAR(item.qtd_total), ''-'')||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">-</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">-</td>',
'                    <td style="padding:8px;border:1px solid #ddd;">''||NVL(item.local,''-'')||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:right;">R$ ''||',
'                        NVL(TO_CHAR(item.valor_item,''FM999G999G990D00''),''-'')||''</td>',
'                </tr>'';',
'        END IF;',
'    END LOOP;',
'',
'    v_mensagem := v_mensagem ||',
'        ''</table>',
'            <br>',
'',
'            <p>',
unistr('                A autoriza\00E7\00E3o emitida pelo Senac segue anexada para registro.'),
'            </p>',
'            <p>',
'                Atenciosamente,',
'            </p>',
'            <p>',
'                <b>'' || v_nome_resp || ''</b><br>',
'                '' || v_setor_resp || ''<br>',
unistr('                Assessoria de Qualidade de Atendimento e Log\00EDstica \2013 ASQUALOG<br>'),
'                Senado Federal',
'            </p>',
'            <p style="font-size:12px;color:#666;margin-top:20px;">',
unistr('                Este \00E9 um e-mail autom\00E1tico do Sistema de Buffet.'),
'            </p>',
'',
'            </body>',
'        </html>'';',
'    ',
'',
'    l_mail_id_dger := APEX_MAIL.SEND(',
'        -- p_to        => ''DGER@senado.leg.br'',',
'        -- p_cc        => v_email_cc,',
'        p_to        => ''marcelo.kobayashi@senado.leg.br'',',
'        p_from      => v_email_remetente,',
unistr('        p_subj      => ''Solicita\00E7\00E3o de Buffet'','),
'        p_body      => NULL,',
'        p_body_html => v_mensagem',
'    );',
'',
'    apex_mail.add_attachment(',
'        p_mail_id    => l_mail_id_dger,',
'        p_attachment => v_blob,',
'        p_filename   => v_filename,',
'        p_mime_type  => v_mimetype',
'    );',
'',
'    /*',
unistr('        In\00EDcio do email para o solicitante'),
'    */',
'',
'    v_email_cc := ''asqualog@senado.leg.br,sequalog-equipe@senado.gov.br'';',
'',
'    IF INSTR(v_email_solicitante, '','') > 0 THEN',
'        v_email_cc := v_email_cc || '','' ||',
'            SUBSTR(v_email_solicitante,',
'                   INSTR(v_email_solicitante, '','') + 1);',
'    END IF;',
'',
'    v_mensagem :=',
'    ''<html>',
'        <body style="font-family: Arial, Helvetica, sans-serif; font-size:14px; color:#333;">',
'',
'        <p>Prezado(a),</p>',
'',
'        <p>',
unistr('        Informamos que a an\00E1lise do Senac da solicita\00E7\00E3o de buffet referente ao evento'),
unistr('        <b>'' || v_evento || ''</b> foi conclu\00EDda. Aquelas contratadas est\00E3o sob an\00E1lise da Diretoria-Geral.'),
'        </p>',
'',
'        <p>',
unistr('        Abaixo constam todos os servi\00E7os solicitados e o respectivo status de cada um. Observe que as quantidades podem ter sido alteradas.'),
'        </p>',
'',
'        <p>',
'        <b>Evento:</b> '' || v_evento || ''<br>',
'        <b>Unidade Solicitante:</b> '' || v_setor_solicitante || ''',
'        </p>',
'',
'        <table style="',
'        border-collapse:collapse;',
'        width:100%;',
'        max-width:900px;',
'        margin-top:10px;',
'        border:1px solid #ddd;',
'        ">',
'',
'        <tr style="background-color:#f2f2f2;">',
unistr('            <th style="padding:8px;border:1px solid #ddd;">Servi\00E7o</th>'),
'            <th style="padding:8px;border:1px solid #ddd;">Data</th>',
unistr('            <th style="padding:8px;border:1px solid #ddd;">N\00BA Pessoas</th>'),
unistr('            <th style="padding:8px;border:1px solid #ddd;">Hor\00E1rio</th>'),
unistr('            <th style="padding:8px;border:1px solid #ddd;">Qtd/Hor\00E1rio</th>'),
'            <th style="padding:8px;border:1px solid #ddd;">Local</th>',
'            <th style="padding:8px;border:1px solid #ddd;">Valor</th>',
'            <th style="padding:8px;border:1px solid #ddd;">Status</th>',
'        </tr>'';',
'    ',
'    FOR item IN (',
'        SELECT',
'            i.id_item,',
'            d.descricao,',
'            i.dat_servico,',
'            i.qtd_pessoas AS qtd_total,',
'            i.local,',
'            i.valor_item,',
'            CASE',
unistr('                WHEN i.status = ''Contratado'' THEN ''Sob an\00E1lise da DGER'''),
'                WHEN i.status = ''Cancelado'' THEN i.status',
'            END AS status',
'        FROM buf_item_solicitacao i',
'        JOIN buf_descricao d',
'          ON d.id_desc = i.fk_id_desc',
'        WHERE i.fk_id_solicitacao = :P1070_ID_SOLICITACAO',
'        ORDER BY i.dat_servico, d.descricao',
'    )',
'    LOOP',
unistr('        -- conta hor\00E1rios para o item (para o rowspan)'),
'        SELECT COUNT(*)',
'          INTO v_qtd_horarios',
'          FROM buf_hor_item h',
'         WHERE h.fk_id_item = item.id_item;',
'',
'        IF v_qtd_horarios = 0 THEN',
'            v_qtd_horarios := 1;',
'        END IF;',
'',
'        v_primeiro := TRUE;',
'',
'        FOR h IN (',
'            SELECT hor, qtd_hor',
'              FROM buf_hor_item',
'             WHERE fk_id_item = item.id_item',
'             ORDER BY hor_minuto',
'        )',
'        LOOP',
'            v_mensagem := v_mensagem || ''<tr>'';',
'',
'            IF v_primeiro THEN',
'                -- colunas fixas com rowspan',
'                v_mensagem := v_mensagem ||',
'                    ''<td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;">'' ||',
'                        item.descricao || ''</td>',
'                     <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:center;">'' ||',
'                        TO_CHAR(item.dat_servico, ''DD/MM/YYYY'') || ''</td>',
'                     <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:center;">'' ||',
'                        NVL(TO_CHAR(item.qtd_total), ''-'') || ''</td>'';',
'            END IF;',
'',
unistr('            -- colunas vari\00E1veis por hor\00E1rio'),
'            v_mensagem := v_mensagem ||',
'                 ''<td style="padding:8px;border:1px solid #ddd;text-align:center;">'' ||',
'                     NVL(h.hor, ''-'') || ''</td>',
'                  <td style="padding:8px;border:1px solid #ddd;text-align:center;">'' ||',
'                     NVL(TO_CHAR(h.qtd_hor), ''-'') || ''</td>'';',
'',
'            IF v_primeiro THEN',
'                v_mensagem := v_mensagem ||',
'                    ''<td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;">'' ||',
'                        NVL(item.local, ''-'') || ''</td>',
'                     <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:right;">R$ '' ||',
'                        NVL(TO_CHAR(item.valor_item, ''FM999G999G990D00''), ''-'') || ''</td>',
'                     <td rowspan="''||v_qtd_horarios||''" style="padding:8px;border:1px solid #ddd;text-align:center;">'' ||',
'                        item.status || ''</td>'';',
'            END IF;',
'',
'            v_mensagem := v_mensagem || ''</tr>'';',
'            v_primeiro := FALSE;',
'        END LOOP;',
'',
unistr('        -- caso n\00E3o tenha nenhum registro em BUF_HOR_ITEM'),
'        IF v_primeiro THEN',
'            v_mensagem := v_mensagem ||',
'                ''<tr>',
'                    <td style="padding:8px;border:1px solid #ddd;">''||item.descricao||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">''||TO_CHAR(item.dat_servico,''DD/MM/YYYY'')||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">''||NVL(TO_CHAR(item.qtd_total), ''-'')||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">-</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:center;">-</td>',
'                    <td style="padding:8px;border:1px solid #ddd;">''||NVL(item.local,''-'')||''</td>',
'                    <td style="padding:8px;border:1px solid #ddd;text-align:right;">R$ ''||',
'                        NVL(TO_CHAR(item.valor_item,''FM999G999G990D00''),''-'')||''</td>',
'                    <td rowspan="''||v_qtd_horarios||''" style="',
'                        padding:8px;',
'                        border:1px solid #ddd;',
'                        text-align:center;',
'                        font-weight:bold;',
'                        background-color:'' ||',
'                        CASE',
unistr('                            WHEN item.status = ''Sob an\00E1lise da DGER'' THEN ''#d4edda'''),
'                            WHEN item.status = ''Cancelado'' THEN ''#f8d7da''',
'                            ELSE ''#ffffff''',
'                        END ||',
'                        '';'' ||',
'                        item.status ||',
'                    ''</td>;',
'                </tr>'';',
'        END IF;',
'    END LOOP;',
'',
'    v_mensagem := v_mensagem ||',
'        ''</table>',
'',
'        <br>',
'',
'        <p>',
unistr('        Segue em anexo a autoriza\00E7\00E3o emitida pelo Senac.'),
'        </p>',
'',
'        <p>',
'        Atenciosamente,',
'        </p>',
'',
'        <p>',
'        <b>'' || v_nome_resp || ''</b><br>',
'        '' || v_setor_resp || ''<br>',
unistr('        Assessoria de Qualidade de Atendimento e Log\00EDstica \2013 ASQUALOG<br>'),
'        Senado Federal',
'        </p>',
'',
'        <p style="font-size:12px;color:#666;margin-top:20px;">',
unistr('        Este \00E9 um e-mail autom\00E1tico do Sistema de Buffet.'),
'        </p>',
'',
'        </body>',
'    </html>'';',
'',
'    l_mail_id_solicitante := APEX_MAIL.SEND(',
'        -- p_to        => REGEXP_SUBSTR(v_email_solicitante, ''[^,]+'', 1, 1),',
'        -- p_cc        => v_email_cc,',
'        p_to        => ''marcelo.kobayashi@senado.leg.br'',',
'        p_from      => v_email_remetente,',
unistr('        p_subj      => ''Solicita\00E7\00E3o de Buffet - Resultado da An\00E1lise'','),
'        p_body      => NULL,',
'        p_body_html => v_mensagem',
'    );',
'',
'    apex_mail.add_attachment(',
'        p_mail_id    => l_mail_id_solicitante,',
'        p_attachment => v_blob,',
'        p_filename   => v_filename,',
'        p_mime_type  => v_mimetype',
'    );',
'',
'    APEX_MAIL.PUSH_QUEUE;',
'',
'    UPDATE buf_solicitacao s',
'    SET ind_excecao = ''N''',
'    WHERE s.id_solicitacao = :P1070_ID_SOLICITACAO;',
'',
'    UPDATE buf_item_solicitacao',
unistr('    SET status = ''Em negocia\00E7\00E3o'''),
'    WHERE fk_id_solicitacao = :P1070_ID_SOLICITACAO',
'        AND status = ''Contratado'';',
'',
'    UPDATE buf_item_solicitacao',
'    SET ind_negado_senac = ''S''',
'    WHERE fk_id_solicitacao = :P1070_ID_SOLICITACAO',
'        AND status = ''Cancelado'';',
'    ',
'    COMMIT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>252287900453378520
);
end;
