wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(266973911833017450)
,p_event_id=>wwv_flow_imp.id(266973482651017447)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_valor_item    NUMBER;',
'    v_qtd           NUMBER;',
'    v_valor         NUMBER;',
'BEGIN',
'    SELECT d.valor ',
'    INTO v_valor_item',
'    FROM buf_descricao d',
'    JOIN buf_item_solicitacao i ON i.fk_id_desc = d.id_desc',
'    WHERE i.id_item = :P1071_ID_ITEM;',
'',
'    v_qtd := :P1071_QTD;',
'',
'    v_valor := v_valor_item * v_qtd;',
'',
'    :P1071_VALOR := ''R$ '' || TO_CHAR(v_valor, ''FM999G999G999D00'', ''NLS_NUMERIC_CHARACTERS = '''',.'''''');',
'END;'))
,p_attribute_02=>'P1071_ID_ITEM,P1071_QTD'
,p_attribute_03=>'P1071_VALOR'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(266974481481017451)
,p_event_id=>wwv_flow_imp.id(266973482651017447)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_REFRESH'
,p_affected_elements_type=>'ITEM'
,p_affected_elements=>'P1071_VALOR'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(266973098009017445)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Confirmar o item'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_qtd_antiga        NUMBER;',
'    v_qtd_nova          NUMBER := :P1071_QTD;',
'',
'    v_diferenca         NUMBER;',
'    v_fk_id_desc        NUMBER;',
'    ',
'    v_qtd_disponivel    NUMBER;',
'    v_qtd_maxima        NUMBER;',
'',
'    v_valor_unitario    NUMBER;',
'    v_valor_item        NUMBER;',
'BEGIN',
'    FOR i IN 1 .. APEX_APPLICATION.G_F01.COUNT LOOP',
'        UPDATE buf_hor_item',
'        SET qtd_hor = TO_NUMBER(APEX_APPLICATION.G_F01(i))',
'        WHERE id_hor_item = APEX_APPLICATION.G_F02(i);',
'    END LOOP;',
'',
'    SELECT NVL(SUM(qtd_hor), 0) INTO v_qtd_nova',
'    FROM buf_hor_item',
'    WHERE fk_id_item = :P1071_ID_ITEM;',
'',
'    SELECT qtd_pessoas, fk_id_desc',
'    INTO v_qtd_antiga, v_fk_id_desc',
'    FROM buf_item_solicitacao',
'    WHERE id_item = :P1071_ID_ITEM;',
'',
'    SELECT qtd_disponivel, valor',
'    INTO v_qtd_disponivel, v_valor_unitario',
'    FROM buf_descricao',
'    WHERE id_desc = v_fk_id_desc;',
'',
'    v_qtd_maxima := v_qtd_antiga + v_qtd_disponivel;',
'',
'    IF v_qtd_nova > v_qtd_maxima THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
unistr('            ''Quantidade indispon\00EDvel. M\00E1ximo permitido: '' || v_qtd_maxima'),
'        );',
'    END IF;',
'',
'    v_diferenca := v_qtd_nova - v_qtd_antiga;',
'',
'    v_valor_item := v_qtd_nova * v_valor_unitario;',
'',
'    UPDATE buf_item_solicitacao',
'    SET status = ''Contratado'',',
'        qtd_pessoas = v_qtd_nova,',
'        valor_item = v_valor_item',
'    WHERE id_item = :P1071_ID_ITEM;',
'',
'    UPDATE buf_descricao',
'    SET qtd_disponivel = qtd_disponivel - v_diferenca',
'    WHERE id_desc = v_fk_id_desc;',
'',
'    COMMIT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(266968632724017410)
,p_internal_uid=>266973098009017445
);
end;
